window.BANCO = window.BANCO || [];
window.BANCO.push({"id":"subvenciones","nombre":"Subvenciones (Ley 38/2003)","bloques":[{"id":"subv-general","nombre":"Subvenciones: disposiciones generales y beneficiarios (LGS, arts. 1 a 21)"},{"id":"subv-concesion","nombre":"Subvenciones: concesión y gestión (LGS, arts. 22 a 35)"},{"id":"subv-reintegro","nombre":"Subvenciones: reintegro y control financiero (LGS, arts. 36 a 51)"},{"id":"subv-sanciones","nombre":"Subvenciones: infracciones y sanciones (LGS, arts. 52 a 69)"}],"calendarios":{"oct2026":{"titulo":"Calendario octubre 2026","year":2026,"meses":[10],"festivos":["2026-10-12"],"nota":"Los domingos también van en rojo."},"feb2026":{"titulo":"Calendario febrero 2026","year":2026,"meses":[2],"festivos":[],"nota":"Los domingos también van en rojo."},"mar2024":{"titulo":"Calendario marzo 2024","year":2024,"meses":[3],"festivos":[],"nota":"Los domingos también van en rojo."},"oct2024":{"titulo":"Calendario octubre 2024","year":2024,"meses":[10],"festivos":[],"nota":"Los domingos también van en rojo."}},"casos":[{"id":"caso-60","titulo":"Bloque III.- Supuesto 24","texto":"Con fecha 13 de octubre de 2025, el Ministro de Cultura y Deporte dictó Orden Ministerial, publicada en el BOE del día siguiente, por la que se aprobaron las bases reguladoras de subvenciones para la modernización de las industrias culturales y creativas, las cuales se otorgarán en régimen de concurrencia competitiva.\nCon fecha 20 de noviembre de 2025, el Secretario de Estado de Cultura, órgano concedente de esta subvención, dictó la correspondiente resolución de convocatoria. El extracto de dicha convocatoria fue publicado en el BOE de 21 de noviembre, concediéndose un plazo de un mes para la presentación de solicitudes. Las bases reguladoras establecen un plazo de 6 meses para resolver.\nEl importe máximo imputable a la convocatoria será de 12.000.000 €. Las ayudas concedidas se sufragarán con los créditos de la aplicación 24.01.334C.772 del Presupuesto de Gastos del Ministerio de Cultura y Deporte para 2025.\nEl 1 de diciembre de 2025, el gestor administrativo de la mercantil Siglo XXI S.L., actuando en nombre y representación de esta, presentó solicitud en la oficina de asistencia en materia de registros del Ministerio de Cultura y Deporte.\nEl Subdirector General de Promoción de Industrias Culturales, órgano competente para la tramitación de las subvenciones, requirió al gestor administrativo de la mercantil Siglo XXI S.L., para que subsanara la solicitud a través de su presentación electrónica, advirtiéndole que, de no ser atendido el requerimiento en el plazo de cinco días, se le tendría por desistido de su solicitud.\nFinalmente, el representante de Siglo XXI S.L., presentó la solicitud en el Registro General Electrónico de la Administración General del Estado el 20 de diciembre de 2025, dentro del plazo concedido en el requerimiento. La resolución definitiva fue dictada dentro de plazo por el órgano competente, resultando la mercantil Siglo XXI S.L. beneficiaria de una subvención por importe de 125.000 euros.\nEn relación con el supuesto planteado, se formulan las siguientes preguntas:"},{"id":"test-54","titulo":"Ejercicio 22.- Tipos de Actividad","texto":"","corto":true,"ids":["pr-54-001","pr-54-002","pr-54-003","pr-54-004","pr-54-005","pr-54-006","pr-54-007","pr-54-008"]},{"id":"test-55","titulo":"Ejercicio 23.- Ámbito de aplicación.","texto":"","corto":true,"ids":["pr-55-001","pr-55-002","pr-55-003","pr-55-004","pr-55-005","pr-55-006","pr-55-007","pr-55-008","pr-55-009","pr-55-010"]},{"id":"test-56","titulo":"Ejercicio 24.- Titulo Preliminar","texto":"","corto":true,"ids":["pr-56-001","pr-56-002","pr-56-003","pr-56-004","pr-56-005","pr-56-006","pr-56-007","pr-56-008","pr-56-009","pr-56-010","pr-56-011","pr-56-012","pr-56-013","pr-56-014","pr-56-015","pr-56-016","pr-56-017","pr-56-018","pr-56-019","pr-56-020"]},{"id":"test-57","titulo":"Ejercicio 25.- Titulo I. Verdadero o Falso","texto":"","corto":true,"ids":["pr-57-001","pr-57-002","pr-57-003","pr-57-004","pr-57-005","pr-57-006","pr-57-007","pr-57-008","pr-57-009","pr-57-010","pr-57-011","pr-57-012","pr-57-013","pr-57-014","pr-57-015","pr-57-016","pr-57-017","pr-57-018","pr-57-019","pr-57-020"]},{"id":"test-58","titulo":"Ejercicio 26.- Infracciones","texto":"","corto":true,"ids":["pr-58-001","pr-58-002","pr-58-003","pr-58-004","pr-58-005","pr-58-006","pr-58-007","pr-58-008","pr-58-009","pr-58-010"]},{"id":"test-59","titulo":"Ejercicio 27.- Subvenciones en números","texto":"","corto":true,"ids":["pr-59-001","pr-59-002","pr-59-003","pr-59-004","pr-59-005","pr-59-006","pr-59-007","pr-59-008","pr-59-009","pr-59-010","pr-59-011","pr-59-012","pr-59-013","pr-59-014","pr-59-015","pr-59-016","pr-59-017","pr-59-018","pr-59-019","pr-59-020"]}],"preguntas":[{"id":"au-26-001","origen":"autoevaluacion","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":1,"enunciado":"¿Cuál de las siguientes actuaciones es propia de la actividad de policía de la Administración?","opciones":["La licencia de apertura de un establecimiento de hostelería.","Una subvención a una asociación agraria para limitar la proliferación de plagas.","La prestación de un servicio de transporte regular limitado.","Las bonificaciones en la cotización de formación profesional de la Seguridad Social."],"bloque":"subv-general","precepto":"Formas de actividad administrativa: policía, servicio público y fomento","correcta":0,"justificaciones":["Es esta. En la actividad de **policía** la Administración limita o condiciona lo que pueden hacer los particulares para proteger el interés general: autorizaciones, licencias, sanciones. Abrir un bar exige licencia previa.","No. Una subvención es actividad de **fomento**: se ayuda para animar una conducta, no se limita.","No. Prestar un servicio de transporte regular es **servicio público**: la Administración presta algo a los ciudadanos.","No. Las bonificaciones en la cotización son un incentivo económico, es decir, actividad de **fomento**."],"ojo":"Truco: si limita o exige permiso, policía. Si presta algo, servicio público. Si incentiva o premia, fomento."},{"id":"au-26-002","origen":"autoevaluacion","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":2,"enunciado":"Indique cuál de las siguientes respuestas se refiere a una actividad administrativa de servicio público:","opciones":["Concesión de una licencia para realizar una obra menor.","Apertura de un hospital por parte del Ministerio de Sanidad.","Concesión de una beca por parte del Ministerio de Educación.","Premios principe de Asturias."],"bloque":"subv-general","precepto":"Formas de actividad administrativa: policía, servicio público y fomento","correcta":1,"justificaciones":["No. Conceder una licencia es actividad de **policía**: la Administración autoriza algo que un particular quiere hacer.","Es esta. Abrir y gestionar un hospital es **servicio público**: la Administración presta directamente una prestación a los ciudadanos, en este caso asistencia sanitaria.","No. Una beca es una ayuda para que alguien estudie, es decir, actividad de **fomento**.","No. Un premio reconoce y estimula una conducta ejemplar: es actividad de **fomento** (en su forma honorífica)."]},{"id":"au-26-003","origen":"autoevaluacion","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":3,"enunciado":"Señale cuál de los siguientes NO es uno de los requisitos de las subvenciones, conforme al artículo 2 de la LGS:","opciones":["Que la entrega se realice con contraprestación directa del beneficiario.","Que la entrega esté sujeta al cumplimiento de un determinado objetivo.","Que el proyecto tenga por objeto el fomento de una actividad de utilidad pública o interés social.","Que la entrega se realice sin contraprestación directa de los beneficiarios."],"bloque":"subv-general","precepto":"Art. 2.1 de la Ley 38/2003","correcta":0,"justificaciones":["Esta es la falsa, y por eso es la que hay que marcar. El **art. 2.1.a** exige justo lo contrario: que la entrega se haga **sin** contraprestación directa del beneficiario. Si hay contraprestación, es un contrato, no una subvención.","Es verdadera, así que no se marca. Es el **art. 2.1.b**: la entrega está sujeta a un objetivo, proyecto, actividad, comportamiento o situación.","Es verdadera, así que no se marca. Es el **art. 2.1.c**: lo financiado debe fomentar una actividad de utilidad pública o interés social.","Es verdadera, así que no se marca. Es el **art. 2.1.a**: sin contraprestación directa."],"ojo":"Las opciones 0 y 3 dicen lo contrario una de la otra. Cuando pasa eso, una de las dos suele ser la respuesta."},{"id":"au-26-004","origen":"autoevaluacion","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":4,"enunciado":"Indique cuál de las siguientes respuestas se refiere a una actividad administrativa de fomento:","opciones":["La ejecución de las obras de un colegio por parte de la Junta de Andalucía.","La concesión de una licencia para la ocupación del dominio público por parte de un Ayuntamiento.","Autorización de residencia para extranjeros.","Exoneración de cuotas a la seguridad social por contratar a trabajadores con un grado de discapacidad."],"bloque":"subv-general","precepto":"Formas de actividad administrativa: policía, servicio público y fomento","correcta":3,"justificaciones":["No. Construir un colegio es una prestación a los ciudadanos, es decir, **servicio público**.","No. Autorizar la ocupación del dominio público es una autorización administrativa, propia de la actividad de **policía**.","No. La autorización de residencia es una autorización previa, otra vez actividad de **policía**.","Es esta. Exonerar de cuotas a quien contrata a personas con discapacidad es un incentivo económico para animar esa conducta: actividad de **fomento**."]},{"id":"au-26-005","origen":"autoevaluacion","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":5,"enunciado":"Señale la respuesta incorrecta. De acuerdo con el artículo 2 de la LGS, no tienen carácter de subvenciones:","opciones":["Los beneficios fiscales y beneficios en la cotización a la Seguridad Social.","Las disposiciones dinerarias realizadas a favor de personas públicas o privadas que cumplan determinados requisitos.","Las prestaciones contributivas y no contributivas del Sistema de la Seguridad Social.","Las prestaciones reconocidas por el Fondo de Garantía Salarial."],"bloque":"subv-general","precepto":"Art. 2.4 de la Ley 38/2003","correcta":1,"justificaciones":["Es verdadera, así que no se marca. Los beneficios fiscales y los beneficios en la cotización a la Seguridad Social están excluidos en el **art. 2.4.g**.","Esta es la falsa, y por eso es la que hay que marcar. Es casi la definición de subvención del **art. 2.1**: disposición dineraria a favor de personas públicas o privadas que cumplen unos requisitos. Sí tiene carácter de subvención.","Es verdadera, así que no se marca. Las prestaciones contributivas y no contributivas de la Seguridad Social están excluidas en el **art. 2.4.a**.","Es verdadera, así que no se marca. Las prestaciones del Fondo de Garantía Salarial están excluidas en el **art. 2.4.f**."]},{"id":"au-26-006","origen":"autoevaluacion","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":6,"enunciado":"¿Cuál de los siguientes supuestos tiene carácter de subvención de acuerdo a la Ley 38/2003, General de Subvenciones?","opciones":["Los premios que se otorguen previa solicitud del beneficiario.","Las prestaciones no contributivas del Sistema de Seguridad Social.","Las prestaciones contributivas del Sistema de Seguridad Social.","Los beneficios fiscales y beneficios en la cotización a la Seguridad Social."],"bloque":"subv-general","precepto":"Arts. 2.4 y 4.a de la Ley 38/2003","correcta":0,"justificaciones":["Es esta. El **art. 4.a** deja fuera de la ley solo los premios que se otorgan **sin** que el beneficiario los haya pedido. Si el premio se concede previa solicitud, no queda excluido y entra en el régimen de la Ley.","No. Las prestaciones no contributivas de la Seguridad Social no tienen carácter de subvención (**art. 2.4.a**).","No. Las contributivas tampoco: están en el mismo **art. 2.4.a**.","No. Los beneficios fiscales y los de cotización a la Seguridad Social están excluidos en el **art. 2.4.g**."],"ojo":"Los premios van por la solicitud: sin solicitud, excluidos de la ley. Con solicitud, dentro."},{"id":"au-26-007","origen":"autoevaluacion","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":7,"enunciado":"¿Cuál de las siguientes subvenciones no está excluida de la aplicación de la Ley General de Subvenciones?","opciones":["Las subvenciones para la financiación de los partidos políticos.","Las subvenciones previstas nominativamente en los Presupuestos Generales de cada Administración pública.","Las subvenciones previstas en la Ley Orgánica de Régimen Electoral.","Los premios que se otorguen sin la previa solicitud del beneficiario."],"bloque":"subv-general","precepto":"Arts. 4 y 22.2.a de la Ley 38/2003","correcta":1,"justificaciones":["No. Las subvenciones de la Ley Orgánica de Financiación de los Partidos Políticos están excluidas en el **art. 4.c**.","Es esta. Las subvenciones previstas nominativamente en los Presupuestos no están excluidas: se conceden de forma directa, pero siguen sujetas a la ley (**art. 22.2.a**).","No. Las subvenciones de la Ley Orgánica del Régimen Electoral General están excluidas en el **art. 4.b**.","No. Los premios otorgados sin solicitud previa están excluidos en el **art. 4.a**."]},{"id":"au-26-008","origen":"autoevaluacion","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":8,"enunciado":"Las prestaciones contributivas y no contributivas del Sistema de la Seguridad Social:","opciones":["Solo las contributivas tienen carácter de subvenciones a efectos de la Ley 38/2003.","Solo las no contributivas tienen carácter de subvenciones a efectos de la Ley 38/2003.","No tienen carácter de subvenciones.","Tienen carácter de subvenciones a efectos de la Ley 38/2003."],"bloque":"subv-general","precepto":"Art. 2.4.a de la Ley 38/2003","correcta":2,"justificaciones":["No. Ni las contributivas ni las no contributivas son subvenciones. El **art. 2.4.a** las excluye a las dos.","No. Tampoco solo las no contributivas: el **art. 2.4.a** habla de ambas.","Es esta. El **art. 2.4.a** dice que las prestaciones contributivas y no contributivas del Sistema de la Seguridad Social no tienen carácter de subvenciones.","No. Es justo lo contrario de lo que dice el **art. 2.4.a**."]},{"id":"au-26-009","origen":"autoevaluacion","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":9,"enunciado":"¿Cuál de los siguientes medios es un ejemplo de actividad de fomento?","opciones":["Servicio de transporte público.","Multas administrativas.","Licencias de obra.","Condecoraciones y títulos."],"bloque":"subv-general","precepto":"Formas de actividad administrativa: policía, servicio público y fomento","correcta":3,"justificaciones":["No. El transporte público es un **servicio público**: la Administración presta algo a los ciudadanos.","No. Las multas son sanciones, propias de la actividad de **policía**.","No. Las licencias de obra son autorizaciones previas: **policía**.","Es esta. Condecoraciones y títulos son fomento en su forma **honorífica**: se reconoce a quien actúa de forma ejemplar para animar a los demás."]},{"id":"au-26-010","origen":"autoevaluacion","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":10,"enunciado":"¿Cuál es la finalidad principal de la actividad de fomento de la Administración?","opciones":["Mantener el orden público.","Dirigir la acción de los particulares hacía fines de interés general.","Suministrar prestaciones a los particulares.","Reprimir conductas contrarias a la ley."],"bloque":"subv-general","precepto":"Exposición de motivos de la Ley 38/2003","correcta":1,"justificaciones":["No. Mantener el orden público es actividad de **policía**.","Es esta. El **fomento** busca dirigir la acción de los particulares hacia fines de interés general sin obligarles, con incentivos. La exposición de motivos de la ley lo dice de las subvenciones: son una técnica de fomento de comportamientos de interés general.","No. Suministrar prestaciones a los particulares es **servicio público**.","No. Reprimir conductas contrarias a la ley es actividad de **policía**, en su forma sancionadora."]},{"id":"au-26-011","origen":"autoevaluacion","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":11,"enunciado":"¿Cuál de los siguientes no es un requisito para que una disposición dineraria sea considerada subvención?","opciones":["Que la otorgue una persona física o jurídica.","Que se entregue sin contraprestación directa.","Tener por objeto el fomento de una actividad de utilidad pública o interés social.","Que la entrega esté sujeta al cumplimiento de un determinado objetivo."],"bloque":"subv-general","precepto":"Art. 2.1 de la Ley 38/2003","correcta":0,"justificaciones":["Esta es la falsa, y por eso es la que hay que marcar. El **art. 2.1** no habla de cualquier persona física o jurídica: la disposición debe hacerla alguno de los sujetos del **art. 3** (las Administraciones públicas y los entes que la ley enumera). Un particular que regala dinero no da una subvención.","Es verdadera, así que no se marca. Es el **art. 2.1.a**: sin contraprestación directa.","Es verdadera, así que no se marca. Es el **art. 2.1.c**: fomento de una actividad de utilidad pública o interés social.","Es verdadera, así que no se marca. Es el **art. 2.1.b**: sujeta al cumplimiento de un objetivo, proyecto o situación."]},{"id":"au-26-012","origen":"autoevaluacion","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":12,"enunciado":"Señale la respuesta incorrecta. Según el articulo 2 de la LGS, no tendrán carácter de subvención:","opciones":["Las prestaciones a favor de afectados por el virus de inmunodeficiencia humana.","Subvención a los intereses del crédito oficial.","Las ayudas económicas concedidas a víctimas de violencia de género.","Los beneficios fiscales."],"bloque":"subv-general","precepto":"Art. 2.4.h de la Ley 38/2003","correcta":1,"justificaciones":["Es verdadera, así que no se marca. Las prestaciones a favor de afectados por el virus de inmunodeficiencia humana están excluidas en el **art. 2.4.c**.","Esta es la falsa, y por eso es la que hay que marcar. El **art. 2.4.h** excluye el crédito oficial, salvo cuando la Administración subvenciona al prestatario los intereses de la operación de crédito. En ese caso sí es subvención.","Es verdadera, así que no se marca. Las ayudas a víctimas de violencia de género están excluidas en el **art. 2.4.i**.","Es verdadera, así que no se marca. Los beneficios fiscales están excluidos en el **art. 2.4.g**."],"ojo":"El crédito oficial no es subvención, pero subvencionar sus intereses sí lo es. Es la excepción a la regla."},{"id":"au-26-013","origen":"autoevaluacion","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":13,"enunciado":"Las subvenciones previstas en la Ley Orgánica del Régimen Electoral General, según el artículo 4 de la Ley 38/2003, ¿están incluidas en el ámbito de aplicación de dicha ley?","opciones":["Sí están incluidas.","Les será de aplicación el Real Decreto 887/2006, de 21 de julio.","No tienen carácter de subvención.","Están excluidas del ámbito de aplicación."],"bloque":"subv-general","precepto":"art. 4.b","correcta":3,"justificaciones":["No. Están excluidas, no incluidas (**art. 4.b**).","No. Si están excluidas, no se les aplica la Ley (**art. 4.b**).","No. Siguen siendo subvenciones, pero la Ley las excluye de su ámbito (**art. 4.b**).","Es esta. Las subvenciones de la Ley Orgánica del Régimen Electoral General están excluidas del ámbito de la Ley (**art. 4.b**)."]},{"id":"au-26-014","origen":"autoevaluacion","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":14,"enunciado":"De acuerdo con la Ley 38/2003, de 17 de noviembre, quedan incluidas dentro del ámbito de la Ley:","opciones":["La subvención otorgada a un grupo parlamentario del Congreso de las Diputados.","Las subvenciones reguladas en la Ley Orgánica de Financiación de los Partidos Políticos.","Las subvenciones en régimen de concurrencia competitiva.","Los premios que se otorguen sin previa solicitud del beneficiario"],"bloque":"subv-general","precepto":"art. 22.1","correcta":2,"justificaciones":["No. Las subvenciones a los grupos parlamentarios están excluidas (**art. 4.d**).","No. Las de la Ley Orgánica de Financiación de los Partidos Políticos están excluidas (**art. 4.c**).","Es esta. La concurrencia competitiva es el procedimiento ordinario de concesión de subvenciones dentro de la Ley (**art. 22.1**).","No. Los premios sin solicitud previa están excluidos (**art. 4.a**)."]},{"id":"au-26-015","origen":"autoevaluacion","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":15,"enunciado":"No están comprendidas en el ámbito de aplicación de la Ley 38/2003:","opciones":["Las subvenciones entre Administraciones públicas.","Las subvenciones previstas en los presupuestos Generales del Estado.","Los premios que se otorguen a solicitud del beneficiario.","Las aportaciones dinerarias entre los distintos agentes de una Administración, siempre que no resulten de una convocatoria pública."],"bloque":"subv-general","precepto":"art. 2.2","correcta":3,"justificaciones":["No. Solo quedan fuera las aportaciones que financian globalmente la actividad de otra Administración, no todas las subvenciones entre Administraciones (**art. 2.2**).","No. Las subvenciones de los Presupuestos Generales sí están dentro de la Ley (**art. 3**).","No. Solo están excluidos los premios sin solicitud, no los que se otorgan a solicitud (**art. 4.a**).","Es esta. Las aportaciones entre agentes de una misma Administración sin convocatoria pública quedan fuera de la Ley (**art. 2.2**)."]},{"id":"au-26-016","origen":"autoevaluacion","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":16,"enunciado":"De acuerdo con el artículo 5 de la LGS, las subvenciones otorgadas por consorcios o mancomunidades se regularán:","opciones":["Por el instrumento jurídico de creación, debiendo ajustarse a las disposiciones contenidas en esta ley.","Por las normas de derecho administrativo.","Por el reglamento orgánico del consorcio.","Exclusivamente por esta Ley."],"bloque":"subv-general","precepto":"art. 5.2","correcta":0,"justificaciones":["Es esta. Se regulan por el instrumento jurídico de creación, que debe ajustarse a la Ley (**art. 5.2**).","No. No se rigen por las normas de derecho administrativo en general, sino por su instrumento de creación (**art. 5.2**).","No. El reglamento orgánico no es el instrumento que cita la ley (**art. 5.2**).","No. “Exclusivamente” es falso: rige el instrumento de creación, adaptado a la Ley (**art. 5.2**)."]},{"id":"au-26-017","origen":"autoevaluacion","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":17,"enunciado":"Según el artículo 6 de la LGS, las subvenciones financiadas con fondos de la Unión Europea se rigen por:","opciones":["La Ley 38/2003 exclusivamente.","Las normas comunitarias y, en su caso, las nacionales de desarrollo.","El reglamento del Fondo Europeo correspondiente.","El derecho internacional."],"bloque":"subv-general","precepto":"art. 6.1","correcta":1,"justificaciones":["No. “Exclusivamente” es falso: la Ley 38/2003 es solo supletoria (**art. 6.2**).","Es esta. Se rigen por las normas comunitarias aplicables y por las normas nacionales de desarrollo o transposición (**art. 6.1**).","No. No se rigen solo por el reglamento de un fondo concreto: también por las normas nacionales de desarrollo (**art. 6.1**).","No. El derecho internacional no es el régimen que fija la ley (**art. 6.1**)."]},{"id":"au-26-018","origen":"autoevaluacion","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":18,"enunciado":"¿Cuál de las siguientes afirmaciones permite distinguir la actividad de fomento de la actividad de servicio público?","opciones":["En el fomento la Administración utiliza siempre medios económicos, mientras que en el servicio público utiliza únicamente medios jurídicos.","En el servicio público la Administración realiza directamente el fin perseguido con sus propios medios, mientras que en el fomento estimula a los particulares para que lo cumplan indirectamente.","En el fomento la Administración actúa mediante coacción, mientras que en el servicio público nunca existe intervención administrativa.","En el servicio público los particulares realizan voluntariamente el fin perseguido, mientras que en el fomento lo realiza directamente la Administración."],"bloque":"subv-general","precepto":"doctrina (fomento y servicio público)","correcta":1,"justificaciones":["No. Es falso: el fomento no usa siempre medios económicos, y el servicio público también emplea medios jurídicos.","Es esta. En el servicio público la Administración presta ella misma la actividad, y en el fomento incentiva a los particulares para que la hagan.","No. El fomento no actúa por coacción: estimula, no impone.","No. Está invertido: en el servicio público presta la Administración, en el fomento los particulares."],"ojo":"La Ley 38/2003 no define esta distinción. Es doctrina general sobre las formas de la actividad administrativa."},{"id":"au-26-019","origen":"autoevaluacion","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":19,"enunciado":"Una Administración concede a una persona una subvención para que realice una actividad considerada de interés social. Conforme al artículo 2 de la Ley 38/2003, para que pueda hablarse de subvención, la entrega dineraria debe realizarse:","opciones":["Siempre a cambio de una contraprestación directa del beneficiario.","Sin contraprestación directa del beneficiario y sujeta al cumplimiento de un determinado objetivo, proyecto, actividad, comportamiento o situación.","Exclusivamente a personas físicas y para actividades ya realizadas.","Únicamente cuando exista una prestación de servicios a favor de la Administración."],"bloque":"subv-general","precepto":"art. 2.1","correcta":1,"justificaciones":["No. La subvención se entrega sin contraprestación directa del beneficiario (**art. 2.1.a**).","Es esta. Sin contraprestación directa y sujeta a un objetivo, proyecto, actividad, comportamiento o situación (**art. 2.1.a y b**).","No. Pueden ser personas públicas o privadas, y para actividades ya realizadas o por desarrollar (**art. 2.1**).","No. No exige prestación de servicios a la Administración, que sería contraprestación (**art. 2.1.a**)."]},{"id":"au-26-020","origen":"autoevaluacion","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":20,"enunciado":"¿Cuál de las siguientes aportaciones dinerarias no está comprendida en el ámbito de aplicación de la Ley 38/2003, conforme al artículo 2?","opciones":["Una subvención concedida a una empresa privada para desarrollar un proyecto de interés social.","Una aportación dineraria entre diferentes Administraciones públicas destinada a financiar globalmente la actividad de la Administración receptora.","Una subvención concedida por una entidad local a una asociación para desarrollar una actividad cultural.","Una ayuda económica condicionada a la realización de una determinada actividad de utilidad pública."],"bloque":"subv-general","precepto":"art. 2.2","correcta":1,"justificaciones":["No. Una subvención a una empresa privada para un proyecto de interés social está dentro de la Ley (**art. 2.1**).","Es esta. Las aportaciones entre Administraciones para financiar globalmente la actividad de la receptora quedan fuera de la Ley (**art. 2.2**).","No. La subvención de una entidad local a una asociación está dentro de la Ley (**art. 3.1.b**).","No. Una ayuda condicionada a una actividad de utilidad pública cumple el concepto de subvención (**art. 2.1**)."]},{"id":"au-27-001","origen":"autoevaluacion","test":"Tema 5 (2) - LGS (arts 8 a 20)","n":1,"enunciado":"Según la LGS, los órganos competentes para la concesión de subvenciones en la Administración General del Estado son:","opciones":["Los Subsecretarios y los Secretarios Generales.","Los Secretarios de Estado y los Subsecretarios.","Los Ministros y los Secretarios de Estado.","El Presidente del Gobierno y los Ministros."],"bloque":"subv-general","precepto":"art. 10.1","correcta":2,"justificaciones":["No. Los Subsecretarios y Secretarios Generales no son los órganos competentes que cita la ley (**art. 10.1**).","No. Los Subsecretarios no figuran en el art. 10.1.","Es esta. En la AGE conceden los Ministros y los Secretarios de Estado (**art. 10.1**).","No. El Presidente del Gobierno no concede subvenciones (**art. 10.1**)."]},{"id":"au-27-002","origen":"autoevaluacion","test":"Tema 5 (2) - LGS (arts 8 a 20)","n":2,"enunciado":"Las bases reguladoras para concesión de subvenciones, en el ámbito de la Administración General del Estado, se aprueban por:","opciones":["Real Decreto.","Ley de Bases.","Orden Ministerial.","Resolución del órgano concedente."],"bloque":"subv-general","precepto":"art. 17.1","correcta":2,"justificaciones":["No. Las bases se aprueban por orden ministerial, no por Real Decreto (**art. 17.1**).","No. “Ley de Bases” no es el instrumento (**art. 17.1**).","Es esta. Se aprueban por orden ministerial, con informe de los servicios jurídicos y de la Intervención Delegada (**art. 17.1**).","No. No las aprueba el propio órgano concedente por resolución (**art. 17.1**)."]},{"id":"au-27-003","origen":"autoevaluacion","test":"Tema 5 (2) - LGS (arts 8 a 20)","n":3,"enunciado":"La gestión de subvenciones a que se refiere la LGS se realizará de acuerdo con los siguientes principios:","opciones":["Publicidad, transparencia, concurrencia, objetividad, igualdad y no discriminación.","Eficacia en el cumplimiento de los objetivos fijados por la Administración otorgante.","Eficiencia en la asignación y utilización de los recursos públicos.","Todas son correctas."],"bloque":"subv-general","precepto":"art. 8.3","correcta":3,"justificaciones":["No. Es cierta, pero no es el único principio (**art. 8.3**).","No. Es cierta, pero no es el único principio (**art. 8.3**).","No. Es cierta, pero no es el único principio (**art. 8.3**).","Es esta. Los tres grupos de principios del art. 8.3 son correctos."]},{"id":"au-27-004","origen":"autoevaluacion","test":"Tema 5 (2) - LGS (arts 8 a 20)","n":4,"enunciado":"En relación con la financiación de las actividades subvencionadas y según el artículo 19 de la LGS:","opciones":["La normativa reguladora de la subvención no podrá exigir un importe de financiación propia para cubrir la actividad subvencionada.","La determinación del importe de la subvención en ningún caso debe calcularse como un porcentaje del coste de la actividad.","El importe de las subvenciones en ningún caso podrá superar el coste de la actividad subvencionada.","La percepción de una subvención es incompatible, en todo caso, con la obtención de otras ayudas para la misma finalidad."],"bloque":"subv-general","precepto":"art. 19.3","correcta":2,"justificaciones":["No. La normativa sí podrá exigir un importe de financiación propia (**art. 19.1**).","No. El importe puede calcularse como porcentaje del coste de la actividad.","Es esta. El importe de la subvención no puede superar el coste de la actividad subvencionada, ni aislada ni con otras ayudas (**art. 19.3**).","No. La compatibilidad la determina la normativa reguladora, no es incompatible en todo caso (**art. 19.2**)."]},{"id":"au-27-005","origen":"autoevaluacion","test":"Tema 5 (2) - LGS (arts 8 a 20)","n":5,"enunciado":"No podrán ser entidades colaboradoras en la gestión de subvenciones públicas según la Ley 38/2003, General de subvenciones:","opciones":["Las sociedades mercantiles participadas integra o mayoritariamente por las Administraciones Públicas.","Las Corporaciones Locales.","Las personas o entidades que no se hallen al corriente de sus obligaciones tributarias.","Los Organismos Autónomos."],"bloque":"subv-general","precepto":"art. 13.2.e","correcta":2,"justificaciones":["No. Las sociedades mercantiles participadas por las Administraciones pueden ser entidades colaboradoras (**art. 12.2**).","No. Las Corporaciones Locales pueden ser entidades colaboradoras (**art. 12.3**).","Es esta. Quien no esté al corriente de sus obligaciones tributarias no puede obtener la condición de entidad colaboradora (**art. 13.2.e**).","No. Los organismos y entes públicos pueden ser entidades colaboradoras (**art. 12.2**)."]},{"id":"au-27-006","origen":"autoevaluacion","test":"Tema 5 (2) - LGS (arts 8 a 20)","n":6,"enunciado":"¿Cuál de los siguientes NO es un principio general que debe regir las subvenciones públicas según la LGS?","opciones":["El principio de transparencia.","El principio de eficiencia.","El principio de publicidad.","El principio de solidaridad."],"bloque":"subv-general","precepto":"art. 8.3","correcta":3,"justificaciones":["No. La transparencia es uno de los principios del art. 8.3.a.","No. La eficiencia en la asignación de recursos es principio del art. 8.3.c.","No. La publicidad es principio del art. 8.3.a.","Es esta. La solidaridad no figura entre los principios del art. 8.3."]},{"id":"au-27-007","origen":"autoevaluacion","test":"Tema 5 (2) - LGS (arts 8 a 20)","n":7,"enunciado":"Conforme a las previsiones de la LGS, señale la respuesta incorrecta:","opciones":["El otorgamiento de una subvención requiere la aprobación del gasto por el órgano competente para ello.","Las bases reguladoras de cada tipo de subvención se publicarán en el BOE o en el diario oficial correspondiente.","En el procedimiento de otorgamiento es necesaria la fiscalización previa de los actos administrativos de contenido económico.","La concesión de subvenciones de cuantía superior a 12 millones de euros corresponde al Consejo de Ministros."],"bloque":"subv-general","precepto":"arts. 9 y 10","correcta":3,"justificaciones":["Es verdadera, así que no se marca. La aprobación del gasto por el órgano competente es requisito (**art. 9.4.e**).","Es verdadera, así que no se marca. Las bases se publican en el BOE o en el diario oficial correspondiente (**art. 9.3**).","Es verdadera, así que no se marca. La fiscalización previa de los actos de contenido económico es requisito (**art. 9.4.d**).","Esta es la falsa, y por eso es la que hay que marcar. Por encima de 12 millones se necesita la previa autorización del Consejo de Ministros, pero la concesión sigue correspondiendo al órgano competente (**art. 10.2**)."],"revisar":"Importe de 12 millones de euros del art. 10.2 LGS. Comprobar que sigue vigente."},{"id":"au-27-008","origen":"autoevaluacion","test":"Tema 5 (2) - LGS (arts 8 a 20)","n":8,"enunciado":"Señale cuál de estas obligaciones corresponde a las Entidades Colaboradoras, de conformidad con el artículo 15 de la LGS:","opciones":["Dar la adecuada publicidad del carácter público de la financiación de las actuaciones que sean objeto de subvención.","Disponer de los libros contables debidamente auditados en los términos exigidos por la legislación mercantil.","Justificar la entrega de los fondos percibidos ante el órgano concedente de la subvención.","Iniciar el procedimiento de reintegro cuando el beneficiario incumpla alguna de sus obligaciones."],"bloque":"subv-general","precepto":"art. 15.1.c","correcta":2,"justificaciones":["No. La publicidad de la financiación pública es obligación del beneficiario (**art. 14.1.h**).","No. Llevar libros auditados es obligación del beneficiario (**art. 14.1.f**).","Es esta. La entidad colaboradora debe justificar la entrega de los fondos percibidos ante el órgano concedente (**art. 15.1.c**).","No. El reintegro lo inicia el órgano concedente, no la entidad colaboradora (**art. 15**)."]},{"id":"au-27-009","origen":"autoevaluacion","test":"Tema 5 (2) - LGS (arts 8 a 20)","n":9,"enunciado":"Conforme al artículo 9 de la Ley 38/2003, ¿cuál de los siguientes NO es un requisito para el otorgamiento de una subvención?","opciones":["La tramitación del procedimiento de concesión de acuerdo con las normas que resulten de aplicación.","Poseer el beneficiario nacionalidad española.","La existencia de crédito adecuado y suficiente para atender las obligaciones de contenido económico derivadas de la misma.","La competencia del órgano administrativo concedente."],"bloque":"subv-general","precepto":"art. 9","correcta":1,"justificaciones":["No. Es requisito tramitar el procedimiento según las normas aplicables (**art. 9.4.c**).","Es esta. La Ley no exige que el beneficiario tenga nacionalidad española (**art. 9**).","No. Es requisito que exista crédito adecuado y suficiente (**art. 9.4.b**).","No. Es requisito la competencia del órgano concedente (**art. 9.4.a**)."]},{"id":"au-27-010","origen":"autoevaluacion","test":"Tema 5 (2) - LGS (arts 8 a 20)","n":10,"enunciado":"Las facultades para conceder subvenciones, a que se refiere el artículo 10 de la LGS podrán ser objeto de desconcentración:","opciones":["Por Real Decreto de la Presidencia de Gobierno.","Mediante Real Decreto acordado en Consejo de Ministros.","Mediante orden del Ministro de la Presidencia.","Por orden del Presidente del Gobierno."],"bloque":"subv-general","precepto":"art. 10.3","correcta":1,"justificaciones":["No. La desconcentración no se hace por real decreto de la Presidencia.","Es esta. Mediante real decreto acordado en Consejo de Ministros (**art. 10.3**).","No. Una orden ministerial no basta para desconcentrar esta facultad (**art. 10.3**).","No. No se hace por orden del Presidente del Gobierno (**art. 10.3**)."]},{"id":"au-27-011","origen":"autoevaluacion","test":"Tema 5 (2) - LGS (arts 8 a 20)","n":11,"enunciado":"De acuerdo al artículo 18 de la LGS, operará como sistema nacional de publicidad de subvenciones:","opciones":["La Base de Datos Nacional de Subvenciones.","El Boletín Oficial del Estado.","El Registro Nacional de Beneficiarios y Entidades Colaboradoras.","El Registro Nacional de Subvenciones y Ayudas del Sector Público."],"bloque":"subv-general","precepto":"art. 18.1","correcta":0,"justificaciones":["Es esta. La Base de Datos Nacional de Subvenciones opera como sistema nacional de publicidad de subvenciones (**art. 18.1**).","No. El BOE publica extractos de las convocatorias, pero el sistema nacional de publicidad es la BDNS (**art. 18.1**).","No. Ese registro no es el que fija el art. 18.","No. Ese registro no es el que fija el art. 18."]},{"id":"au-27-012","origen":"autoevaluacion","test":"Tema 5 (2) - LGS (arts 8 a 20)","n":12,"enunciado":"De acuerdo al artículo 20.9 de la Ley 38/2003, la Base de Datos Nacional de Subvenciones podrá suministrar información pública sobre las sanciones firmes impuestas por:","opciones":["Infracciones graves.","Infracciones muy graves.","Infracciones leves.","En ningún caso podrá suministrar información pública sobre sanciones."],"bloque":"subv-general","precepto":"art. 20.9","correcta":1,"justificaciones":["No. La Ley habla solo de infracciones muy graves (**art. 20.9**).","Es esta. Puede suministrar información pública sobre las sanciones firmes por infracciones muy graves (**art. 20.9**).","No. Las leves no se publican (**art. 20.9**).","No. Sí puede, en el caso de las muy graves (**art. 20.9**)."]},{"id":"au-27-013","origen":"autoevaluacion","test":"Tema 5 (2) - LGS (arts 8 a 20)","n":13,"enunciado":"Los planes estratégicos de subvenciones con carácter general contendrán previsiones para:","opciones":["Un período de vigencia de cinco años.","Un período de vigencia de dos años.","Un período de vigencia de cuatro años.","Un período de vigencia de tres años."],"bloque":"subv-general","precepto":"art. 8 y Reglamento","correcta":3,"justificaciones":["No. Cinco años es más de lo que fija el Reglamento como regla general.","No. Dos años es menos de lo que fija el Reglamento como regla general.","No. Cuatro años no es el plazo general del Reglamento.","Es esta. Con carácter general los planes estratégicos tienen una vigencia de tres años."],"ojo":"La Ley 38/2003 (art. 8.1) exige el plan pero no fija su vigencia. Los tres años vienen del Reglamento (RD 887/2006).","revisar":"El dato no está en la Ley 38/2003 sino en su Reglamento (RD 887/2006). Conviene comprobarlo en el texto del Reglamento."},{"id":"au-27-014","origen":"autoevaluacion","test":"Tema 5 (2) - LGS (arts 8 a 20)","n":14,"enunciado":"Señale la respuesta correcta en relación con la competencia para otorgar subvenciones, de acuerdo con el artículo 10 de la Ley 38/2003, de 17 de noviembre, General de Subvenciones:","opciones":["La previa autorización del Consejo de Ministros en la concesión de subvenciones, no implicará la aprobación del gasto.","Las facultades para conceder subvenciones, no podrán ser objeto de desconcentración.","La concesión de subvenciones de cuantía superior a 10 millones de euros requerirá la previa autorización del Consejo de Ministros.","Es competente para conceder subvenciones en el ámbito del Servicio Público de Empleo Estatal la Ministra de Trabajo y Economía Social."],"bloque":"subv-general","precepto":"art. 10","correcta":0,"justificaciones":["Es esta. La autorización previa del Consejo de Ministros no implica la aprobación del gasto, que corresponde al órgano competente (**art. 10.2**).","No. Sí pueden desconcentrarse, mediante real decreto acordado en Consejo de Ministros (**art. 10.3**).","No. El umbral es de 12 millones, no de 10 (**art. 10.2**).","No. En el SEPE concede su presidente o director, no la Ministra (**art. 10.1**)."],"revisar":"Importe de 12 millones de euros del art. 10.2 LGS. Comprobar que sigue vigente."},{"id":"au-27-015","origen":"autoevaluacion","test":"Tema 5 (2) - LGS (arts 8 a 20)","n":15,"enunciado":"Según la Ley 38/2003, ¿cuál de los siguientes no es un requisito obligatorio para obtener la condición de beneficiario de una subvención?","opciones":["Estar al corriente en el cumplimiento de las obligaciones tributarias.","Hallarse al corriente de pago de obligaciones por reintegro de subvenciones.","No haber sido condenado mediante sentencia firme por delitos de prevaricación.","Tener personalidad jurídica."],"bloque":"subv-general","precepto":"art. 13","correcta":3,"justificaciones":["No. Estar al corriente de las obligaciones tributarias es requisito (**art. 13.2.e**).","No. Estar al corriente de pago de reintegros es requisito (**art. 13.2.g**).","No. Haber sido condenado por prevaricación impide obtener la condición de beneficiario (**art. 13.2.a**).","Es esta. Puede ser beneficiario quien carezca de personalidad jurídica, como las agrupaciones del art. 11.3."]},{"id":"au-27-016","origen":"autoevaluacion","test":"Tema 5 (2) - LGS (arts 8 a 20)","n":16,"enunciado":"Según el artículo 14 de la Ley 38/2003, ¿cuál de los siguientes no es una obligación del beneficiario de una subvención?","opciones":["Ejecutar directamente la actividad subvencionada sin subcontratar.","Someterse a las actuaciones de comprobación.","Conservar los documentos justificativos.","Justificar la aplicación de los fondos."],"bloque":"subv-general","precepto":"art. 14.1","correcta":0,"justificaciones":["Es esta. La Ley no obliga a ejecutar sin subcontratar: se puede subcontratar si la normativa lo prevé (**art. 29**).","No. Someterse a las actuaciones de comprobación es obligación (**art. 14.1.c**).","No. Conservar los documentos justificativos es obligación (**art. 14.1.g**).","No. Justificar la aplicación de los fondos es obligación (**art. 14.1.b**)."]},{"id":"au-27-017","origen":"autoevaluacion","test":"Tema 5 (2) - LGS (arts 8 a 20)","n":17,"enunciado":"¿Cuál de estas afirmaciones no es correcta sobre las bases reguladoras establecidas en el artículo 17 de la LGS?","opciones":["Su aprobación requerirá el informe previo de los servicios jurídicos y de la Intervención Delegada correspondiente.","Contendrá la definición del objeto de la subvención.","Serán objeto de publicación en el Boletín Oficial del Estado.","Se aprobará por Real Decreto de Consejo de Ministros."],"bloque":"subv-general","precepto":"art. 17","correcta":3,"justificaciones":["Es verdadera, así que no se marca. Se aprueban previo informe de los servicios jurídicos y de la Intervención Delegada (**art. 17.1**).","Es verdadera, así que no se marca. Definen el objeto de la subvención (**art. 17.3.a**).","Es verdadera, así que no se marca. Se publican en el BOE (**art. 17.1**).","Esta es la falsa, y por eso es la que hay que marcar. Se aprueban por orden ministerial, no por Real Decreto del Consejo de Ministros (**art. 17.1**)."]},{"id":"au-27-018","origen":"autoevaluacion","test":"Tema 5 (2) - LGS (arts 8 a 20)","n":18,"enunciado":"Según establece el articulo 16 de la LGS, los convenios de colaboración:","opciones":["No podrá tener un plazo de vigencia superior a tres años.","La duración total de las prórrogas no puede ser superior a la vigencia del período inicial.","No pueden prorrogarse.","Se formalizarán entre el órgano administrativo concedente y el beneficiario de la subvención."],"bloque":"subv-general","precepto":"art. 16.2","correcta":1,"justificaciones":["No. El plazo máximo de vigencia es de cuatro años, no de tres (**art. 16.2**).","Es esta. La duración total de las prórrogas no puede ser superior a la vigencia del período inicial (**art. 16.2**).","No. Sí pueden prorrogarse por mutuo acuerdo antes de que acabe el convenio (**art. 16.2**).","No. El convenio se formaliza entre el órgano concedente y la entidad colaboradora, no el beneficiario (**art. 16.1**)."]},{"id":"au-27-019","origen":"autoevaluacion","test":"Tema 5 (2) - LGS (arts 8 a 20)","n":19,"enunciado":"Dentro de las obligaciones del beneficiario establecidas en el artículo 14 de la LGS no se encuentra:","opciones":["Entregar a los beneficiarios los fondos recibidos.","El cumplimiento de los requisitos y condiciones.","Comunicar la obtención de otras subvenciones que financien las actividades subvencionadas.","Someterse a las actuaciones de comprobación."],"bloque":"subv-general","precepto":"art. 14.1","correcta":0,"justificaciones":["Es esta. Entregar los fondos a los beneficiarios es obligación de la entidad colaboradora, no del beneficiario (**art. 15.1.a**).","No. Cumplir los requisitos y condiciones sí es obligación del beneficiario (**art. 14.1.b**).","No. Comunicar otras subvenciones sí es obligación del beneficiario (**art. 14.1.d**).","No. Someterse a las actuaciones de comprobación sí es obligación del beneficiario (**art. 14.1.c**)."]},{"id":"au-27-020","origen":"autoevaluacion","test":"Tema 5 (2) - LGS (arts 8 a 20)","n":20,"enunciado":"Conforme al artículo 11 de la LGS, ¿quiénes tendrán igualmente la consideración de beneficiarios cuando el beneficiario sea una persona jurídica?","opciones":["En todo caso, los miembros asociados que realicen actividades por cuenta del beneficiario.","Los empleados del beneficiario.","Solo se considerara beneficiario a la persona jurídica.","Cuando se prevea en la normativa reguladora, los miembros asociados que realicen actividades por cuenta del beneficiario."],"bloque":"subv-general","precepto":"art. 11.2","correcta":3,"justificaciones":["No. No lo son en todo caso: solo si lo prevén las bases reguladoras (**art. 11.2**).","No. Los empleados no son beneficiarios (**art. 11.2**).","No. No solo la persona jurídica: también los miembros asociados si lo prevén las bases (**art. 11.2**).","Es esta. Si lo prevé la normativa reguladora, los miembros asociados que realicen actividades por cuenta del beneficiario (**art. 11.2**)."]},{"id":"au-27-021","origen":"autoevaluacion","test":"Tema 5 (2) - LGS (arts 8 a 20)","n":21,"enunciado":"¿Qué condición deben cumplir las agrupaciones sin personalidad jurídica para acceder a ser beneficiario de una subvención?","opciones":["Tener actividad comercial previa.","Disponer de domicilio fiscal en España.","Estar constituidas notarialmente.","Que se prevea expresamente en las bases reguladoras."],"bloque":"subv-general","precepto":"art. 11.3","correcta":3,"justificaciones":["No. No se exige actividad comercial previa (**art. 11.3**).","No. No se exige domicilio fiscal en España (**art. 11.3**).","No. No se exige constitución notarial (**art. 11.3**).","Es esta. Deben estar previstas expresamente en las bases reguladoras (**art. 11.3**)."]},{"id":"au-27-022","origen":"autoevaluacion","test":"Tema 5 (2) - LGS (arts 8 a 20)","n":22,"enunciado":"¿Cuál de estas afirmaciones no es una obligación que establezca el artículo 11 de la LGS a las agrupaciones sin personalidad jurídica cuando sean beneficiarios de una subvención?","opciones":["Deberá nombrarse un representante o apoderado único de la agrupación.","No podrá disolverse hasta que haya transcurrido el plazo de prescripción del procedimiento de reintegro.","Deberán hacerse constar expresamente los compromisos de ejecución asumidos por cada miembro.","Deberán registrarse en el Registro Nacional de Subvenciones."],"bloque":"subv-general","precepto":"art. 11.3","correcta":3,"justificaciones":["No. Sí es obligación nombrar un representante o apoderado único (**art. 11.3**).","No. Sí es obligación no disolverse hasta que prescriba el reintegro (**art. 11.3**).","No. Sí es obligación hacer constar los compromisos de cada miembro (**art. 11.3**).","Es esta. El art. 11 no obliga a registrarlas en el Registro Nacional de Subvenciones."]},{"id":"au-27-023","origen":"autoevaluacion","test":"Tema 5 (2) - LGS (arts 8 a 20)","n":23,"enunciado":"Según el artículo 13 de la LGS, ¿cómo puede justificarse que no se está incurso en prohibiciones para ser beneficiario?","opciones":["Mediante testimonio judicial, certificados telemáticos o certificación administrativa.","Únicamente mediante declaración jurada.","Por medios notariales.","No es necesaria la acreditación de dicha situación."],"bloque":"subv-general","precepto":"art. 13.7","correcta":0,"justificaciones":["Es esta. Puede hacerse con testimonio judicial, certificados telemáticos o certificación administrativa (**art. 13.7**).","No. “Únicamente” es falso: la declaración responsable solo sirve si no puede expedirse el documento (**art. 13.7**).","No. Los medios notariales solo valen para la declaración responsable, y no son el medio general (**art. 13.7**).","No. Sí es necesaria la acreditación (**art. 13.7**)."]},{"id":"au-27-024","origen":"autoevaluacion","test":"Tema 5 (2) - LGS (arts 8 a 20)","n":24,"enunciado":"En relación con el seguimiento de los planes estratégicos de subvenciones, cada Departamento ministerial deberá emitir anualmente un informe:","opciones":["Antes del 31 de marzo de cada año.","Antes del 30 de abril de cada año.","Antes del 30 de junio de cada año.","Antes del 31 de diciembre de cada año."],"bloque":"subv-general","precepto":"Reglamento (RD 887/2006)","correcta":0,"justificaciones":["Es esta. El informe anual de cada Departamento ministerial sobre el grado de avance del plan se emite antes del 31 de marzo.","No. El plazo no es el 30 de abril.","No. El plazo no es el 30 de junio.","No. El plazo no es el 31 de diciembre."],"ojo":"El seguimiento del plan estratégico se regula en el Reglamento, no en la Ley 38/2003.","revisar":"El dato no está en la Ley 38/2003 sino en su Reglamento (RD 887/2006). Conviene comprobarlo en el texto del Reglamento."},{"id":"au-27-025","origen":"autoevaluacion","test":"Tema 5 (2) - LGS (arts 8 a 20)","n":25,"enunciado":"Cuando las bases reguladoras lo prevean expresamente, podrán acceder a la condición de beneficiario:","opciones":["Exclusivamente las personas jurídicas con personalidad jurídica propia.","Las agrupaciones de personas físicas o jurídicas, públicas o privadas, así como las comunidades de bienes u otras unidades económicas o patrimonios separados, aunque carezcan de personalidad jurídica.","Únicamente las Administraciones públicas.","Las sociedades mercantiles."],"bloque":"subv-general","precepto":"art. 11.3","correcta":1,"justificaciones":["No. Si las bases lo prevén, también pueden serlo agrupaciones sin personalidad (**art. 11.3**).","Es esta. Las agrupaciones, comunidades de bienes y otras unidades económicas, aunque no tengan personalidad jurídica (**art. 11.3**).","No. No son solo las Administraciones públicas (**art. 11**).","No. Las sociedades mercantiles pueden ser beneficiarias, pero no es lo que se condiciona a las bases reguladoras (**art. 11.3**)."]},{"id":"au-28-001","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":1,"enunciado":"Conforme a la Ley 38/2003, indique la respuesta incorrecta:","opciones":["No podrá realizarse el pago a beneficiarios que no se hallen al corriente de sus obligaciones frente a la Seguridad Social.","Con carácter previo a la convocatoria de la subvención deberá efectuarse la aprobación del gasto.","La resolución de concesión de la subvención conllevará el compromiso del gasto correspondiente.","En ningún caso se podrán realizar pagos que supongan entregas de fondos previamente a la justificación de la subvención."],"bloque":"subv-concesion","precepto":"art. 34","correcta":3,"justificaciones":["Es verdadera, así que no se marca. No se paga a quien no está al corriente con la Seguridad Social (**art. 34.5**).","Es verdadera, así que no se marca. La aprobación del gasto precede a la convocatoria (**art. 34.1**).","Es verdadera, así que no se marca. La resolución de concesión conlleva el compromiso del gasto (**art. 34.2**).","Esta es la falsa, y por eso es la que hay que marcar. Pueden hacerse pagos anticipados cuando la normativa reguladora lo prevea (**art. 34.4**)."]},{"id":"au-28-002","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":2,"enunciado":"¿Cuál es el instrumento habitual para canalizar las subvenciones previstas nominativamente en los Presupuestos Generales del Estado?","opciones":["La concurrencia competitiva.","Los convenios.","No pueden existir subvenciones nominativas.","Ninguna es correcta."],"bloque":"subv-concesion","precepto":"art. 28","correcta":1,"justificaciones":["No. La concurrencia competitiva es el procedimiento ordinario, no el de las nominativas (**art. 22.1**).","Es esta. Las subvenciones nominativas se instrumentan mediante convenios (**art. 28**).","No. Sí existen: son una forma de concesión directa (**art. 22.2.a**).","No. La segunda opción es correcta."]},{"id":"au-28-003","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":3,"enunciado":"De acuerdo a la LGS, ¿el beneficiario podrá subcontratar la actividad que constituye el objeto de la subvención?","opciones":["Total o parcialmente, cuando la normativa reguladora de la subvención así lo prevea.","Sólo parcialmente.","En ningún caso será posible la subcontratación de la actividad objeto de subvención.","Sólo totalmente."],"bloque":"subv-concesion","precepto":"art. 29.2","correcta":0,"justificaciones":["Es esta. Puede subcontratar total o parcialmente cuando la normativa reguladora lo prevea (**art. 29.2**).","No. No se limita a lo parcial: la ley dice total o parcialmente (**art. 29.1**).","No. Sí es posible si la normativa lo prevé (**art. 29.2**).","No. No se limita a lo total: la ley dice total o parcialmente (**art. 29.1**)."]},{"id":"au-28-004","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":4,"enunciado":"El artículo 22 de la LGS establece, respecto del procedimiento de concesión de subvenciones, que:","opciones":["Se prohíbe expresamente la concesión directa de subvenciones.","La propuesta de concesión se formulará al órgano concedente por un órgano colegiado o unipersonal.","En ningún caso se procederá al prorrateo entre los beneficiarios del importe global máximo destinado a las subvenciones.","No podrán otorgarse subvenciones por cuantía superior a la que se determine en la convocatoria."],"bloque":"subv-concesion","precepto":"art. 22.3","correcta":3,"justificaciones":["No. La concesión directa está permitida en los casos del art. 22.2.","No. La propuesta la formula un órgano colegiado, no uno unipersonal (**art. 22.1**).","No. Excepcionalmente, si lo prevén las bases, procede el prorrateo (**art. 22.1**).","Es esta. No pueden otorgarse subvenciones por cuantía superior a la que fije la convocatoria (**art. 22.3**)."]},{"id":"au-28-005","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":5,"enunciado":"Una subvención puede concederse de forma directa, sin someterse a libre concurrencia:","opciones":["Cuando se decida libremente por Real Decreto el Consejo de Ministros.","En los supuestos que prevean las bases de la convocatoria correspondiente, siempre que exista crédito suficiente y adecuado.","Por razones de interés público, social, económico o humanitario que dificulten su convocatoria pública.","En ningún caso."],"bloque":"subv-concesion","precepto":"art. 22.2.c","correcta":2,"justificaciones":["No. El Consejo de Ministros no puede decidirlo libremente: debe haber razones del art. 22.2.c.","No. Esa no es una excepción: la concesión directa no depende de lo que prevean las bases de una convocatoria (**art. 22.2**).","Es esta. Excepcionalmente, por razones de interés público, social, económico o humanitario que dificulten su convocatoria pública (**art. 22.2.c**).","No. Sí es posible en los casos del art. 22.2."]},{"id":"au-28-006","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":6,"enunciado":"Respecto de las subvenciones públicas, señale la afirmación correcta:","opciones":["El procedimiento ordinario de concesión de subvenciones se tramitará en régimen de concesión directa.","El plazo máximo para resolver y notificar la resolución del procedimiento de reintegro de subvenciones será de tres meses.","El procedimiento ordinario de concesión de subvenciones se tramitará en régimen de concurrencia competitiva.","Tienen el carácter de subvenciones las prestaciones reconocidas por el Fondo de Garantía Salarial."],"bloque":"subv-concesion","precepto":"art. 22.1","correcta":2,"justificaciones":["No. El procedimiento ordinario es la concurrencia competitiva (**art. 22.1**).","No. El plazo de resolución del reintegro es de 12 meses, no de tres (**art. 42.4**).","Es esta. El procedimiento ordinario se tramita en régimen de concurrencia competitiva (**art. 22.1**).","No. Las prestaciones del FOGASA no tienen carácter de subvención (**art. 2.4**)."]},{"id":"au-28-007","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":7,"enunciado":"De las siguientes afirmaciones, señale la correcta según la Ley 38/2003, General de Subvenciones:","opciones":["El beneficiario deberá acreditar con anterioridad a la propuesta de concesión estar al corriente en sus obligaciones tributarias.","El beneficiario deberá comunicar, en la justificación de la inversión, la obtención de otras subvenciones con idéntica finalidad.","Son subvencionables los gastos de procedimientos judiciales.","Excepcionalmente, serán gastos subvencionables los intereses deudores de las cuentas bancarias."],"bloque":"subv-concesion","precepto":"art. 14.1.e","correcta":0,"justificaciones":["Es esta. Debe acreditarlo con anterioridad a dictarse la propuesta de resolución de concesión (**art. 14.1.e**).","No. La comunicación se hace tan pronto como se conozca y siempre antes de la justificación, no en ella (**art. 14.1.d**).","No. Los gastos de procedimientos judiciales no son subvencionables (**art. 31.7**).","No. Los intereses deudores de cuentas bancarias no son subvencionables (**art. 31.7**)."]},{"id":"au-28-008","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":8,"enunciado":"De acuerdo con el artículo 31 de la LGS, salvo disposición expresa en contrario en las bases reguladoras de las subvenciones, se considerará gasto realizado el que ha sido pagado por el beneficiario:","opciones":["Con anterioridad a la finalización del período de ejecución.","Con anterioridad a la finalización del año natural en que se haya solicitado la subvención.","Dentro del período de ejecución determinado por la normativa reguladora de la subvención.","Con anterioridad a la finalización del período de justificación determinado por la normativa reguladora de la subvención."],"bloque":"subv-concesion","precepto":"art. 31.2","correcta":3,"justificaciones":["No. El límite no es el fin del período de ejecución sino el del período de justificación (**art. 31.2**).","No. El año natural de la solicitud no es el criterio (**art. 31.2**).","No. El período de ejecución no es el referente del pago (**art. 31.2**).","Es esta. Gasto realizado es el efectivamente pagado antes de que finalice el período de justificación (**art. 31.2**)."]},{"id":"au-28-009","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":9,"enunciado":"Señale la respuesta correcta respecto al procedimiento de concesión de subvenciones en régimen de concurrencia competitiva, según la LGS:","opciones":["Siempre se deberá dar un plazo de audiencia a la persona interesada.","Se iniciará de oficio o a solicitud de la persona interesada.","Se iniciará a solicitud de la persona interesada.","La propuesta de resolución definitiva no crea derecho alguno a favor del beneficiario propuesto, frente a la Administración."],"bloque":"subv-concesion","precepto":"art. 24.6","correcta":3,"justificaciones":["No. Se puede prescindir de la audiencia cuando no se tengan en cuenta otros hechos o alegaciones que los del interesado (**art. 24.4**).","No. Se inicia siempre de oficio, no a solicitud del interesado (**art. 23.1**).","No. Se inicia siempre de oficio (**art. 23.1**).","Es esta. Las propuestas de resolución provisional y definitiva no crean derecho alguno hasta que se notifique la concesión (**art. 24.6**)."]},{"id":"au-28-010","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":10,"enunciado":"La tramitación de subvenciones en régimen de concurrencia competitiva:","opciones":["Es un procedimiento simplificado en materia de subvenciones.","Constituye el procedimiento ordinario de concesión de subvenciones.","Constituye un procedimiento excepcional de concesión de subvenciones.","Requerirá la acreditación de las razones de interés público, económico y social que la justifican."],"bloque":"subv-concesion","precepto":"art. 22.1","correcta":1,"justificaciones":["No. No es un procedimiento simplificado: es el ordinario (**art. 22.1**).","Es esta. La concurrencia competitiva es el procedimiento ordinario de concesión (**art. 22.1**).","No. Lo excepcional es la concesión directa (**art. 22.2.c**).","No. Acreditar razones de interés público es requisito de la concesión directa excepcional, no de la concurrencia (**art. 22.2.c**)."]},{"id":"au-28-011","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":11,"enunciado":"El plazo máximo para resolver y notificar la resolución del procedimiento de concesión de subvenciones en régimen de concurrencia competitiva no podrá exceder de:","opciones":["Seis meses, en ningún caso.","Tres meses, en ningún caso.","Seis meses, salvo que una norma con rango de ley establezca plazo mayor o así lo prevea la normativa de la Unión Europea.","Tres meses, salvo que una norma con rango de ley establezca plazo mayor o así lo prevea la normativa de la Unión Europea."],"bloque":"subv-concesion","precepto":"art. 25.4","correcta":2,"justificaciones":["No. El plazo de seis meses admite excepciones, así que no vale decir que es así en ningún caso (**art. 25.4**).","No. El plazo general es de seis meses, no de tres (**art. 25.4**).","Es esta. No puede exceder de seis meses, salvo que una norma con rango de ley fije un plazo mayor o lo prevea la normativa de la Unión Europea (**art. 25.4**).","No. Tiene la excepción correcta, pero el plazo es de seis meses y no de tres (**art. 25.4**)."]},{"id":"au-28-012","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":12,"enunciado":"De acuerdo al artículo 23.5 de la Ley 38/2003, si la solicitud no reúne los requisitos establecidos en la norma de convocatoria el órgano competente requerirá al interesado que subsane:","opciones":["En el plazo máximo e improrrogable de 5 días.","En el plazo máximo de 20 días.","En el plazo de 15 días.","En el plazo máximo e improrrogable de 10 días."],"bloque":"subv-concesion","precepto":"art. 23.5","correcta":3,"justificaciones":["No. Cinco días no es el plazo de subsanación de la Ley 38/2003 (**art. 23.5**).","No. Veinte días no es el plazo. La ley fija diez (**art. 23.5**).","No. Quince días es el plazo para aportar documentación cuando se sustituye por declaración responsable (**art. 23.4**), pero no el de subsanar (**art. 23.5**).","Es esta. El plazo es de diez días, máximo e improrrogable, y si no se subsana se le tiene por desistido (**art. 23.5**)."]},{"id":"au-28-013","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":13,"enunciado":"Según el artículo 23.2 de la LGS, en el procedimiento de concesión de subvenciones en régimen de concurrencia competitiva la iniciación de oficio se realizará siempre mediante:","opciones":["Bases reguladoras aprobadas por el órgano competente.","Resolución de concesión adoptada por el órgano competente.","Convocatoria aprobada por el órgano competente.","Plan estratégico aprobado por el órgano competente."],"bloque":"subv-concesion","precepto":"art. 23.2","correcta":2,"justificaciones":["No. Las bases reguladoras fijan las reglas, pero no inician el procedimiento (**art. 23.2**).","No. La resolución de concesión pone fin al procedimiento, no lo inicia (**art. 25**).","Es esta. La iniciación de oficio se realiza siempre mediante convocatoria aprobada por el órgano competente (**art. 23.2**).","No. El plan estratégico es un instrumento de planificación previo, no el acto de inicio (**art. 8**)."]},{"id":"au-28-014","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":14,"enunciado":"De acuerdo con el artículo 29 de la Ley 38/2003, el beneficiario podrá subcontratar, total o parcialmente, la actividad:","opciones":["Con carácter general, salvo que la normativa reguladora de la subvención lo prohíba expresamente.","En cualquier caso se podrá subcontratar hasta un 20% de la actividad.","En ningún caso se podrá subcontratar totalmente la actividad.","Únicamente cuando la normativa reguladora de la subvención así lo prevea."],"bloque":"subv-concesion","precepto":"art. 29.2","correcta":3,"justificaciones":["No. Es al revés: solo se puede subcontratar cuando lo prevea la normativa reguladora (**art. 29.2**).","No. El 20 % no es el límite general. Es el umbral a partir del cual se exigen requisitos (**art. 29.3**). Sin previsión en las bases, el tope es el 50 % (**art. 29.2**).","No. La ley no prohíbe siempre la subcontratación total. Si las bases lo prevén, puede ser total o parcial (**art. 29.2**).","Es esta. El beneficiario solo puede subcontratar, total o parcialmente, cuando la normativa reguladora de la subvención así lo prevea (**art. 29.2**)."]},{"id":"au-28-015","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":15,"enunciado":"De acuerdo a la Ley 38/2003, la actividad subvencionada que el beneficiario subcontrate con terceros no excederá del porcentaje que se fije en las bases reguladoras. Si tal previsión no figura, el beneficiario podrá subcontratar hasta un porcentaje:","opciones":["Que no exceda del 30 por ciento del importe de la actividad subvencionada.","Que no exceda del 60 por ciento del importe de la actividad subvencionada.","Que no exceda del 20 por ciento del importe de la actividad subvencionada.","Que no exceda del 50 por ciento del importe de la actividad subvencionada."],"bloque":"subv-concesion","precepto":"art. 29.2","correcta":3,"justificaciones":["No. El tope supletorio no es del 30 %, sino del 50 % (**art. 29.2**).","No. El 60 % no aparece en la ley (**art. 29.2**).","No. El 20 % es el umbral de la subcontratación sujeta a requisitos, no el tope supletorio (**art. 29.3**).","Es esta. Si las bases no fijan porcentaje, se puede subcontratar hasta el 50 % del importe de la actividad subvencionada (**art. 29.2**)."]},{"id":"au-28-016","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":16,"enunciado":"Conforme al artículo 34 de la LGS, con carácter previo a la convocatoria de la subvención o a la concesión directa de la misma, deberá efectuarse:","opciones":["El compromiso del gasto.","La aprobación del gasto.","La justificación de la inversión.","El reconocimiento de la obligación."],"bloque":"subv-concesion","precepto":"art. 34.1","correcta":1,"justificaciones":["No. El compromiso del gasto lo conlleva la resolución de concesión, que es posterior (**art. 34.2**).","Es esta. Antes de la convocatoria o de la concesión directa debe efectuarse la aprobación del gasto (**art. 34.1**).","No. La justificación la presenta el beneficiario después de realizar la actividad (**art. 34.3**).","No. El reconocimiento de la obligación llega al final, cuando se justifica y se va a pagar (**art. 34.3**)."]},{"id":"au-28-017","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":17,"enunciado":"¿Cuál de los siguientes gastos no se considera subvencionables, salvo que las bases reguladoras digan lo contrario?","opciones":["Los gastos financieros.","Los gastos en materiales relacionados con la actividad.","Los costes de personal.","El arrendamiento de locales."],"bloque":"subv-concesion","precepto":"art. 31.7","correcta":0,"justificaciones":["Es esta. Los gastos financieros solo son subvencionables si están relacionados con la actividad, son indispensables y las bases reguladoras lo prevén (**art. 31.7**).","No. Los materiales relacionados con la actividad responden a su naturaleza y son subvencionables en general (**art. 31.1**).","No. Los costes de personal, si responden a la actividad, son gasto subvencionable en general (**art. 31.1**).","No. El arrendamiento de locales para la actividad es un gasto subvencionable en general (**art. 31.1**)."],"ojo":"Pregunta mal planteada: el enunciado dice que no es subvencionable 'salvo que las bases digan lo contrario' y eso encaja con los gastos financieros del art. 31.7, que exigen previsión en las bases."},{"id":"au-28-018","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":18,"enunciado":"Según la Ley General de Subvenciones, la convocatoria de subvenciones debe publicarse:","opciones":["Para subvenciones en concurrencia competitiva de importe superior a 12 millones de euros.","Íntegramente su contenido en el BOE.","Cuando el importe supere los 60.000 euros.","En la BDNS y un extracto de la misma, en el \"Boletín Oficial del Estado\"."],"bloque":"subv-concesion","precepto":"art. 23.2","correcta":3,"justificaciones":["No. La convocatoria se publica siempre, sin atender a ese importe. Los 12 millones son el umbral de autorización del Consejo de Ministros (**art. 10.2**).","No. En el BOE solo se publica un extracto, no el contenido íntegro (**art. 23.2**).","No. Los 60.000 euros se refieren a la subcontratación (**art. 29.3**), no a la publicación.","Es esta. La convocatoria se publica en la BDNS y un extracto de la misma en el BOE (**art. 23.2**)."]},{"id":"au-28-019","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":19,"enunciado":"Según el articulo 31 de la LGS cuando el importe del gasto subvencionable supere las cuantías establecidas para el contrato menor:","opciones":["El beneficiario deberá solicitar como mínimo tres ofertas de diferentes proveedores, con carácter previo a la contracción del compromiso.","Se le tiene que comunicar al órgano concedente previo a realizar el gasto.","Se requerirá autorización por parte del órgano concedente previo a realizar el gasto.","No podrá realizarse dicho gasto."],"bloque":"subv-concesion","precepto":"art. 31.3","correcta":0,"justificaciones":["Es esta. Si el gasto supera la cuantía del contrato menor, el beneficiario debe pedir al menos tres ofertas de proveedores distintos antes de contraer el compromiso (**art. 31.3**).","No. La ley no exige comunicar el gasto al órgano concedente antes de hacerlo (**art. 31.3**).","No. No hace falta autorización previa del concedente para realizar ese gasto (**art. 31.3**).","No. El gasto sí puede realizarse. Lo que se exige son tres ofertas (**art. 31.3**)."]},{"id":"au-28-020","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":20,"enunciado":"En ningún caso serán gastos subvencionables:","opciones":["Los impuestos indirectos cuando sean susceptibles de recuperación o compensación.","Los gastos de asesoría jurídica o financiera.","Los gastos periciales para la realización del proyecto subvencionado.","Los gastos de administración específicos."],"bloque":"subv-concesion","precepto":"art. 31.8","correcta":0,"justificaciones":["Es esta. En ningún caso son subvencionables los impuestos indirectos susceptibles de recuperación o compensación (**art. 31.8**).","No. La asesoría jurídica o financiera es subvencionable si es indispensable y las bases lo prevén (**art. 31.7**).","No. Los gastos periciales son subvencionables en las mismas condiciones (**art. 31.7**).","No. Los gastos de administración específicos son subvencionables si las bases lo prevén (**art. 31.7**)."]},{"id":"au-28-021","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":21,"enunciado":"En el procedimiento de concesión de subvenciones, ¿cuándo cabrá efectuar el prorrateo del importe global máximo destinado a las subvenciones entre los beneficiarios de la misma?","opciones":["Excepcionalmente, siempre que así se prevea en las bases reguladoras.","Excepcionalmente, cuando el órgano instructor lo considere adecuado para una mejor distribución de las subvenciones.","Con carácter general, salvo que las bases reguladoras lo prohíban expresamente.","El prorrateo solo será posible en las subvenciones de carácter nominativo."],"bloque":"subv-concesion","precepto":"art. 22.1","correcta":0,"justificaciones":["Es esta. El prorrateo es excepcional y solo cabe si lo prevén las bases reguladoras (**art. 22.1**).","No. No depende de lo que considere el órgano instructor, sino de las bases (**art. 22.1**).","No. No es la regla general. Es una excepción que debe estar prevista (**art. 22.1**).","No. El prorrateo se prevé para la concurrencia competitiva, no para las nominativas (**art. 22.1**)."]},{"id":"au-28-022","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":22,"enunciado":"Según el artículo 28 de la LGS, la concesión directa de subvenciones por interés público, social, económico o humanitario deben aprobarse por:","opciones":["Orden Ministerial.","Acuerdo de Consejo de Ministros.","Real Decreto del Gobierno, a propuesta del ministro competente e informe del Ministerio de Hacienda.","Real Decreto de la Presidencia de Gobierno."],"bloque":"subv-concesion","precepto":"art. 28.2","correcta":2,"justificaciones":["No. Una orden ministerial aprueba las bases reguladoras (**art. 17.2**), no estas subvenciones directas.","No. No basta un acuerdo del Consejo de Ministros. La ley exige real decreto (**art. 28.2**).","Es esta. El Gobierno las aprueba por real decreto, a propuesta del ministro competente y previo informe del Ministerio de Hacienda (**art. 28.2**).","No. No existe un real decreto 'de la Presidencia'. Lo aprueba el Gobierno, a propuesta del ministro competente (**art. 28.2**)."]},{"id":"au-28-023","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":23,"enunciado":"El Real Decreto que regule una subvención directa por razones de interés público, social, económico o humanitario deberá contener como mínimo:","opciones":["Objeto, régimen jurídico, beneficiarios, procedimiento y justificación.","Solo el importe y la fecha de concesión.","Solo el beneficiario y el importe correspondiente.","El régimen sancionador aplicable."],"bloque":"subv-concesion","precepto":"art. 28.3","correcta":0,"justificaciones":["Es esta. Debe contener como mínimo el objeto, el régimen jurídico, los beneficiarios y modalidades de ayuda y el procedimiento de concesión y justificación (**art. 28.3**).","No. Son contenidos mínimos mucho más amplios que el importe y la fecha (**art. 28.3**).","No. Falta lo esencial, como el objeto y el procedimiento (**art. 28.3**).","No. El régimen sancionador está en la propia ley y no forma parte del contenido mínimo (**art. 28.3**)."]},{"id":"au-28-024","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":24,"enunciado":"¿Cuál de las siguientes afirmaciones sobre la subcontratación de actividades subvencionadas por los beneficiarios NO es correcta?","opciones":["Los contratistas asumirán la total responsabilidad de la ejecución de la actividad.","No podrá concertarse dicha contratación con personas incursas en alguna de las prohibiciones del artículo 13 de la LGS.","No se considera subcontratación los gastos en que tenga que incurrir el beneficiario para la realización por sí mismo de la actividad.","No podrá fraccionarse un contrato con el objeto de disminuir la cuantía del mismo y eludir el cumplimiento de los requisitos."],"bloque":"subv-concesion","precepto":"art. 29.5","correcta":0,"justificaciones":["Es la falsa. Los contratistas quedan obligados solo ante el beneficiario, que asume la total responsabilidad frente a la Administración (**art. 29.5**).","Es verdadera. No se puede subcontratar con personas incursas en las prohibiciones del art. 13 (**art. 29.7.a**).","Es verdadera. No es subcontratación lo que el beneficiario necesita para hacer por sí mismo la actividad (**art. 29.1**).","Es verdadera. No se puede fraccionar un contrato para eludir los requisitos (**art. 29.4**)."]},{"id":"au-28-025","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":25,"enunciado":"En ningún caso podrá concertarse por el beneficiario la ejecución total o parcial de las actividades subvencionadas con:","opciones":["Personas que hayan percibido otras subvenciones para la realización de otra actividad.","Personas o entidades solicitantes de ayudas o subvenciónes.","Personas o entidades vinculadas con el beneficiario con la la previa autorización expresa del órgano concedente.","Personas o entidades incursas en alguna de las prohibiciones del artículo 13 de la LGS."],"bloque":"subv-concesion","precepto":"art. 29.7","correcta":3,"justificaciones":["No. La prohibición es con quien percibió otras subvenciones para esa misma actividad, no para otra distinta (**art. 29.7.b**).","No. Solo está vetado quien pidió ayuda en la misma convocatoria y no la obtuvo. No cualquier solicitante (**art. 29.7.e**).","No. Con vinculadas sí se puede, si hay autorización expresa previa y el coste no supera el incurrido (**art. 29.7.d**).","Es esta. No se puede subcontratar con personas o entidades incursas en las prohibiciones del art. 13 (**art. 29.7.a**)."]},{"id":"au-28-026","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":26,"enunciado":"Según el artículo 29 de la LGS, ¿qué está prohibido en la subcontratación de actividades subvencionadas?","opciones":["Subcontratar a personas jurídicas.","Contratar a empresas del sector público.","Fraccionar un contrato para disminuir la cuantía y así eludir requisitos legales.","Contratar servicios de asesoría contable."],"bloque":"subv-concesion","precepto":"art. 29.4","correcta":2,"justificaciones":["No. Se puede subcontratar con personas jurídicas siempre que no concurra una prohibición (**art. 29.7**).","No. Contratar con empresas del sector público no está prohibido por el art. 29 (**art. 29.7**).","Es esta. Está prohibido fraccionar un contrato para reducir su cuantía y eludir los requisitos (**art. 29.4**).","No. Los servicios de asesoría contable pueden subcontratarse, salvo los casos del art. 29.7."]},{"id":"au-28-027","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":27,"enunciado":"Según se establece en el articulo 30 de la LGS, la rendición de la cuenta justificativa:","opciones":["Constituye un acto obligatorio del beneficiario o de la entidad colaboradora.","Es solo obligatorio para el beneficiario de la subvención.","Deberá presentarse en el plazo de 6 meses desde la realización de la actividad.","Se realizará mediante declaración responsable de haber realizado la actividad."],"bloque":"subv-concesion","precepto":"art. 30.2","correcta":0,"justificaciones":["Es esta. La rendición de la cuenta justificativa es un acto obligatorio del beneficiario o de la entidad colaboradora (**art. 30.2**).","No. También obliga a la entidad colaboradora (**art. 30.2**).","No. Seis meses no es el plazo. A falta de bases, son tres meses desde el fin del plazo de la actividad (**art. 30.2**).","No. La cuenta justificativa incluye los justificantes de gasto y no basta una declaración responsable (**art. 30.2**)."]},{"id":"au-28-028","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":28,"enunciado":"El plazo para presentar la cuenta justificativa de una subvención según la LGS es:","opciones":["Vendrá establecido en las bases reguladoras de las subvenciones.","6 meses desde la finalización de la actividad.","1 año desde la finalización de la actividad.","El plazo de justificación será de 3 meses en todo caso."],"bloque":"subv-concesion","precepto":"art. 30.2","correcta":0,"justificaciones":["Es esta. Lo determinan las bases reguladoras. Solo si no lo prevén, el plazo máximo es de tres meses desde que termina el plazo de realización de la actividad (**art. 30.2**).","No. Seis meses no es el plazo legal (**art. 30.2**).","No. Un año no es el plazo legal (**art. 30.2**).","No. Los tres meses son supletorios, no 'en todo caso' (**art. 30.2**)."]},{"id":"au-28-029","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":29,"enunciado":"Una vez evaluadas las solicitudes en un procedimiento de concurrencia competitiva, el órgano instructor formulará:","opciones":["Directamente la resolución definitiva.","Una propuesta de resolución provisional, debidamente motivada, que deberá notificarse a los interesados y respecto de la cual se concederá un plazo de 10 días para alegaciones.","Una propuesta definitiva sin posibilidad de alegaciones.","Una resolución provisional que no necesita ser motivada."],"bloque":"subv-concesion","precepto":"art. 24.4","correcta":1,"justificaciones":["No. Antes de la resolución hay una propuesta provisional y después una definitiva (**art. 24.4**).","Es esta. El instructor formula una propuesta de resolución provisional motivada, que se notifica a los interesados con 10 días para alegaciones (**art. 24.4**).","No. Hay alegaciones, salvo que se prescinda del trámite si no hay otros hechos ni alegaciones (**art. 24.4**).","No. La propuesta provisional debe estar debidamente motivada (**art. 24.4**)."]},{"id":"au-28-030","origen":"autoevaluacion","test":"Tema 5 (3) - LGS (arts 22 a 35)","n":30,"enunciado":"Cuando el importe de la propuesta de resolución provisional sea inferior al solicitado, podrá instarse la reformulación de la solicitud:","opciones":["Siempre, aunque no esté prevista en las bases reguladoras.","Únicamente en los procedimientos de concesión directa.","Cuando así se haya previsto en las bases reguladoras, para ajustar los compromisos y condiciones a la subvención otorgable.","Únicamente cuando lo solicite el órgano concedente después de la resolución definitiva."],"bloque":"subv-concesion","precepto":"art. 27.1","correcta":2,"justificaciones":["No. Solo cabe la reformulación si las bases la han previsto (**art. 27.1**).","No. La reformulación es propia de la concurrencia competitiva, no de la concesión directa (**art. 27.1**).","Es esta. Si lo prevén las bases, se puede instar al beneficiario a reformular para ajustar compromisos y condiciones a la subvención otorgable (**art. 27.1**).","No. La reformulación se produce ante la propuesta provisional, no después de la resolución definitiva (**art. 27.1**)."]},{"id":"au-29-001","origen":"autoevaluacion","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":1,"enunciado":"Según el artículo 36 de la LGS, la declaración judicial o administrativa de nulidad o anulación llevará consigo:","opciones":["La obligación de devolver las cantidades percibidas.","La obligación de publicar de nuevo la convocatoria.","La obligación de aprobar una nueva convocatoria.","La obligación de presentar renuncia formal a la subvención."],"bloque":"subv-reintegro","precepto":"art. 36.4","correcta":0,"justificaciones":["Es esta. La declaración de nulidad o anulación lleva consigo la obligación de devolver las cantidades percibidas (**art. 36.4**).","No. La ley no impone volver a publicar la convocatoria (**art. 36.4**).","No. No obliga a aprobar una nueva convocatoria (**art. 36.4**).","No. La renuncia formal no es la consecuencia que prevé la ley (**art. 36.4**)."]},{"id":"au-29-002","origen":"autoevaluacion","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":2,"enunciado":"De acuerdo al artículo 38 de la LGS, el interés de demora aplicable en materia de subvenciones será el interés legal del dinero:","opciones":["Incrementado en un 30 por ciento, salvo que la Ley de Presupuestos Generales del Estado establezca otro diferente.","Incrementado en un 50 por ciento, salvo que la Ley de Presupuestos Generales del Estado establezca otro diferente.","Incrementado en un 75 por ciento, salvo que la Ley de Presupuestos Generales del Estado establezca otro diferente.","Incrementado en un 25 por ciento, salvo que la Ley de Presupuestos Generales del Estado establezca otro diferente."],"bloque":"subv-reintegro","precepto":"art. 38.2","correcta":3,"justificaciones":["No. El incremento es del 25 %, no del 30 % (**art. 38.2**).","No. El incremento es del 25 %, no del 50 % (**art. 38.2**).","No. El incremento es del 25 %, no del 75 % (**art. 38.2**).","Es esta. El interés de demora es el interés legal del dinero incrementado en un 25 %, salvo que la Ley de Presupuestos fije otro (**art. 38.2**)."]},{"id":"au-29-003","origen":"autoevaluacion","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":3,"enunciado":"De acuerdo al artículo 39 de la Ley 38/2003, el derecho de la Administración a reconocer o liquidar el reintegro:","opciones":["Prescribirá a los cuatro años.","Prescribirá a los seis años.","Prescribirá a los cinco años.","Prescribirá al año."],"bloque":"subv-reintegro","precepto":"art. 39.1","correcta":0,"justificaciones":["Es esta. El derecho de la Administración a reconocer o liquidar el reintegro prescribe a los cuatro años (**art. 39.1**).","No. Seis años no es el plazo (**art. 39.1**).","No. Cinco años no es el plazo (**art. 39.1**).","No. Un año no es el plazo. Son cuatro (**art. 39.1**)."]},{"id":"au-29-004","origen":"autoevaluacion","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":4,"enunciado":"El plazo máximo para resolver y notificar la resolución del procedimiento de reintegro será de:","opciones":["Seis meses, desde la notificación del acuerdo de iniciación.","Seis meses, desde la fecha del acuerdo de iniciación.","Doce meses, desde la notificación del acuerdo de iniciación.","Doce meses, desde la fecha del acuerdo de iniciación."],"bloque":"subv-reintegro","precepto":"art. 42.4","correcta":3,"justificaciones":["No. El plazo es de doce meses, no de seis (**art. 42.4**).","No. Son doce meses, no seis (**art. 42.4**).","No. El plazo es de doce meses, pero se cuenta desde la fecha del acuerdo de iniciación y no desde su notificación (**art. 42.4**).","Es esta. Son doce meses desde la fecha del acuerdo de iniciación (**art. 42.4**)."]},{"id":"au-29-005","origen":"autoevaluacion","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":5,"enunciado":"Conforme a la LGS, constituye infracción muy grave la siguiente conducta:","opciones":["La presentación fuera de plazo de las cuentas justificativas de la aplicación dada a los fondos percibidos.","La no aplicación, en todo o en parte, de las cantidades recibidas a los fines para los que la subvención fue concedida.","La resistencia, obstrucción, excusa o negativa a las actuaciones de control financiero.","La falta de justificación del empleo dado a los fondos recibidos una vez transcurrido el plazo establecido para su presentación."],"bloque":"subv-sanciones","precepto":"art. 58.b","correcta":1,"justificaciones":["No. Presentar tarde las cuentas justificativas es infracción leve (**art. 56.a**).","Es esta. No aplicar, en todo o en parte, las cantidades recibidas a los fines de la subvención es infracción muy grave (**art. 58.b**).","No. La resistencia u obstrucción al control financiero es, con carácter general, infracción leve (**art. 56.g**). Solo es muy grave si impide verificar el empleo de los fondos (**art. 58.c**).","No. La falta de justificación una vez transcurrido el plazo es infracción grave (**art. 57.c**)."]},{"id":"au-29-006","origen":"autoevaluacion","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":6,"enunciado":"Según la Ley 38/2003, cuando proceda el reintegro de una subvención, se exigirá el interés de demora correspondiente calculado:","opciones":["Desde el momento del pago de la subvención hasta la fecha en que se inicie el procedimiento de reintegro.","Desde el momento de la concesión de la subvención hasta la fecha en que se inicie el procedimiento de reintegro.","Desde el momento de la concesión de la subvención hasta la fecha en que se acuerde el reintegro.","Desde el momento del pago de la subvención hasta la fecha en que se acuerde el reintegro."],"bloque":"subv-reintegro","precepto":"art. 37.1","correcta":3,"justificaciones":["No. El interés se cuenta desde el pago hasta que se acuerde el reintegro, no hasta que se inicie el procedimiento (**art. 37.1**).","No. El inicio es desde el pago y no desde la concesión, y llega hasta el acuerdo de reintegro (**art. 37.1**).","No. Se cuenta desde el pago, no desde la concesión (**art. 37.1**).","Es esta. Desde el pago de la subvención hasta la fecha en que se acuerde la procedencia del reintegro, o hasta que el deudor ingrese si es antes (**art. 37.1**)."]},{"id":"au-29-007","origen":"autoevaluacion","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":7,"enunciado":"En materia de subvenciones y según la Ley General de Subvenciones, son infracciones graves:","opciones":["La falta de suministro de información por parte de las administraciones a la Base de Datos Nacional de Subvenciones.","La obtención de la subvención falseando las condiciones requeridas para su concesión.","El incumplimiento de las obligaciones de conservación de justificantes o documentos equivalentes.","La presentación de cuentas justificativas inexactas o incompletas."],"bloque":"subv-sanciones","precepto":"art. 57.f","correcta":0,"justificaciones":["Es esta. Es infracción grave que las administraciones obligadas no suministren información a la Base de Datos Nacional de Subvenciones (**art. 57.f**).","No. Obtener la subvención falseando las condiciones es infracción muy grave (**art. 58.a**).","No. Incumplir la conservación de justificantes es infracción leve (**art. 56.e**).","No. Presentar cuentas justificativas inexactas o incompletas es infracción leve (**art. 56.b**)."]},{"id":"au-29-008","origen":"autoevaluacion","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":8,"enunciado":"Según el artículo 42 de la LGS, respecto al procedimiento de reintegro, ¿cuál de las siguientes afirmaciones es correcta?","opciones":["Podrá iniciarse de oficio o por solicitud de persona interesada.","No se regirá por las disposiciones generales contenidas en la Ley del Procedimiento Administrativo Común.","El plazo máximo para resolver y notificar la resolución será de 12 meses desde la fecha del acuerdo de iniciación.","Contra la resolución del procedimiento de reintegro no cabrá recurso en vía administrativa."],"bloque":"subv-reintegro","precepto":"art. 42.4","correcta":2,"justificaciones":["No. El reintegro se inicia siempre de oficio, no a solicitud del interesado (**art. 42.2**).","No. Se rige por las disposiciones generales del procedimiento administrativo común (**art. 42.1**).","Es esta. El plazo máximo para resolver y notificar es de 12 meses desde la fecha del acuerdo de iniciación (**art. 42.4**).","No. La resolución pone fin a la vía administrativa (**art. 42.5**), pero cabe el recurso potestativo de reposición o el contencioso."]},{"id":"au-29-009","origen":"autoevaluacion","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":9,"enunciado":"Según el artículo 65 de la LGS, ¿en qué plazo prescriben las infracciones en materia de subvenciones?","opciones":["Tres años, a contar desde el día de su comisión, cuando esta tenga carácter grave.","Cinco años, a contar desde el día de su comisión, cuando esta tenga carácter muy grave.","Un año, a contar desde el día de su comisión, cuando esta tenga carácter leve.","Cuatro años, a contar desde el día en que la infracción se hubiera cometido."],"bloque":"subv-sanciones","precepto":"art. 65.1","correcta":3,"justificaciones":["No. Las infracciones prescriben a los cuatro años, también las graves (**art. 65.1**).","No. El plazo es de cuatro años, también para las muy graves (**art. 65.1**).","No. El plazo de un año no distingue las leves. Todas prescriben a los cuatro años (**art. 65.1**).","Es esta. Las infracciones prescriben a los cuatro años desde el día de su comisión, sea cual sea su gravedad (**art. 65.1**)."]},{"id":"au-29-010","origen":"autoevaluacion","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":10,"enunciado":"¿Qué órgano es competente exigir del beneficiario o entidad colaboradora el reintegro de subvenciones?","opciones":["El Tribunal de Cuentas.","El Consejo de Ministros.","El órgano concedente de la subvención.","La Intervención General del Estado."],"bloque":"subv-reintegro","precepto":"art. 41.1","correcta":2,"justificaciones":["No. El Tribunal de Cuentas no exige el reintegro en vía administrativa (**art. 41.1**).","No. El Consejo de Ministros no es el competente (**art. 41.1**).","Es esta. El órgano concedente exige el reintegro mediante la resolución del procedimiento (**art. 41.1**).","No. La Intervención General controla, pero no exige el reintegro (**art. 41.1**)."]},{"id":"au-29-011","origen":"autoevaluacion","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":11,"enunciado":"Si transcurre el plazo para resolver el procedimiento de reintegro sin que se haya notificado resolución expresa:","opciones":["Se produce la caducidad del procedimiento.","Será desestimatorio el silencio administrativo.","Se produce la prescripción del procedimiento.","Será estimatorio el silencio administrativo."],"bloque":"subv-reintegro","precepto":"art. 42.4","correcta":0,"justificaciones":["Es esta. Si pasa el plazo sin resolución expresa, se produce la caducidad del procedimiento (**art. 42.4**).","No. No hay silencio desestimatorio. La ley prevé la caducidad (**art. 42.4**).","No. Lo que prescribe es el derecho a reintegrar. El procedimiento caduca (**art. 42.4**).","No. No hay silencio estimatorio. La ley prevé la caducidad (**art. 42.4**)."]},{"id":"au-29-012","origen":"autoevaluacion","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":12,"enunciado":"Señale la afirmación correcta. De acuerdo con la Ley 38/2003, será nula la resolución de una concesión que:","opciones":["Se otorgue a favor de persona que no haya justificado la entrega de los fondos percibidos.","Se otorgue careciendo de crédito suficiente consignado al efecto.","Sea constitutiva de infracción administrativa.","Adolezca de un defecto de forma."],"bloque":"subv-reintegro","precepto":"art. 36.1.b","correcta":1,"justificaciones":["No. No justificar fondos anteriores es causa de prohibición de ser beneficiario (**art. 13**), no de nulidad.","Es esta. Es causa de nulidad de la resolución de concesión la carencia o insuficiencia de crédito (**art. 36.1.b**).","No. Ser constitutiva de infracción administrativa no la anula. La causa de nulidad es un acto constitutivo de delito (**art. 36.1.a**).","No. Un defecto de forma es, como mucho, causa de anulabilidad (**art. 36.2**)."]},{"id":"au-29-013","origen":"autoevaluacion","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":13,"enunciado":"El plazo de prescripción de una infracción muy grave en el ámbito de la Ley 38/2003, General de Subvenciones es de:","opciones":["4 años.","3 años.","2 años.","5 años."],"bloque":"subv-sanciones","precepto":"art. 65.1","correcta":0,"justificaciones":["Es esta. Todas las infracciones prescriben a los cuatro años desde su comisión, también las muy graves (**art. 65.1**).","No. Tres años no es el plazo (**art. 65.1**).","No. Dos años no es el plazo (**art. 65.1**).","No. Cinco años no es el plazo. Son cuatro (**art. 65.1**)."]},{"id":"au-29-014","origen":"autoevaluacion","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":14,"enunciado":"¿Cuál de estas no es una causa de reintegro establecida en el artículo 37 de la LGS?","opciones":["La carencia o insuficiencia de crédito.","Obtención de la subvención falseando las condiciones requeridas para ello.","Incumplimiento de la obligación de justificación o la justificación insuficiente.","Incumplimiento de la obligación de adoptar las medidas de difusión."],"bloque":"subv-reintegro","precepto":"art. 37.1","correcta":0,"justificaciones":["Es la que no es causa de reintegro. La carencia o insuficiencia de crédito es causa de nulidad de la concesión (**art. 36.1.b**).","Sí es causa de reintegro. Obtener la subvención falseando las condiciones (**art. 37.1.a**).","Sí es causa de reintegro. No justificar o justificar de forma insuficiente (**art. 37.1.c**).","Sí es causa de reintegro. No adoptar las medidas de difusión (**art. 37.1.d**)."]},{"id":"au-29-015","origen":"autoevaluacion","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":15,"enunciado":"Cuando el importe de las subvenciones supere el coste de la actividad subvencionada, aisladamente o en concurrencia con otras, procederá:","opciones":["El reintegro del exceso obtenido con exigencia del interés de demora.","El reintegro del exceso obtenido sin exigencia del interés de demora.","El reintegro total de la subvención.","El inicio de revisión de oficio por parte de la administración con la devolución del importe de la subvención."],"bloque":"subv-reintegro","precepto":"art. 37.3","correcta":0,"justificaciones":["Es esta. Procede reintegrar el exceso sobre el coste de la actividad, con el interés de demora (**art. 37.3**).","No. El reintegro del exceso lleva interés de demora (**art. 37.3**).","No. Se reintegra el exceso, no la subvención entera (**art. 37.3**).","No. No hay revisión de oficio cuando concurre una causa de reintegro (**art. 36.5**)."]},{"id":"au-29-016","origen":"autoevaluacion","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":16,"enunciado":"¿Cuál de estas afirmaciones sobre el procedimiento de reintegro establecido en la LGS NO es correcta?","opciones":["Prescribirá a los cuatro años el derecho de la Administración a reconocer o liquidar el reintegro.","Los procedimientos para la exigencia del reintegro de las subvenciones, tendrán siempre carácter administrativo.","Los beneficiarios en los casos del artículo 37, deberán reintegrar la totalidad o parte de las cantidades percibidas, más los intereses de demora.","Este procedimiento será incompatible con el procedimiento sancionador establecido en la Ley."],"bloque":"subv-reintegro","precepto":"art. 40.1","correcta":3,"justificaciones":["Es verdadera. El derecho a reconocer o liquidar el reintegro prescribe a los cuatro años (**art. 39.1**).","Es verdadera. Los procedimientos de reintegro tienen siempre carácter administrativo (**art. 38.4**).","Es verdadera. En los casos del art. 37 se reintegra todo o parte más los intereses de demora (**art. 40.1**).","Es la falsa. La obligación de reintegro es independiente de las sanciones que puedan exigirse (**art. 40.1**)."]},{"id":"au-29-017","origen":"autoevaluacion","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":17,"enunciado":"¿Cuál de estas afirmaciones es correcta sobre el procedimiento de reintegro?","opciones":["Es un procedimiento sancionador.","El órgano concedente será el competente para exigir el reintegro.","El plazo de resolución será de 6 meses.","No es obligatorio el trámite de audiencia al interesado."],"bloque":"subv-reintegro","precepto":"art. 41.1","correcta":1,"justificaciones":["No. El reintegro no es un procedimiento sancionador. Es independiente de las sanciones (**art. 40.1**).","Es esta. El órgano concedente es el competente para exigir el reintegro (**art. 41.1**).","No. El plazo es de doce meses, no de seis (**art. 42.4**).","No. Se garantiza siempre el derecho de audiencia del interesado (**art. 42.3**)."]},{"id":"au-29-018","origen":"autoevaluacion","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":18,"enunciado":"¿Cuál de estas es una falta muy grave tipificada en la Ley 38/2003?","opciones":["El incumplimiento de las obligaciones de conservación de justificantes.","La falta de entrega, por parte de las entidades colaboradoras, a los beneficiarios de los fondos recibidos.","El incumplimiento de las condiciones establecidas alterando sustancialmente los fines para los que la subvención fue concedida.","El incumplimiento de la obligación de colaboración."],"bloque":"subv-sanciones","precepto":"art. 58.d","correcta":1,"justificaciones":["No. Incumplir la conservación de justificantes es infracción leve (**art. 56.e**).","Es esta. Es muy grave que las entidades colaboradoras no entreguen a los beneficiarios los fondos recibidos (**art. 58.d**).","No. Alterar sustancialmente los fines de la subvención es infracción grave (**art. 57.b**).","No. El incumplimiento de la obligación de colaboración es, con carácter general, infracción leve (**art. 56.h**)."]},{"id":"au-29-019","origen":"autoevaluacion","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":19,"enunciado":"Las sanciones en materia de subvenciones serán acordadas e impuestas por:","opciones":["En el caso de organismos autónomos el director del mismo.","El Consejo de Ministros.","El Tribunal de Cuentas.","Los Ministros o los Secretarios de Estado."],"bloque":"subv-sanciones","precepto":"art. 66.1","correcta":3,"justificaciones":["No. En el caso de organismos autónomos sanciona el titular del ministerio al que estén adscritos (**art. 66.1**).","No. El Consejo de Ministros no es el órgano sancionador de la ley (**art. 66.1**).","No. El Tribunal de Cuentas no impone sanciones de subvenciones (**art. 66.1**).","Es esta. Las sanciones las acuerdan e imponen los ministros o los secretarios de Estado de los departamentos concedentes (**art. 66.1**)."]},{"id":"au-29-020","origen":"autoevaluacion","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":20,"enunciado":"Según la LGS, cuando la sanción consista en la pérdida de la posibilidad de obtener subvenciones, ayudas públicas y avales de Estado será competente para sancionar:","opciones":["El Consejo de Ministros.","El Presidente del Gobierno.","El Ministro de Hacienda.","Los ministros o secretarios de estado."],"bloque":"subv-sanciones","precepto":"art. 66.1","correcta":2,"justificaciones":["No. El Consejo de Ministros no tiene esa competencia (**art. 66.1**).","No. El Presidente del Gobierno no sanciona en esta materia (**art. 66.1**).","Es esta. Si la sanción es perder la posibilidad de obtener subvenciones, ayudas o avales, o contratar, es competente el Ministro de Hacienda (**art. 66.1**).","No. La regla general (ministros y secretarios de Estado) cede ante esta excepción (**art. 66.1**)."]},{"id":"au-29-021","origen":"autoevaluacion","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":21,"enunciado":"De acuerdo con la Ley 38/2003, ¿qué tipo de actuaciones puede incluir el control financiero?","opciones":["La comprobación material de las inversiones financiadas.","Supervisión externa mediante auditoría.","Exclusivamente revisiones contables.","Solo control previo de legalidad."],"bloque":"subv-reintegro","precepto":"art. 44.4.d","correcta":0,"justificaciones":["Es esta. Entre las actuaciones del control financiero está la comprobación material de las inversiones financiadas (**art. 44.4.d**).","No. La ley no recoge una 'supervisión externa mediante auditoría' como forma de control financiero (**art. 44.4**).","No. El control financiero no se limita a revisiones contables (**art. 44.4**).","No. No es solo un control previo de legalidad. Verifica la obtención, la aplicación y la justificación (**art. 44.2**)."]},{"id":"au-29-022","origen":"autoevaluacion","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":22,"enunciado":"Según la Disposición adicional quinta de la Ley 38/2003 a las ayudas en especie, se le aplicará la LGS cuando:","opciones":["Se transfieran derechos de forma onerosa.","Los bienes sean usados.","El beneficiario sea una empresa pública.","La adquisición de los bienes se realice con la finalidad exclusiva de entregarlos a un tercero."],"bloque":"subv-general","precepto":"DA 5.ª.2","correcta":3,"justificaciones":["No. La entrega gratuita de bienes se rige por la legislación patrimonial (**DA 5.ª.1**). El carácter oneroso no es el criterio.","No. Que los bienes sean usados no es el criterio (**DA 5.ª**).","No. La condición de empresa pública del beneficiario no es el criterio (**DA 5.ª**).","Es esta. Se aplica la ley cuando los bienes se adquieren con la finalidad exclusiva de entregarlos a un tercero (**DA 5.ª.2**)."]},{"id":"au-29-023","origen":"autoevaluacion","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":23,"enunciado":"El procedimiento de reintegro de subvenciones:","opciones":["Se inicia de oficio por acuerdo del órgano competente.","Se inicia exclusivamente como consecuencia de denuncia.","Se inicia siempre mediante informe de la IGAE.","Se inicia siempre a instancia del beneficiario."],"bloque":"subv-reintegro","precepto":"art. 42.2","correcta":0,"justificaciones":["Es esta. Se inicia de oficio por acuerdo del órgano competente (**art. 42.2**).","No. La denuncia es una de las vías, pero no la única (**art. 42.2**).","No. También puede iniciarse por informe de control financiero de la IGAE, pero no siempre así (**art. 42.2**).","No. Nunca se inicia a instancia del beneficiario, sino de oficio (**art. 42.2**)."]},{"id":"au-29-024","origen":"autoevaluacion","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":24,"enunciado":"Constituye una infracción leve en materia de subvenciones:","opciones":["La no aplicación de las cantidades recibidas a los fines para los que la subvención fue concedida.","La obtención de una subvención falseando las condiciones requeridas para su concesión.","La presentación fuera de plazo de las cuentas justificativas de la aplicación dada a los fondos percibidos.","La falta de entrega, por una entidad colaboradora, de los fondos recibidos a los beneficiarios cuando así se establezca."],"bloque":"subv-sanciones","precepto":"art. 56.a","correcta":2,"justificaciones":["No. No aplicar las cantidades recibidas a sus fines es infracción muy grave (**art. 58.b**).","No. Obtener la subvención falseando las condiciones es infracción muy grave (**art. 58.a**).","Es esta. Presentar fuera de plazo las cuentas justificativas es infracción leve (**art. 56.a**).","No. La falta de entrega de fondos por la entidad colaboradora es infracción muy grave (**art. 58.d**)."]},{"id":"au-29-025","origen":"autoevaluacion","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":25,"enunciado":"Una entidad comete una infracción grave en materia de subvenciones, ¿qué sanción no pecuniaria podría imponerse conforme al artículo 59?","opciones":["La prohibición de obtener subvenciones durante un máximo de diez años.","La prohibición de contratar con las Administraciones públicas durante un plazo mínimo de diez años.","La pérdida o prohibición, durante un plazo de hasta cinco años, de obtener subvenciones, actuar como entidad colaboradora o contratar con las Administraciones públicas.","La pérdida definitiva de la personalidad jurídica."],"bloque":"subv-sanciones","precepto":"art. 59.3","correcta":2,"justificaciones":["No. El máximo es de cinco años, no de diez (**art. 59.3.a**).","No. La prohibición de contratar tiene un máximo de cinco años, no un mínimo de diez (**art. 59.3.c**).","Es esta. Las sanciones no pecuniarias consisten en perder, hasta cinco años, la posibilidad de obtener subvenciones, de ser entidad colaboradora o de contratar con las Administraciones (**art. 59.3**).","No. La pérdida de la personalidad jurídica no es una sanción de la ley (**art. 59.3**)."],"ojo":"Para infracciones graves, el art. 62.2 limita esas sanciones a tres años y exige además que el perjuicio supere el 50 % de la subvención y los 30.000 euros. La pregunta cita el art. 59 y se resuelve por él.","revisar":"Graves: el art. 62.2 limita a tres años. La opción correcta habla de cinco (art. 59.3), que es el máximo general."},{"id":"of-08-001","origen":"oficiales","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":1,"enunciado":"Desde la perspectiva administrativa, las subvenciones son una técnica de:","opciones":["Limitación.","Arbitral.","De servicio público.","Fomento."],"bloque":"subv-general","precepto":"concepto de subvención","correcta":3,"justificaciones":["No. La limitación restringe derechos, y la subvención los favorece.","No. La actividad arbitral es de resolución de conflictos.","No. El servicio público es la prestación directa de servicios, y la subvención no lo es.","Es esta. La subvención es una técnica de fomento: estimula actividades de interés general mediante una ayuda."],"revisar":"Pregunta de doctrina. No consta en la Ley 38/2003 con esas palabras. Razonada con doctrina general.","dup":"of-08-001"},{"id":"of-08-002","origen":"oficiales","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":2,"enunciado":"Indique cuál de las siguientes respuestas se refiere a una actividad administrativa de fomento:","opciones":["La ejecución de las obras de construcción de una carretera nacional por parte del Ministerio de Fomento.","La concesión del Premio Nacional de Literatura por parte del Ministerio de Educación, Cultura y Deporte.","La vacunación a viajeros en un Centro de Vacunación Internacional de una Subdelegación del Gobierno.","La concesión de una licencia para la ocupación del dominio público por parte de un Ayuntamiento."],"bloque":"subv-general","precepto":"concepto de fomento","correcta":1,"justificaciones":["No. Construir una carretera es prestar un servicio público.","Es esta. Un premio es un incentivo honorífico, una modalidad de fomento.","No. Vacunar es prestación de un servicio público.","No. La licencia sobre el dominio público es una actividad de limitación o intervención."],"revisar":"Pregunta de doctrina. No consta en la Ley 38/2003 con esas palabras. Razonada con doctrina general.","dup":"of-08-002"},{"id":"of-08-003","origen":"oficiales","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":3,"enunciado":"De acuerdo con la Ley 38/2003, de 17 de noviembre, quedan incluidas dentro del ámbito de la Ley:","opciones":["Las subvenciones por ayudas sociales otorgadas por un Ayuntamiento.","La subvención otorgada a un grupo parlamentario del Congreso de las Diputados.","Las subvenciones previstas en la Ley Orgánica 5/1985, de 19 de junio, para el Régimen Electoral General.","Los premios que se otorgan sin solicitud del beneficiario."],"bloque":"subv-general","precepto":"arts. 3 y 4","correcta":0,"justificaciones":["Es esta. Las Entidades Locales son Administraciones públicas a efectos de la ley, y sus ayudas sociales entran en ella (**art. 3**).","No. Las subvenciones a los grupos parlamentarios de las Cortes están excluidas (**art. 4.d**).","No. Las subvenciones de la ley electoral están excluidas (**art. 4.b**).","No. Los premios sin solicitud del beneficiario están excluidos (**art. 4.a**)."]},{"id":"of-08-004","origen":"oficiales","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":4,"enunciado":"Señale la afirmación correcta. De acuerdo la Ley 38/2003, la subvención es un instrumento de la actividad administrativa:","opciones":["De servicio público.","Arbitral.","De limitación.","De fomento."],"bloque":"subv-general","precepto":"concepto de subvención","correcta":3,"justificaciones":["No. El servicio público es la prestación directa de servicios, y la subvención no lo es.","No. La actividad arbitral es de resolución de conflictos.","No. La limitación restringe derechos, y la subvención los favorece.","Es esta. La subvención es un instrumento de fomento: persigue una actividad de utilidad pública o interés social (**art. 2.1.c**)."],"revisar":"El término fomento es doctrina. El art. 2.1.c habla de fomento de una actividad de utilidad pública o interés social."},{"id":"of-08-005","origen":"oficiales","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":5,"enunciado":"Conforme a la LGS, ¿cuál de las siguientes subvenciones está incluida dentro de la aplicación de esta Ley?","opciones":["Los premios que se otorguen sin la previa solicitud del beneficiario.","Las subvenciones previstas en la Ley Orgánica 5/1985, de 19 de junio, del Régimen Electoral General.","Las previstas nominativamente en los Presupuestos Generales del Estado.","Las subvenciones a los grupos parlamentarios de las Cámaras de las Cortes Generales."],"bloque":"subv-general","precepto":"art. 22.2.a","correcta":2,"justificaciones":["No. Los premios sin solicitud están excluidos (**art. 4.a**).","No. Las subvenciones de la ley electoral están excluidas (**art. 4.b**).","Es esta. Las subvenciones previstas nominativamente en los Presupuestos están dentro de la ley y se conceden de forma directa (**art. 22.2.a**).","No. Las de los grupos parlamentarios de las Cortes están excluidas (**art. 4.d**)."]},{"id":"of-08-006","origen":"oficiales","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":6,"enunciado":"Indique la afirmación correcta en relación con el concepto de subvención y el ámbito de aplicación de la Ley 38/2003:","opciones":["La entrega ha de estar sujeta al cumplimiento de un determinado objetivo, ya realizado a fecha de la convocatoria.","Tienen carácter de subvención las prestaciones no contributivas del Sistema de la Seguridad Social.","Están excluidas del ámbito de aplicación de la Ley los premios que se otorguen a solicitud del beneficiario.","No tienen carácter de subvención las prestaciones reconocidas por el Fondo de Garantía Salarial."],"bloque":"subv-general","precepto":"art. 2.4.f","correcta":3,"justificaciones":["No. El objetivo puede estar ya realizado o por desarrollar (**art. 2.1.b**).","No. Las prestaciones contributivas y no contributivas de la Seguridad Social no son subvenciones (**art. 2.4.a**).","No. Lo que está excluido son los premios sin solicitud, no los que se otorgan a solicitud (**art. 4.a**).","Es esta. Las prestaciones del Fondo de Garantía Salarial no son subvenciones (**art. 2.4.f**)."]},{"id":"of-08-007","origen":"oficiales","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":7,"enunciado":"Quedan incluidos en el ámbito de aplicación de la Ley 38/2003, de 17 de noviembre, General de Subvenciones:","opciones":["Los premios que se otorguen previa solicitud del beneficiario.","Las subvenciones previstas en la Ley Orgánica 5/1985, de 19 de junio, del Régimen Electoral General.","Las subvenciones reguladas en la Ley Orgánica 3/1987, de 2 de julio, de Financiación de los Partidos Políticos.","Las subvenciones a los grupos parlamentarios de las Cámaras de las Cortes Generales."],"bloque":"subv-general","precepto":"art. 4.a","correcta":0,"justificaciones":["Es esta. Los premios otorgados previa solicitud sí entran en la ley. Solo quedan fuera los que se dan sin solicitud (**art. 4.a**).","No. Están excluidas las de la ley electoral (**art. 4.b**).","No. Están excluidas las de la ley de partidos (**art. 4.c**).","No. Están excluidas las de los grupos parlamentarios (**art. 4.d**)."]},{"id":"of-08-008","origen":"oficiales","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":8,"enunciado":"Según la Ley General de Subvenciones, ¿qué régimen jurídico le será de aplicación a una subvención concedida por el Estado a agricultores afectados por la sequía en la comunidad autónoma de Madrid?","opciones":["Las normas de derecho privado en todo caso.","El derecho autonómico, dado que las subvenciones van dirigidas a varias Comunidades Autónomas.","El derecho privado y las restantes normas de desarrollo y, en su defecto, el derecho administrativo.","Ley General de Subvenciones y sus disposiciones de desarrollo, las restantes normas de derecho administrativo y, en su defecto, las normas de derecho privado."],"bloque":"subv-general","precepto":"art. 5.1","correcta":3,"justificaciones":["No. No se rigen por el derecho privado en todo caso (**art. 5.1**).","No. Es una subvención del Estado y se rige por la ley estatal (**art. 5.1**).","No. El derecho privado va en último lugar, no en primero (**art. 5.1**).","Es esta. Se rigen por la ley y sus disposiciones de desarrollo, las restantes normas de derecho administrativo y, en su defecto, el derecho privado (**art. 5.1**)."]},{"id":"of-08-009","origen":"oficiales","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":9,"enunciado":"Las subvenciones a los grupos parlamentarios de las Cámaras de las Cortes Generales, según la Ley 38/2003, ¿están incluidas en el ámbito de aplicación?","opciones":["Están explícitamente excluidas del ámbito de aplicación.","Están explícitamente incluidas en el ámbito de aplicación.","No tienen acceso a ningún tipo de subvenciones, si bien la Ley permite el acceso a los grupos parlamentarios de las cámaras regionales.","Están explícitamente incluidas sólo las de los grupos con representación en más de la mitad de las Comunidades Autónomas."],"bloque":"subv-general","precepto":"art. 4.d","correcta":0,"justificaciones":["Es esta. Las subvenciones a los grupos parlamentarios de las Cortes están expresamente excluidas (**art. 4.d**).","No. Están excluidas, no incluidas (**art. 4.d**).","No. La ley las menciona para excluirlas, y no distingue por cámaras regionales (**art. 4.d**).","No. La exclusión no depende de la representación en las Comunidades Autónomas (**art. 4.d**)."]},{"id":"of-08-010","origen":"oficiales","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":10,"enunciado":"Según el artículo 2.4 de la Ley 38/2003, de 17 de noviembre, General de Subvenciones, no tienen carácter de subvenciones:","opciones":["Las otorgadas como consecuencia de la Política Agrícola Común.","Las que financien proyectos relacionados con la ciencia y la tecnología.","Los beneficios fiscales y beneficios en la cotización a la Seguridad Social.","Las destinadas a fomentar actividades de interés social."],"bloque":"subv-general","precepto":"art. 2.4.g","correcta":2,"justificaciones":["No. Las ayudas de la PAC se financian con fondos de la Unión y se rigen por su normativa (**art. 6**), pero siguen siendo subvenciones.","No. Financiar proyectos de ciencia es un fin que puede subvencionarse (**art. 2.1.c**).","Es esta. Los beneficios fiscales y los beneficios en la cotización a la Seguridad Social no son subvenciones (**art. 2.4.g**).","No. Fomentar actividades de interés social es el objeto típico de una subvención (**art. 2.1.c**)."],"dup":"of-08-010"},{"id":"of-08-011","origen":"oficiales","test":"Tema 5 (1) - LGS (arts 1 a 6)","n":11,"enunciado":"Según el artículo 6 de la Ley 38/2003, ¿cuál de las siguientes afirmaciones sobre las subvenciones financiadas con cargo a fondos de la Unión Europea es correcta?","opciones":["Se rigen por la Ley General de Subvenciones y, en su defecto, por el derecho privado nacional.","Se rigen por las normas comunitarias aplicables y las normas nacionales de desarrollo o transposición, siendo la Ley General de Subvenciones de aplicación supletoria respecto de las normas de aplicación directa de la Unión Europea.","Se rigen exclusivamente por la normativa nacional de desarrollo o transposición de las normas comunitarias aplicables.","Los procedimientos de concesión y control de la Ley General de Subvenciones tienen carácter preferente sobre las normas comunitarias de aplicación directa."],"bloque":"subv-general","precepto":"art. 6","correcta":1,"justificaciones":["No. Se rigen primero por las normas comunitarias, y la ley es solo supletoria (**art. 6**).","Es esta. Se rigen por las normas comunitarias y las nacionales de desarrollo, y la ley es supletoria de las de aplicación directa (**art. 6.1 y 2**).","No. Las normas comunitarias de aplicación directa no se limitan a normas nacionales de transposición (**art. 6**).","No. Al contrario, los procedimientos de la ley son supletorios (**art. 6.2**)."]},{"id":"of-09-001","origen":"oficiales","test":"Tema 5 (2) - LGS (arts 8 a 21)","n":1,"enunciado":"Será requisito para la percepción de ayudas y subvenciones con cargo a los Presupuestos Generales del Estado el cumplimiento, por parte de los beneficiarios:","opciones":["Solo de sus obligaciones tributarias.","Solo de sus obligaciones frente a la Seguridad Social.","De sus obligaciones tributarias y frente a la Seguridad Social.","No necesitan acreditar cumplimiento alguno."],"bloque":"subv-general","precepto":"art. 13.2.e","correcta":2,"justificaciones":["No. También se exige estar al corriente con la Seguridad Social (**art. 13.2.e**).","No. También se exige estar al corriente con Hacienda (**art. 13.2.e**).","Es esta. Se exige estar al corriente de las obligaciones tributarias y frente a la Seguridad Social (**art. 13.2.e**).","No. Es requisito y hay que acreditarlo (**art. 13.2.e**)."]},{"id":"of-09-002","origen":"oficiales","test":"Tema 5 (2) - LGS (arts 8 a 21)","n":2,"enunciado":"En relación con la competencia para conceder subvenciones, de acuerdo con la Ley General de Subvenciones:","opciones":["Está atribuida exclusivamente al Ministro, aunque puede ser desconcentrada por Orden Ministerial.","Está atribuida a Ministro o Secretario de Estado, además de Presidentes o Directores de Organismos Públicos.","Está atribuida al Consejo de Ministros en aquellos casos en los que el valor de la subvención supere los seis millones de euros.","La LGS no hace referencia a la competencia para otorgarlas, por lo que se aplica supletoriamente la LCSP."],"bloque":"subv-general","precepto":"art. 10.1","correcta":1,"justificaciones":["No. También conceden los Secretarios de Estado y los presidentes o directores de organismos (**art. 10.1**).","Es esta. Conceden los Ministros, los Secretarios de Estado y los presidentes o directores de organismos y entidades vinculados (**art. 10.1**).","No. El umbral de autorización del Consejo de Ministros es de 12 millones, no de 6 (**art. 10.2**).","No. La ley sí regula la competencia, y la LCSP no es supletoria (**art. 10**)."]},{"id":"of-09-003","origen":"oficiales","test":"Tema 5 (2) - LGS (arts 8 a 21)","n":3,"enunciado":"Las subvenciones concedidas por las Administraciones Públicas deberán, con carácter general, publicarse en la BDNS. Dicha publicación no procederá, sin embargo, en el siguiente supuesto:","opciones":["Cuando la publicación de los datos del beneficiario en razón del objeto de la subvención pueda ser contraria al respeto y salvaguarda del honor de las personas físicas.","Si se ha concedido la subvención por el procedimiento de concurrencia competitiva.","Si se trata de ayudas públicas cofinanciadas con Fondos Estructurales.","Si los beneficiarios son personas físicas."],"bloque":"subv-general","precepto":"art. 20.8.b","correcta":0,"justificaciones":["Es esta. No se publican si la publicación puede ser contraria al honor o a la intimidad personal o familiar de las personas físicas (**art. 20.8.b**).","No. La concurrencia competitiva no exime de publicar (**art. 20.8**).","No. Cofinanciar con Fondos Estructurales no exime de publicar (**art. 20.8**).","No. Ser persona física no exime por sí solo. Hace falta riesgo para el honor o la intimidad (**art. 20.8.b**)."]},{"id":"of-09-004","origen":"oficiales","test":"Tema 5 (2) - LGS (arts 8 a 21)","n":4,"enunciado":"La Ley 38/2003, General de Subvenciones, determina que para poder otorgar una subvención:","opciones":["Deben aprobarse, con carácter previo a su otorgamiento, las normas que establezcan las bases reguladoras de la concesión.","Debe publicarse en el BOE la existencia de crédito adecuado y suficiente para su concesión.","Se aprobarán las bases reguladoras cuando se hayan fiscalizado los actos de contenido económico.","Deben aprobarse las bases reguladoras, una vez se ha tramitado el procedimiento de concesión."],"bloque":"subv-general","precepto":"art. 9.2","correcta":0,"justificaciones":["Es esta. Antes de otorgar la subvención deben aprobarse las bases reguladoras (**art. 9.2**).","No. La existencia de crédito es un requisito, pero no se publica en el BOE (**art. 9.4.b**).","No. Las bases se aprueban antes, no cuando se fiscalizan los actos (**art. 9.2**).","No. Las bases se aprueban antes de conceder, no después (**art. 9.2**)."]},{"id":"of-09-005","origen":"oficiales","test":"Tema 5 (2) - LGS (arts 8 a 21)","n":5,"enunciado":"Según la LGS, ¿qué órganos son competentes para la concesión de subvenciones en la AGE?","opciones":["Los Subdirectores generales de los Organismos Públicos con autorización previa del Presidente o Director correspondiente.","Los Ministros y los Secretarios de Estado y los Presidentes o Directores de los Organismos Públicos.","Los Subsecretarios y Directores Generales de los Departamentos Ministeriales en el ámbito de sus competencias.","Solamente el Consejo de Ministros."],"bloque":"subv-general","precepto":"art. 10.1","correcta":1,"justificaciones":["No. Los subdirectores generales no son órgano competente (**art. 10.1**).","Es esta. Son competentes los Ministros, los Secretarios de Estado y los presidentes o directores de los organismos (**art. 10.1**).","No. Subsecretarios y directores generales no tienen esta competencia (**art. 10.1**).","No. El Consejo de Ministros solo autoriza las de cuantía superior a 12 millones (**art. 10.2**)."]},{"id":"of-09-006","origen":"oficiales","test":"Tema 5 (2) - LGS (arts 8 a 21)","n":6,"enunciado":"Conforme a la Ley 38/2003, ¿cuál es el órgano responsable de la administración y custodia de la Base de Datos Nacional de Subvenciones?","opciones":["La Dirección General de Presupuestos.","La Subsecretaría del Ministerio Política Territorial y Función Pública.","La Intervención General de la Administración del Estado.","La Dirección General de Fondos Europeos."],"bloque":"subv-general","precepto":"art. 20.3","correcta":2,"justificaciones":["No. La Dirección General de Presupuestos no la administra (**art. 20.3**).","No. Esa Subsecretaría no la administra (**art. 20.3**).","Es esta. La Intervención General de la Administración del Estado administra y custodia la BDNS (**art. 20.3**).","No. Fondos Europeos no la administra (**art. 20.3**)."]},{"id":"of-09-007","origen":"oficiales","test":"Tema 5 (2) - LGS (arts 8 a 21)","n":7,"enunciado":"De conformidad con la Ley General de Subvenciones, el beneficiario de una subvención:","opciones":["Ha de ser una persona jurídica necesariamente, ya que las personas físicas reciben ayudas, no subvenciones.","Puede ser una persona física o jurídica.","Puede ser solo una persona física.","Solo podrá ser una persona física en el caso de que la entidad colaboradora sea una persona jurídica."],"bloque":"subv-general","precepto":"art. 11.1","correcta":1,"justificaciones":["No. Pueden ser también personas físicas (**art. 11.1**).","Es esta. Puede ser beneficiario una persona física o jurídica (**art. 11.1**).","No. También pueden ser personas jurídicas (**art. 11.1**).","No. La condición de beneficiario no depende de la entidad colaboradora (**art. 11.1**)."]},{"id":"of-09-008","origen":"oficiales","test":"Tema 5 (2) - LGS (arts 8 a 21)","n":8,"enunciado":"De conformidad con el artículo 10 de la Ley 38/2003, son órganos competentes para la concesión de subvenciones:","opciones":["La Comisión Delegada del Gobierno para asuntos económicos.","El Consejo de Ministros.","Los Ministros y Secretarios de Estado.","Los Directores Generales."],"bloque":"subv-general","precepto":"art. 10.1","correcta":2,"justificaciones":["No. Esa comisión no concede, solo puede autorizar (**art. 10.2**).","No. El Consejo de Ministros no concede, autoriza las de más de 12 millones (**art. 10.2**).","Es esta. Conceden los Ministros y los Secretarios de Estado (**art. 10.1**).","No. Los directores generales no figuran (**art. 10.1**)."]},{"id":"of-09-009","origen":"oficiales","test":"Tema 5 (2) - LGS (arts 8 a 21)","n":9,"enunciado":"Según el artículo 10 de la LGS, en un organismo autónomo, ¿quién es la autoridad competente para conceder una subvención de cuantía superior a 12 millones de euros?","opciones":["El titular del Departamento ministerial, con autorización del Consejo de Ministros.","El Presidente o Director, con autorización del titular del Departamento ministerial.","El Consejo de Ministros.","El Presidente o Director del organismo autónomo, con autorización del Consejo de Ministros."],"bloque":"subv-general","precepto":"art. 10.2","correcta":3,"justificaciones":["No. En el organismo concede su presidente o director, no el titular del Departamento (**art. 10.1**).","No. La autorización necesaria es la del Consejo de Ministros, no la del titular del Departamento (**art. 10.2**).","No. El Consejo de Ministros autoriza, pero no concede (**art. 10.2**).","Es esta. Concede el presidente o director del organismo, con autorización previa del Consejo de Ministros (**art. 10.1 y 2**)."]},{"id":"of-09-010","origen":"oficiales","test":"Tema 5 (2) - LGS (arts 8 a 21)","n":10,"enunciado":"Conforme a la Ley General de Subvenciones, no podrán obtener la condición de beneficiario de una subvención:","opciones":["Los que hayan dado lugar, por causa de la que hubiesen sido declarados culpables, a la resolución firme de cualquier contrato celebrado con la Administración.","Los que tengan la residencia fiscal fuera de España.","Los sancionados mediante resolución con la pérdida de la posibilidad de obtener subvenciones, aun cuando dicha resolución no sea firme.","Los condenados mediante sentencia a la pérdida de la posibilidad de obtener ayudas, aun cuando dicha sentencia no sea firme."],"bloque":"subv-general","precepto":"art. 13.2.c","correcta":0,"justificaciones":["Es esta. No puede ser beneficiario quien haya dado lugar, por causa de la que fuese declarado culpable, a la resolución firme de un contrato con la Administración (**art. 13.2.c**).","No. La prohibición es para residentes en paraísos fiscales, no para cualquier residencia fuera de España (**art. 13.2.f**).","No. La sanción debe ser firme (**art. 13.2.h**).","No. La sentencia debe ser firme (**art. 13.2.a**)."]},{"id":"of-09-011","origen":"oficiales","test":"Tema 5 (2) - LGS (arts 8 a 21)","n":11,"enunciado":"De acuerdo con la LGS, no tienen atribuida la competencia para la concesión de subvenciones:","opciones":["Los Ministros.","Los Presidentes o Directores de Organismos Autónomos.","Los Subsecretarios.","Los Secretarios de Estado."],"bloque":"subv-general","precepto":"art. 10.1","correcta":2,"justificaciones":["Sí tienen competencia. Los Ministros (**art. 10.1**).","Sí tienen competencia. Los presidentes o directores de organismos (**art. 10.1**).","Es esta. Los Subsecretarios no tienen atribuida la competencia (**art. 10.1**).","Sí tienen competencia. Los Secretarios de Estado (**art. 10.1**)."]},{"id":"of-09-012","origen":"oficiales","test":"Tema 5 (2) - LGS (arts 8 a 21)","n":12,"enunciado":"Conforme al artículo 10 de la LGS, la competencia para la concesión de subvenciones corresponde a:","opciones":["Los Secretarios Generales Técnicos.","El Consejo de Ministros cuando la cuantía sea superior a 12 millones de euros.","Los Directores Generales.","Los Ministros y Secretarios de Estado."],"bloque":"subv-general","precepto":"art. 10.1","correcta":3,"justificaciones":["No. Los secretarios generales técnicos no figuran (**art. 10.1**).","No. El Consejo de Ministros no concede. Autoriza las que superan 12 millones (**art. 10.2**).","No. Los directores generales no figuran (**art. 10.1**).","Es esta. Los Ministros y los Secretarios de Estado (**art. 10.1**)."]},{"id":"of-09-013","origen":"oficiales","test":"Tema 5 (2) - LGS (arts 8 a 21)","n":13,"enunciado":"De conformidad con lo previsto en la Ley 38/2003, requerirá la previa autorización del Consejo de Ministros o, en su caso, de la Comisión Delegada del Gobierno para Asuntos Económicos, la concesión de subvenciones de cuantía superior a:","opciones":["Quince millones de euros.","Doce millones de euros.","Diez millones de euros.","Veinte millones de euros."],"bloque":"subv-general","precepto":"art. 10.2","correcta":1,"justificaciones":["No. El umbral no es de quince millones (**art. 10.2**).","Es esta. Por encima de doce millones hace falta autorización previa del Consejo de Ministros o, si así lo establece la norma, de la Comisión Delegada (**art. 10.2**).","No. Diez millones es un umbral antiguo (**art. 10.2**).","No. El umbral no es de veinte millones (**art. 10.2**)."]},{"id":"of-09-014","origen":"oficiales","test":"Tema 5 (2) - LGS (arts 8 a 21)","n":14,"enunciado":"Conforme al artículo 10 de la LGS, la concesión de subvenciones en cuantía superior a 12 millones de euros requerirá la previa autorización de:","opciones":["La Comisión Delegada del Gobierno para Asuntos Económicos o, cuando así lo establezca la normativa de la subvención, del Consejo de Ministros.","El Consejo de Ministros y la Comisión Delegada del Gobierno para Asuntos Económicos.","El Consejo de Ministros o, cuando así lo establezca la normativa reguladora, de la Comisión Delegada del Gobierno para Asuntos Económicos.","El Consejo de Ministros, cuando así lo establezca la normativa reguladora de la subvención."],"bloque":"subv-general","precepto":"art. 10.2","correcta":2,"justificaciones":["No. La regla es el Consejo de Ministros, y la Comisión Delegada solo si lo establece la norma (**art. 10.2**).","No. Son alternativas, no acumulativas (**art. 10.2**).","Es esta. Consejo de Ministros o, si la normativa reguladora lo establece, la Comisión Delegada del Gobierno para Asuntos Económicos (**art. 10.2**).","No. El Consejo de Ministros es la regla general, no depende de lo que diga la norma (**art. 10.2**)."]},{"id":"of-09-015","origen":"oficiales","test":"Tema 5 (2) - LGS (arts 8 a 21)","n":15,"enunciado":"Conforme a la LGS, ¿cuál de los siguientes es un órgano competente para la concesión de subvenciones en la AGE?","opciones":["Los Subdirectores Generales.","La Comisión Delegada del Gobierno para Asuntos Económicos.","Los Secretarios de Estado.","La Comisión General de Secretarios de Estado y Subsecretarios."],"bloque":"subv-general","precepto":"art. 10.1","correcta":2,"justificaciones":["No. Los subdirectores generales no son órgano competente (**art. 10.1**).","No. La Comisión Delegada puede autorizar, pero no concede (**art. 10.2**).","Es esta. Los Secretarios de Estado son órgano competente (**art. 10.1**).","No. Esa Comisión no concede subvenciones (**art. 10.1**)."]},{"id":"of-09-016","origen":"oficiales","test":"Tema 5 (2) - LGS (arts 8 a 21)","n":16,"enunciado":"¿Cuál de los siguientes NO es uno de los requisitos enumerados en el artículo 9 de la LGS?","opciones":["La comunicación posterior al Tribunal de Cuentas.","La fiscalización previa de los actos administrativos de contenido económico.","La aprobación del gasto.","La existencia de crédito adecuado y suficiente."],"bloque":"subv-general","precepto":"art. 9","correcta":0,"justificaciones":["Es esta. La comunicación posterior al Tribunal de Cuentas no es requisito del art. 9. Lo que se comunica, antes, es a la Comisión Europea cuando procede (**art. 9.1**).","Sí es requisito. La fiscalización previa de los actos de contenido económico (**art. 9.4.d**).","Sí es requisito. La aprobación del gasto por el órgano competente (**art. 9.4.e**).","Sí es requisito. La existencia de crédito adecuado y suficiente (**art. 9.4.b**)."]},{"id":"of-09-017","origen":"oficiales","test":"Tema 5 (2) - LGS (arts 8 a 21)","n":17,"enunciado":"Conforme a la LGS, ¿cuál de los siguientes NO es un requisito que debe cumplir el otorgamiento de una subvención?","opciones":["La audiencia pública.","La tramitación del procedimiento de concesión de acuerdo con las normas que resulten de aplicación.","La competencia del órgano administrativo concedente.","La existencia de crédito adecuado y suficiente para atender las obligaciones económicas derivadas de la concesión."],"bloque":"subv-general","precepto":"art. 9.4","correcta":0,"justificaciones":["Es esta. La audiencia pública no es requisito del otorgamiento (**art. 9.4**).","Sí es requisito. La tramitación del procedimiento según las normas aplicables (**art. 9.4.c**).","Sí es requisito. La competencia del órgano concedente (**art. 9.4.a**).","Sí es requisito. La existencia de crédito adecuado y suficiente (**art. 9.4.b**)."]},{"id":"of-09-018","origen":"oficiales","test":"Tema 5 (2) - LGS (arts 8 a 21)","n":18,"enunciado":"El plan en el que se concretan los objetivos y efectos que se pretenden con las subvenciones a otorgar por un Departamento Ministerial, el plazo necesario para su consecución, los costes previsibles y sus fuentes de financiación, se denomina:","opciones":["Plan anual de subvenciones.","Plan estratégico de subvenciones.","Plan trienal de subvenciones.","Plan plurianual de subvenciones."],"bloque":"subv-general","precepto":"art. 8.1","correcta":1,"justificaciones":["No. La ley no habla de plan anual (**art. 8.1**).","Es esta. Es el plan estratégico de subvenciones (**art. 8.1**).","No. La ley no lo llama trienal (**art. 8.1**).","No. La ley no lo llama plurianual (**art. 8.1**)."]},{"id":"of-09-019","origen":"oficiales","test":"Tema 5 (2) - LGS (arts 8 a 21)","n":19,"enunciado":"Según establece el artículo 20 de la Ley 38/2003, ¿quién es el órgano responsable de la administración y custodia de la Base de Datos Nacional de Subvenciones (BDNS)?","opciones":["Intervención General de la Administración del Estado.","Secretaría de Estado de Hacienda.","Agencia Estatal de Administración Tributaria.","Ninguna de las respuestas anteriores es correcta."],"bloque":"subv-general","precepto":"art. 20.3","correcta":0,"justificaciones":["Es esta. La Intervención General de la Administración del Estado (**art. 20.3**).","No. La Secretaría de Estado de Hacienda no la administra (**art. 20.3**).","No. La Agencia Tributaria no la administra (**art. 20.3**).","No. Sí hay una respuesta correcta (**art. 20.3**)."],"dup":"of-09-019"},{"id":"of-09-020","origen":"oficiales","test":"Tema 5 (2) - LGS (arts 8 a 21)","n":20,"enunciado":"La aprobación de las bases reguladoras de las subvenciones, a nivel estatal, se lleva a cabo por:","opciones":["Real Decreto del Consejo de Ministros.","Orden Ministerial.","Resolución, o en su caso, instrucción.","Ley Orgánica."],"bloque":"subv-general","precepto":"art. 17.2","correcta":1,"justificaciones":["No. No se aprueban por real decreto (**art. 17.2**).","Es esta. Se aprueban por orden ministerial (**art. 17.2**).","No. La resolución o instrucción no es la forma de aprobar las bases en la AGE (**art. 17.2**).","No. No se aprueban por ley orgánica (**art. 17.2**)."]},{"id":"of-09-021","origen":"oficiales","test":"Tema 5 (2) - LGS (arts 8 a 21)","n":21,"enunciado":"De acuerdo con el artículo 10 de la Ley 38/2003, ¿quién tiene la competencia para la concesión de una subvención de cuantía de 10 millones de euros en un Organismo Autónomo?","opciones":["El Presidente o Director del Organismo Autónomo, sin que esta competencia pueda ser objeto de desconcentración.","El Presidente o Director del Organismo Autónomo previa autorización del Consejo de Ministros, sin que esta competencia pueda ser objeto de desconcentración.","El Presidente o Director del Organismo Autónomo; esta competencia podrá ser objeto de desconcentración.","El Presidente o Director del Organismo Autónomo previa autorización del Consejo de Ministros; esta competencia podrá ser objeto de desconcentración."],"bloque":"subv-general","precepto":"art. 10","correcta":2,"justificaciones":["No. Sí puede desconcentrarse (**art. 10.3**).","No. Diez millones no supera el umbral de 12, así que no hace falta autorización, y además sí puede desconcentrarse (**art. 10.2 y 3**).","Es esta. Concede su presidente o director, sin autorización por no superar 12 millones, y la competencia puede desconcentrarse por real decreto (**art. 10.1, 2 y 3**).","No. No hace falta autorización con diez millones (**art. 10.2**)."],"dup":"of-09-021"},{"id":"of-09-022","origen":"oficiales","test":"Tema 5 (2) - LGS (arts 8 a 21)","n":22,"enunciado":"Según lo dispuesto en el artículo 20 de la Ley 38/2003, ¿cuál de los siguientes es el órgano responsable de la administración y custodia de la Base de Datos Nacional de Subvenciones?","opciones":["El Ministerio de Hacienda.","La Intervención General de la Administración del Estado.","El Ministerio de Economía, Comercio y Empresa.","La Autoridad Independiente de Responsabilidad Fiscal."],"bloque":"subv-general","precepto":"art. 20.3","correcta":1,"justificaciones":["No. El Ministerio de Hacienda no es el órgano que la custodia (**art. 20.3**).","Es esta. La Intervención General de la Administración del Estado (**art. 20.3**).","No. Economía no la administra (**art. 20.3**).","No. La AIReF no la administra (**art. 20.3**)."]},{"id":"of-09-023","origen":"oficiales","test":"Tema 5 (2) - LGS (arts 8 a 21)","n":23,"enunciado":"De acuerdo con el artículo 10.3 de la Ley 38/2003, ¿qué facultades podrán ser objeto de desconcentración mediante real decreto acordado en Consejo de Ministros?","opciones":["Las facultades para conceder subvenciones.","La autorización del Consejo de Ministros para conceder subvenciones de cuantía superior a 12 millones de euros.","La aprobación del gasto correspondiente a la subvención.","La competencia para conceder subvenciones en las corporaciones locales."],"bloque":"subv-general","precepto":"art. 10.3","correcta":0,"justificaciones":["Es esta. Las facultades para conceder subvenciones pueden desconcentrarse por real decreto acordado en Consejo de Ministros (**art. 10.3**).","No. La ley no prevé desconcentrar la autorización del Consejo de Ministros (**art. 10.3**).","No. La aprobación del gasto no es una facultad que prevea el art. 10.3 (**art. 10.3**).","No. En las corporaciones locales rige su legislación de régimen local (**art. 10.4**)."]},{"id":"of-10-001","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":1,"enunciado":"Si las bases reguladoras permitieran la subcontratación de las actividades subvencionadas sin establecer límites cuantitativos, ¿qué porcentaje NO podrá superar?","opciones":["El 20 % del importe de la actividad subvencionada, sumando los precios de todos los subcontratos.","El 30 % del importe de la actividad subvencionada, sumando los precios de todos los subcontratos.","El 40 % del importe de la actividad subvencionada, sumando los precios de todos los subcontratos.","El 50 % del importe de la actividad subvencionada, sumando los precios de todos los subcontratos."],"bloque":"subv-concesion","precepto":"art. 29.2","correcta":3,"justificaciones":["No. El tope supletorio es del 50 %, no del 20 % (**art. 29.2**).","No. El tope supletorio es del 50 %, no del 30 % (**art. 29.2**).","No. El tope supletorio es del 50 %, no del 40 % (**art. 29.2**).","Es esta. Sin límite en las bases, no puede superar el 50 % del importe de la actividad subvencionada (**art. 29.2**)."]},{"id":"of-10-002","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":2,"enunciado":"Según el artículo 22 de la Ley 38/2003, el procedimiento ordinario de concesión de subvenciones se tramitará en régimen de:","opciones":["Concesión directa.","Concurrencia competitiva.","Concesión indirecta.","Concurrencia no competitiva."],"bloque":"subv-concesion","precepto":"art. 22.1","correcta":1,"justificaciones":["No. La concesión directa es excepcional (**art. 22.2**).","Es esta. El procedimiento ordinario es la concurrencia competitiva (**art. 22.1**).","No. La ley no regula una concesión indirecta (**art. 22**).","No. La concurrencia es competitiva por definición (**art. 22.1**)."]},{"id":"of-10-003","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":3,"enunciado":"Según el artículo 23 de la LGS, el procedimiento de concesión en régimen de concurrencia competitiva se inicia:","opciones":["Siempre de oficio.","Siempre a instancia de parte.","De oficio o a instancia de parte.","No existe este tipo de procedimiento de concesión."],"bloque":"subv-concesion","precepto":"art. 23.1","correcta":0,"justificaciones":["Es esta. El procedimiento de concesión se inicia siempre de oficio (**art. 23.1**).","No. No se inicia a instancia de parte (**art. 23.1**).","No. Solo de oficio (**art. 23.1**).","No. Es el procedimiento ordinario (**art. 22.1**)."]},{"id":"of-10-004","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":4,"enunciado":"El vencimiento del plazo máximo sin haberse notificado la resolución de concesión de la subvención legitima a los interesados:","opciones":["Para entender desestimada su pretensión por silencio administrativo.","Para entender estimada su pretensión por silencio administrativo.","Para considerar prescrito su derecho.","Para considerar caducado el procedimiento."],"bloque":"subv-concesion","precepto":"art. 25.5","correcta":0,"justificaciones":["Es esta. El vencimiento del plazo sin resolución legitima para entender desestimada la solicitud por silencio (**art. 25.5**).","No. El silencio es desestimatorio, no estimatorio (**art. 25.5**).","No. Lo que se prevé es el silencio desestimatorio, no la prescripción del derecho (**art. 25.5**).","No. No se prevé caducidad en la concesión (**art. 25.5**)."]},{"id":"of-10-005","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":5,"enunciado":"De acuerdo con la Ley 38/2003, ¿qué tipo de subvenciones podrán concederse de forma directa?","opciones":["Las de concurrencia competitiva.","Las previstas nominativamente en los Presupuestos Generales del Estado, Comunidades Autónomas o Entidades Locales.","Aquellas cuyo otorgamiento o cuantía venga impuesto a la Administración por una norma con rango inferior a la ley.","A propuesta del Ministro de Hacienda, aquellas en que se acrediten razones de interés presupuestario."],"bloque":"subv-concesion","precepto":"art. 22.2.a","correcta":1,"justificaciones":["No. La concurrencia competitiva es el procedimiento ordinario (**art. 22.1**).","Es esta. Las previstas nominativamente en los Presupuestos Generales del Estado, de las Comunidades Autónomas o de las Entidades Locales (**art. 22.2.a**).","No. Es cuando venga impuesto por una norma con rango de ley (**art. 22.2.b**).","No. Las excepcionales son por razones de interés público, social, económico o humanitario (**art. 22.2.c**)."]},{"id":"of-10-006","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":6,"enunciado":"Según la LGS, en una subvención quedarán exonerados de la constitución de garantía:","opciones":["Los beneficiarios de subvenciones concedidas por importe inferior a 3.000 €.","Las entidades obligadas por ley a la presentación de fianzas o depósitos ante las Administraciones Públicas.","Las entidades lucrativas que desarrollen proyectos o programas de acción social y cooperación internacional.","No existen supuestos que exoneren de la obligación de constituir garantía."],"bloque":"subv-concesion","precepto":"Reglamento art. 42","correcta":0,"justificaciones":["Es esta. Los beneficiarios de subvenciones de importe inferior a 3.000 euros están exonerados (**Reglamento art. 42**).","No. Lo que exonera es que la ley les exima de presentar cauciones, y no que estén obligadas a presentarlas.","No. Se exonera a las entidades sin ánimo de lucro de acción social y cooperación, no a las lucrativas.","No. Sí hay supuestos de exoneración (**art. 21**)."],"revisar":"El dato viene del Reglamento de la Ley 38/2003 (RD 887/2006), que no tengo en las fuentes. Conviene comprobarlo."},{"id":"of-10-007","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":7,"enunciado":"De conformidad con el artículo 30.2 de la LGS, el plazo de rendición de la cuenta justificativa será el que determinen las bases reguladoras y en su defecto se realizará, como máximo, en el plazo de:","opciones":["Un mes desde la finalización del plazo para la realización de la actividad.","Dos meses desde la finalización del plazo para la realización de la actividad.","Tres meses desde la finalización del plazo para la realización de la actividad.","Seis meses desde la finalización del plazo para la realización de la actividad."],"bloque":"subv-concesion","precepto":"art. 30.2","correcta":2,"justificaciones":["No. Un mes no es el plazo supletorio (**art. 30.2**).","No. Dos meses no es el plazo supletorio (**art. 30.2**).","Es esta. Como máximo, tres meses desde que finaliza el plazo de realización de la actividad (**art. 30.2**).","No. Seis meses no es el plazo supletorio (**art. 30.2**)."],"dup":"of-10-007"},{"id":"of-10-008","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":8,"enunciado":"De acuerdo con la LGS, ¿cómo se tramitará el procedimiento ordinario de concesión de subvenciones?","opciones":["Mediante la concesión directa a través de Real Decreto.","Mediante la concesión nominativa a través de Real Decreto.","En régimen de concurrencia competitiva.","Mediante la concesión nominativa en los Presupuestos Generales del Estado."],"bloque":"subv-concesion","precepto":"art. 22.1","correcta":2,"justificaciones":["No. La concesión directa es excepcional (**art. 22.2**).","No. La nominativa es una modalidad de concesión directa (**art. 22.2.a**).","Es esta. El procedimiento ordinario se tramita en concurrencia competitiva (**art. 22.1**).","No. La nominativa es una modalidad de concesión directa, no la ordinaria (**art. 22.2.a**)."]},{"id":"of-10-009","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":9,"enunciado":"¿A través de qué instrumento debe canalizarse una subvención nominativa?","opciones":["Un convenio.","Un contrato privado.","Un contrato de servicios.","Una encomienda de gestión."],"bloque":"subv-concesion","precepto":"art. 28.1","correcta":0,"justificaciones":["Es esta. Los convenios son el instrumento habitual para canalizar las subvenciones nominativas (**art. 28.1**).","No. Un contrato privado no canaliza una subvención (**art. 28.1**).","No. Un contrato de servicios tiene contraprestación y la subvención no (**art. 2.1.a**).","No. La encomienda de gestión es otra figura (**art. 28.1**)."]},{"id":"of-10-010","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":10,"enunciado":"De acuerdo con el artículo 23 de la LGS, señale cuál de los siguientes aspectos NO es un contenido necesario de la convocatoria de subvenciones:","opciones":["Objeto, condiciones y finalidad de la concesión de la subvención.","Plazo de resolución y notificación.","Identificación de los empleados públicos responsables de la tramitación de las solicitudes.","Criterios de valoración de las solicitudes."],"bloque":"subv-concesion","precepto":"art. 23.2","correcta":2,"justificaciones":["Sí es contenido necesario. Objeto, condiciones y finalidad (**art. 23.2.c**).","Sí es contenido necesario. Plazo de resolución y notificación (**art. 23.2.h**).","Es esta. La convocatoria no tiene que identificar a los empleados públicos que tramitan las solicitudes (**art. 23.2**). Sí los órganos de instrucción y resolución.","Sí es contenido necesario. Criterios de valoración (**art. 23.2.l**)."]},{"id":"of-10-011","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":11,"enunciado":"De acuerdo con la Ley 38/2003, de 17 de noviembre, General de Subvenciones, se considera gasto subvencionable:","opciones":["Los gastos financieros, de asesoría jurídica o financiera, los notariales, registrales y periciales, en todo caso.","Los impuestos indirectos aun cuando sean susceptibles de recuperación o compensación.","Los impuestos personales sobre la renta.","Con carácter excepcional, los gastos de garantía bancaria cuando así lo prevea la normativa reguladora de la subvención."],"bloque":"subv-concesion","precepto":"art. 31.7","correcta":3,"justificaciones":["No. Solo si las bases lo prevén, no en todo caso (**art. 31.7**).","No. Los impuestos indirectos recuperables nunca lo son (**art. 31.8**).","No. Los impuestos personales sobre la renta nunca lo son (**art. 31.8**).","Es esta. Excepcionalmente, los gastos de garantía bancaria, si lo prevé la normativa reguladora (**art. 31.7**)."]},{"id":"of-10-012","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":12,"enunciado":"De acuerdo con la Ley 38/2003, de 17 de noviembre, General de Subvenciones las subvenciones reguladas por esta ley:","opciones":["Podrán adjudicarse directamente cuando se acrediten razones excepcionales de interés público que dificulten su convocatoria.","Solo pueden adjudicarse directamente si existe causa excepcional de utilidad pública o interés social debidamente justificada.","Solo pueden adjudicarse directamente las previstas en los presupuestos de la Administración correspondiente.","Solo pueden adjudicarse directamente las sometidas al régimen especial para subvenciones de cooperación internacional."],"bloque":"subv-concesion","precepto":"art. 22.2.c","correcta":0,"justificaciones":["Es esta. Se pueden conceder directamente, con carácter excepcional, cuando se acrediten razones de interés público, social, económico o humanitario que dificulten la convocatoria (**art. 22.2.c**).","No. Hay más supuestos que la utilidad pública o el interés social (**art. 22.2**).","No. Hay otros supuestos además de los presupuestos (**art. 22.2**).","No. La cooperación internacional no es el único régimen especial (**art. 22.2**)."]},{"id":"of-10-013","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":13,"enunciado":"Según la Ley 38/2003, el plazo máximo para resolver y notificar la resolución del procedimiento de concesión en régimen de concurrencia competitiva será de:","opciones":["3 meses.","6 meses.","1 mes.","15 días."],"bloque":"subv-concesion","precepto":"art. 25.4","correcta":1,"justificaciones":["No. Tres meses no es el plazo (**art. 25.4**).","Es esta. Seis meses (**art. 25.4**).","No. Un mes no es el plazo (**art. 25.4**).","No. Quince días no es el plazo (**art. 25.4**)."]},{"id":"of-10-014","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":14,"enunciado":"Según la Ley 38/2003, de 17 de noviembre, General de Subvenciones, en ningún caso serán gastos subvencionables:","opciones":["Los gastos financieros.","Los gastos de asesoría jurídica o financiera.","Los gastos notariales y registrales.","Los gastos de procedimientos judiciales."],"bloque":"subv-concesion","precepto":"art. 31.7","correcta":3,"justificaciones":["No. Son subvencionables si las bases lo prevén (**art. 31.7**).","No. Son subvencionables si las bases lo prevén (**art. 31.7**).","No. Son subvencionables si las bases lo prevén (**art. 31.7**).","Es esta. Los gastos de procedimientos judiciales no son subvencionables en ningún caso (**art. 31.7.c**)."]},{"id":"of-10-015","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":15,"enunciado":"Según la Ley General de Subvenciones, deben concederse por concurrencia competitiva:","opciones":["Las subvenciones con asignación nominal en los Presupuestos Generales del Estado.","Las subvenciones de cuantía impuesta por una norma de rango legal.","Las subvenciones que se concedan con criterios de valoración previamente fijados.","Las subvenciones que se justifiquen por razones de interés social."],"bloque":"subv-concesion","precepto":"art. 22.1","correcta":2,"justificaciones":["No. Las nominativas se conceden de forma directa (**art. 22.2.a**).","No. Las impuestas por una norma legal se conceden de forma directa (**art. 22.2.b**).","Es esta. La concurrencia competitiva compara las solicitudes según criterios de valoración fijados previamente (**art. 22.1**).","No. Las razones de interés social justifican la concesión directa excepcional (**art. 22.2.c**)."]},{"id":"of-10-016","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":16,"enunciado":"Según la LGS, con carácter previo a la convocatoria de la subvención o a la concesión directa de la misma, deberá realizarse:","opciones":["El compromiso del gasto.","La autorización del gasto.","La aprobación del gasto.","La aprobación y el compromiso del gasto."],"bloque":"subv-concesion","precepto":"art. 34.1","correcta":2,"justificaciones":["No. El compromiso lo conlleva la resolución de concesión, que es posterior (**art. 34.2**).","No. La ley habla de aprobación del gasto, no de autorización (**art. 34.1**).","Es esta. Antes de la convocatoria o de la concesión directa debe efectuarse la aprobación del gasto (**art. 34.1**).","No. El compromiso llega con la concesión (**art. 34.2**)."]},{"id":"of-10-017","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":17,"enunciado":"Dentro del proceso de concesión de una subvención, quedan exonerados de constituir garantía, salvo previsión en contrario:","opciones":["Las personas o entidades cuyo domicilio se encuentre radicado fuera del territorio nacional.","Las entidades que por ley estén exentos de la presentación de cauciones o depósitos ante las Administraciones Públicas.","Los beneficiarios de subvenciones concedidas por importe inferior a 5.000 euros.","Las sociedades mercantiles y las fundaciones del sector privado."],"bloque":"subv-concesion","precepto":"Reglamento art. 42","correcta":1,"justificaciones":["No. El domicilio fuera de España no exonera por sí solo.","Es esta. Quedan exoneradas las entidades que por ley estén exentas de presentar cauciones o depósitos ante las Administraciones (**Reglamento art. 42**).","No. El umbral de exoneración es de 3.000 euros, no de 5.000.","No. Ser sociedad mercantil o fundación privada no exonera."],"revisar":"El dato viene del Reglamento de la Ley 38/2003 (RD 887/2006), que no tengo en las fuentes. Conviene comprobarlo."},{"id":"of-10-018","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":18,"enunciado":"Indique cuál de las siguientes afirmaciones es correcta en relación con la concesión de subvenciones, a los efectos de la LGS:","opciones":["Se prohíbe expresamente la concesión de subvenciones de forma nominativa en los Presupuestos Generales del Estado.","El procedimiento ordinario de concesión de subvenciones se tramitará en régimen de concesión directa.","Con carácter excepcional, se podrán conceder directamente aquellas subvenciones en las que se acrediten razones justificadas que dificulten su convocatoria pública.","Las bases reguladoras no podrán prever que el órgano competente proceda al prorrateo del importe global máximo."],"bloque":"subv-concesion","precepto":"art. 22.2.c","correcta":2,"justificaciones":["No. La nominativa está permitida (**art. 22.2.a**).","No. El ordinario es la concurrencia competitiva (**art. 22.1**).","Es esta. Con carácter excepcional pueden concederse directamente cuando haya razones justificadas que dificulten la convocatoria (**art. 22.2.c**).","No. Las bases pueden prever el prorrateo, excepcionalmente (**art. 22.1**)."]},{"id":"of-10-019","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":19,"enunciado":"De acuerdo con la LGS, en ningún caso serán gastos subvencionables:","opciones":["Los gastos notariales y registrales.","Los gastos de procedimientos judiciales.","Los gastos de asesoría jurídica o financiera.","Los gastos periciales para la realización del proyecto subvencionado."],"bloque":"subv-concesion","precepto":"art. 31.7.c","correcta":1,"justificaciones":["No. Son subvencionables si las bases lo prevén y son indispensables (**art. 31.7**).","Es esta. Los gastos de procedimientos judiciales no son subvencionables en ningún caso (**art. 31.7.c**).","No. Son subvencionables si las bases lo prevén (**art. 31.7**).","No. Son subvencionables si las bases lo prevén (**art. 31.7**)."]},{"id":"of-10-020","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":20,"enunciado":"En la gestión de subvenciones, la fase de compromiso del gasto tiene lugar con:","opciones":["La publicación de la convocatoria de la subvención.","La resolución de concesión de la subvención.","La justificación por el beneficiario de la subvención.","El pago de la subvención."],"bloque":"subv-concesion","precepto":"art. 34.2","correcta":1,"justificaciones":["No. La convocatoria exige antes la aprobación del gasto, no el compromiso (**art. 34.1**).","Es esta. La resolución de concesión conlleva el compromiso del gasto (**art. 34.2**).","No. La justificación es posterior y condiciona el pago (**art. 34.3**).","No. El pago es posterior al compromiso (**art. 34.3**)."]},{"id":"of-10-021","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":21,"enunciado":"Señale cuál de los siguientes NO es un requisito en el procedimiento de concesión de una subvención en concurrencia competitiva:","opciones":["La publicación en el Boletín Oficial del Estado de las bases reguladoras.","La previa existencia de un plan estratégico de subvenciones.","La notificación de la resolución de concesión.","La previa realización de la actividad o el cumplimiento de la finalidad que determine su concesión."],"bloque":"subv-concesion","precepto":"art. 22","correcta":3,"justificaciones":["Sí es requisito. Las bases se publican en el BOE o el diario oficial correspondiente (**art. 9.3**).","Sí es requisito. Debe haber un plan estratégico previo (**art. 8.1**).","Sí es requisito. La resolución de concesión se notifica (**art. 25**).","Es esta. Lo que se subvenciona puede estar ya realizado o por desarrollar, así que no se exige la realización previa (**art. 2.1.b**)."]},{"id":"of-10-022","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":22,"enunciado":"La resolución de concesión de una subvención conllevará:","opciones":["El compromiso del gasto.","El reconocimiento de la obligación.","La propuesta de pago.","La aprobación del gasto."],"bloque":"subv-concesion","precepto":"art. 34.2","correcta":0,"justificaciones":["Es esta. La resolución de concesión conlleva el compromiso del gasto (**art. 34.2**).","No. El reconocimiento de la obligación llega al justificar y pagar (**art. 34.3**).","No. La propuesta de pago es posterior (**art. 34.3**).","No. La aprobación del gasto es previa, antes de la convocatoria (**art. 34.1**)."]},{"id":"of-10-023","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":23,"enunciado":"De conformidad con lo dispuesto en la Ley 38/2003, podrán ser subvencionados con carácter excepcional:","opciones":["Los intereses deudores de las cuentas bancarias, cuando así lo prevea la normativa reguladora de la subvención.","Los intereses, recargos y sanciones administrativas y penales, cuando así lo prevea la normativa reguladora de la subvención.","Los gastos de procedimientos judiciales, cuando así lo prevea la normativa reguladora de la subvención.","Los gastos de garantía bancaria, cuando así lo prevea la normativa reguladora de la subvención."],"bloque":"subv-concesion","precepto":"art. 31.7","correcta":3,"justificaciones":["No. Los intereses deudores de las cuentas bancarias nunca son subvencionables (**art. 31.7.a**).","No. Los intereses, recargos y sanciones nunca son subvencionables (**art. 31.7.b**).","No. Los gastos de procedimientos judiciales nunca son subvencionables (**art. 31.7.c**).","Es esta. Los gastos de garantía bancaria pueden subvencionarse excepcionalmente, si lo prevé la normativa reguladora (**art. 31.7**)."]},{"id":"of-10-024","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":24,"enunciado":"Según la LGS, ¿cuál es el instrumento habitual para canalizar las subvenciones previstas en los Presupuestos Generales del Estado?","opciones":["La encomienda de gestión.","El encargo a un medio propio.","El convenio.","El contrato."],"bloque":"subv-concesion","precepto":"art. 28.1","correcta":2,"justificaciones":["No. La encomienda de gestión es otra figura (**art. 28.1**).","No. El encargo a un medio propio es otra figura (**art. 28.1**).","Es esta. Los convenios son el instrumento habitual para las subvenciones nominativas (**art. 28.1**).","No. El contrato supone contraprestación, y la subvención no la tiene (**art. 2.1.a**)."]},{"id":"of-10-025","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":25,"enunciado":"Según la Ley 38/2003, ¿cuándo requiere autorización la subcontratación con terceros de una actividad subvencionada?","opciones":["Cuando la actividad concertada exceda del 25% del importe de la subvención y sea superior a 100.000 euros.","Cuando la actividad concertada exceda del 20% del importe de la subvención y dicho importe sea superior a 60.000 euros.","Cuando la actividad concertada exceda del 20% del importe de la subvención y supere los 18.000 euros.","En cualquier supuesto en que la actividad concertada supere las cuantías establecidas en la Ley 9/2017 para el contrato menor."],"bloque":"subv-concesion","precepto":"art. 29.3","correcta":1,"justificaciones":["No. Ni el 25 % ni los 100.000 euros son los umbrales (**art. 29.3**).","Es esta. Cuando lo concertado exceda del 20 % del importe de la subvención y ese importe sea superior a 60.000 euros (**art. 29.3**).","No. El importe de la subvención debe superar 60.000 euros, no 18.000 (**art. 29.3**).","No. La ley fija sus propios umbrales y no remite al contrato menor (**art. 29.3**)."]},{"id":"of-10-026","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":26,"enunciado":"¿En qué caso, según lo dispuesto en la Ley 38/2003, serán subvencionables los intereses deudores de una cuenta bancaria?","opciones":["Siempre, salvo disposición expresa en contrario en las bases reguladoras.","Cuando resulten estrictamente necesarios y se realicen en el plazo establecido por las bases reguladoras.","Cuando el beneficiario de la subvención los abona efectivamente o cuando sean susceptibles de recuperación o compensación.","En ningún caso."],"bloque":"subv-concesion","precepto":"art. 31.7.a","correcta":3,"justificaciones":["No. Nunca son subvencionables (**art. 31.7.a**).","No. Esa es la regla general de gasto subvencionable, pero los intereses deudores quedan excluidos (**art. 31.1 y 7**).","No. Eso se refiere a los tributos y a los impuestos (**art. 31.8**).","Es esta. Los intereses deudores de las cuentas bancarias no son subvencionables en ningún caso (**art. 31.7.a**)."]},{"id":"of-10-027","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":27,"enunciado":"En un procedimiento de concesión de subvenciones en régimen de concurrencia competitiva, debe tramitarse el oportuno expediente de gasto:","opciones":["Cuando se haya previsto expresamente en la normativa reguladora.","Solo antes de la resolución de concesión de las subvenciones.","Única y excepcionalmente si se contempla una cuantía adicional a la cuantía total máxima establecida en la convocatoria de subvenciones.","Con carácter previo a la convocatoria de las subvenciones."],"bloque":"subv-concesion","precepto":"art. 34.1","correcta":3,"justificaciones":["No. El gasto se aprueba siempre, no solo si lo prevé la normativa (**art. 34.1**).","No. Se aprueba antes de la convocatoria, no solo antes de resolver (**art. 34.1**).","No. No es solo excepcional. Siempre hay que aprobar el gasto (**art. 34.1**).","Es esta. La aprobación del gasto es previa a la convocatoria (**art. 34.1**)."]},{"id":"of-10-028","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":28,"enunciado":"Señale la respuesta correcta según el artículo 31 de la Ley General de Subvenciones, en relación con los gastos subvencionables:","opciones":["El carácter subvencionable del gasto de amortización está sujeto a que la subvención haya contribuido a la compra de los bienes.","Cuando en las bases no se haya determinado el plazo en el que deba realizarse la actividad, los gastos deberán realizarse antes de que finalice el año natural en que se haya concedido la subvención.","Si en la normativa reguladora no se prevé, los gastos de garantía bancaria serán subvencionados con carácter general.","Los tributos no serán, en ningún caso, gastos subvencionables."],"bloque":"subv-concesion","precepto":"art. 31.1","correcta":1,"justificaciones":["No. Es al revés: la amortización solo es subvencionable si la subvención no ha contribuido a la compra de los bienes (**art. 31.6.a**).","Es esta. Sin plazo en las bases, los gastos deben realizarse antes de que acabe el año natural de la concesión (**art. 31.1**).","No. La garantía bancaria solo se subvenciona excepcionalmente, si lo prevé la normativa (**art. 31.7**).","No. Los tributos son subvencionables cuando el beneficiario los abona efectivamente (**art. 31.8**)."]},{"id":"of-10-029","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":29,"enunciado":"Desde el punto de vista del procedimiento de gasto, en la gestión de subvenciones la fase del compromiso de gasto tiene lugar:","opciones":["Con la comprobación de la justificación de la subvención por el órgano concedente.","Con la resolución de la concesión de la subvención.","Con la convocatoria de la subvención.","Con la justificación del beneficiario de la actividad para la que se concedió."],"bloque":"subv-concesion","precepto":"art. 34.2","correcta":1,"justificaciones":["No. La comprobación de la justificación es posterior (**art. 34.3**).","Es esta. El compromiso del gasto se produce con la resolución de concesión (**art. 34.2**).","No. La convocatoria exige antes la aprobación del gasto (**art. 34.1**).","No. La justificación del beneficiario es posterior (**art. 34.3**)."]},{"id":"of-10-030","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":30,"enunciado":"Con carácter previo a la convocatoria de subvenciones, la funcionaria que gestiona la subvención sabe que debe efectuar:","opciones":["El reconocimiento de la obligación.","La aprobación del gasto.","El reconocimiento de la obligación y la propuesta de gasto.","El compromiso del gasto."],"bloque":"subv-concesion","precepto":"art. 34.1","correcta":1,"justificaciones":["No. El reconocimiento de la obligación llega al final (**art. 34.3**).","Es esta. Antes de la convocatoria debe aprobarse el gasto (**art. 34.1**).","No. El reconocimiento de la obligación es posterior (**art. 34.3**).","No. El compromiso lo conlleva la resolución de concesión (**art. 34.2**)."]},{"id":"of-10-031","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":31,"enunciado":"Conforme al Real Decreto 887/2006, la justificación por el beneficiario del cumplimiento de las condiciones impuestas y de la consecución de los objetivos previstos en el acto de concesión de una subvención, podrá revestir las siguientes modalidades:","opciones":["Cuenta justificativa simplificada o informe de auditor o memoria económica.","Cuentas anuales auditadas o memoria económica abreviada o auditoría de estados contables.","Memoria de actuación justificativa o detalle de ingresos y otras subvenciones o una muestra de las cuentas justificativas presentadas.","Cuenta justificativa o acreditación por módulos o presentación de estados contables."],"bloque":"subv-concesion","precepto":"art. 30.1","correcta":3,"justificaciones":["No. Esa lista no coincide con las modalidades que recoge la ley (**art. 30.1**).","No. Esa lista no coincide con las modalidades que recoge la ley (**art. 30.1**).","No. Esa lista no coincide con las modalidades que recoge la ley (**art. 30.1**).","Es esta. La justificación puede revestir la forma de cuenta justificativa, acreditación por módulos o estados contables (**art. 30.1**)."],"ojo":"La pregunta cita el Reglamento, pero las tres modalidades de la ley son suficientes para resolverla. El Reglamento desarrolla la cuenta justificativa en varias formas."},{"id":"of-10-032","origen":"oficiales","test":"Tema 5 (3) - LGS (arts 22 a 34)","n":32,"enunciado":"El artículo 22.2 de la Ley 38/2003, habla de la concesión de las subvenciones nominativas previstas en los Presupuestos Generales del Estado, ¿cuál es el procedimiento para dicha concesión?","opciones":["La concurrencia competitiva.","La evaluación individualizada.","La subasta pública.","La concesión directa."],"bloque":"subv-concesion","precepto":"art. 22.2.a","correcta":3,"justificaciones":["No. La concurrencia competitiva es el procedimiento ordinario (**art. 22.1**).","No. La ley no habla de evaluación individualizada para las nominativas (**art. 22.2.a**).","No. La subasta pública no es un procedimiento de concesión de subvenciones (**art. 22**).","Es esta. Las nominativas se conceden de forma directa (**art. 22.2.a**)."],"dup":"of-10-032"},{"id":"of-11-001","origen":"oficiales","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":1,"enunciado":"Conforme a la LGS, el plazo máximo para resolver y notificar la resolución del procedimiento de reintegro de una subvención será, desde la fecha del acuerdo de iniciación, de:","opciones":["12 meses.","9 meses.","6 meses.","3 meses."],"bloque":"subv-reintegro","precepto":"art. 42.4","correcta":0,"justificaciones":["Es esta. Doce meses desde la fecha del acuerdo de iniciación (**art. 42.4**).","No. Nueve meses no es el plazo (**art. 42.4**).","No. Seis meses no es el plazo (**art. 42.4**).","No. Tres meses no es el plazo (**art. 42.4**)."]},{"id":"of-11-002","origen":"oficiales","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":2,"enunciado":"Conforme a la LGS, en el supuesto en el que alguno de los beneficiarios tuviera que reintegrar las cantidades percibidas, dichas cantidades tendrán la consideración de:","opciones":["Pagos en formalización.","Ingresos del Tesoro Público.","Ingresos de derecho público.","Pagos indebidos."],"bloque":"subv-reintegro","precepto":"art. 38.1","correcta":2,"justificaciones":["No. Los pagos en formalización no son una categoría de la ley (**art. 38.1**).","No. La ley no dice 'ingresos del Tesoro Público' sino 'ingresos de derecho público' (**art. 38.1**).","Es esta. Las cantidades a reintegrar tienen la consideración de ingresos de derecho público (**art. 38.1**).","No. Los pagos indebidos son otra categoría, no la que fija la ley (**art. 38.1**)."]},{"id":"of-11-003","origen":"oficiales","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":3,"enunciado":"Conforme a la Ley General de Subvenciones el derecho de la Administración a liquidar el reintegro de una subvención:","opciones":["Prescribe a los 4 años desde el momento en que vence el plazo para presentar la justificación por parte del beneficiado.","Prescribe a los 4 años desde la fecha de la convocatoria.","Es imprescriptible.","Prescribe a los 4 años desde el inicio del procedimiento de reintegro."],"bloque":"subv-reintegro","precepto":"art. 39","correcta":0,"justificaciones":["Es esta. Prescribe a los cuatro años desde que vence el plazo de justificación del beneficiario (**art. 39.1 y 2.a**).","No. No se cuenta desde la fecha de la convocatoria (**art. 39.2**).","No. Sí prescribe (**art. 39.1**).","No. No se cuenta desde el inicio del procedimiento (**art. 39.2**)."]},{"id":"of-11-004","origen":"oficiales","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":4,"enunciado":"De conformidad con la Ley 38/2003, el derecho de la Administración a reconocer o liquidar el reintegro de una subvención prescribirá a los:","opciones":["Dos años.","Tres años.","Cuatro años.","No prescribe."],"bloque":"subv-reintegro","precepto":"art. 39.1","correcta":2,"justificaciones":["No. Dos años no es el plazo (**art. 39.1**).","No. Tres años no es el plazo (**art. 39.1**).","Es esta. Cuatro años (**art. 39.1**).","No. Sí prescribe (**art. 39.1**)."],"dup":"of-11-004"},{"id":"of-11-005","origen":"oficiales","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":5,"enunciado":"¿A quién corresponderá el control financiero de las subvenciones?","opciones":["A la Subsecretaría del Ministerio de Hacienda, sin perjuicio de la competencia atribuida a la Junta Consultiva.","A la Intervención General de la Administración del Estado, sin perjuicio de la competencia atribuida al Tribunal de Cuentas.","A la Intervención General de la Administración del Estado, sin perjuicio de las competencias atribuidas al Consejo de Estado.","A la Abogacía del Estado, sin perjuicio de la competencia atribuida a la Intervención General de la Administración del Estado."],"bloque":"subv-reintegro","precepto":"art. 44.3","correcta":1,"justificaciones":["No. La Subsecretaría no ejerce el control financiero (**art. 44.3**).","Es esta. Corresponde a la Intervención General de la Administración del Estado, sin perjuicio del Tribunal de Cuentas (**art. 44.3**).","No. El Consejo de Estado no figura en la ley (**art. 44.3**).","No. La Abogacía del Estado no ejerce el control financiero (**art. 44.3**)."]},{"id":"of-11-006","origen":"oficiales","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":6,"enunciado":"Según establece el artículo 38 de la Ley 38/2003, los procedimientos para la exigencia del reintegro de las subvenciones, tendrán siempre carácter:","opciones":["Presupuestario.","Patrimonial.","Administrativo.","Sancionador."],"bloque":"subv-reintegro","precepto":"art. 38.4","correcta":2,"justificaciones":["No. No tienen carácter presupuestario (**art. 38.4**).","No. No tienen carácter patrimonial (**art. 38.4**).","Es esta. Tienen siempre carácter administrativo (**art. 38.4**).","No. El reintegro no es un procedimiento sancionador (**art. 40.1**)."]},{"id":"of-11-007","origen":"oficiales","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":7,"enunciado":"¿Cuál de las siguientes es una infracción grave conforme a la Ley General de Subvenciones?","opciones":["La incomparecencia en el lugar y tiempo señalados para rendir cuentas.","Impedir la entrada al local en que existan indicios probatorios de la correcta justificación de los fondos recibidos.","La falta de justificación del empleo dado a los fondos recibidos una vez transcurrido el plazo establecido para su presentación.","Las coacciones al personal controlador que realice el control financiero."],"bloque":"subv-sanciones","precepto":"art. 57.c","correcta":2,"justificaciones":["No. Incomparecer ante el control financiero es parte de la resistencia u obstrucción, infracción leve (**art. 56.g**).","No. Impedir la entrada a los locales es resistencia u obstrucción, infracción leve (**art. 56.g**).","Es esta. La falta de justificación una vez vencido el plazo es infracción grave (**art. 57.c**).","No. Las coacciones al personal controlador son resistencia, infracción leve (**art. 56.g**)."]},{"id":"of-11-008","origen":"oficiales","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":8,"enunciado":"El plazo de prescripción de las infracciones y sanciones en el ámbito de la Ley General de Subvenciones es de:","opciones":["3 años para las infracciones y 5 años para las sanciones.","4 años tanto para las infracciones como para las sanciones.","3 años tanto para las infracciones como para las sanciones.","5 años para las infracciones y 3 años para las sanciones."],"bloque":"subv-sanciones","precepto":"art. 65","correcta":1,"justificaciones":["No. Son cuatro años para ambas (**art. 65**).","Es esta. Cuatro años tanto para infracciones como para sanciones (**art. 65.1 y 2**).","No. Son cuatro, no tres (**art. 65**).","No. Son cuatro para ambas (**art. 65**)."]},{"id":"of-11-009","origen":"oficiales","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":9,"enunciado":"El plazo máximo para resolver y notificar la resolución del procedimiento de reintegro de subvenciones será:","opciones":["12 meses desde la fecha del acuerdo de iniciación.","6 meses desde la fecha del acuerdo de iniciación.","9 meses desde la fecha del acuerdo de iniciación.","3 meses desde la fecha del acuerdo de iniciación."],"bloque":"subv-reintegro","precepto":"art. 42.4","correcta":0,"justificaciones":["Es esta. Doce meses desde la fecha del acuerdo de iniciación (**art. 42.4**).","No. Seis meses no es el plazo (**art. 42.4**).","No. Nueve meses no es el plazo (**art. 42.4**).","No. Tres meses no es el plazo (**art. 42.4**)."]},{"id":"of-11-010","origen":"oficiales","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":10,"enunciado":"De acuerdo con el artículo 42 de la Ley 38/2003, en la tramitación del procedimiento de reintegro de subvenciones se garantizará, en todo caso, el derecho del interesado a:","opciones":["La revisión del expediente administrativo.","La presentación de alegaciones.","La presentación de medios de prueba.","La audiencia."],"bloque":"subv-reintegro","precepto":"art. 42.3","correcta":3,"justificaciones":["No. La ley garantiza el trámite de audiencia (**art. 42.3**).","No. Las alegaciones se hacen en la audiencia, pero la garantía que dice la ley es la audiencia (**art. 42.3**).","No. La prueba no es la garantía que cita el artículo (**art. 42.3**).","Es esta. Se garantiza en todo caso el derecho del interesado a la audiencia (**art. 42.3**)."]},{"id":"of-11-011","origen":"oficiales","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":11,"enunciado":"Según la Ley 38/2003, de 17 de noviembre, General de Subvenciones, será causa de nulidad de la resolución de concesión:","opciones":["El incumplimiento de la obligación de justificación.","La carencia o insuficiencia de crédito.","La no adopción del comportamiento que fundamenta la concesión de la subvención.","La obtención de la subvención falseando las condiciones requeridas para ello."],"bloque":"subv-reintegro","precepto":"art. 36.1.b","correcta":1,"justificaciones":["No. No justificar es causa de reintegro (**art. 37.1.c**), no de nulidad.","Es esta. La carencia o insuficiencia de crédito es causa de nulidad de la concesión (**art. 36.1.b**).","No. Es causa de reintegro (**art. 37.1.b**), no de nulidad.","No. Es causa de reintegro (**art. 37.1.a**), no de nulidad."]},{"id":"of-11-012","origen":"oficiales","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":12,"enunciado":"En relación con las subvenciones públicas, señale la afirmación correcta de conformidad con la Ley General de Subvenciones:","opciones":["El plazo máximo para resolver y notificar la resolución del procedimiento de reintegro de una subvención será de 6 meses.","Los Secretarios de Estado, en el ámbito de la AGE, son competentes para su concesión.","El Tribunal de Cuentas es el responsable de la administración y custodia de la Base de Datos Nacional de Subvenciones.","La obtención de una subvención falseando las condiciones requeridas para su concesión está tipificado como infracción grave."],"bloque":"subv-general","precepto":"art. 10.1","correcta":1,"justificaciones":["No. El plazo es de 12 meses, no de 6 (**art. 42.4**).","Es esta. Los Secretarios de Estado son competentes para conceder subvenciones (**art. 10.1**).","No. La administra la Intervención General, no el Tribunal de Cuentas (**art. 20.3**).","No. Obtener la subvención falseando las condiciones es infracción muy grave (**art. 58.a**)."]},{"id":"of-11-013","origen":"oficiales","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":13,"enunciado":"Siguiendo lo dispuesto en la Ley 38/2003, de 17 de noviembre, General de Subvenciones, ¿cuál de las siguientes infracciones se tipificaría como grave?","opciones":["La resistencia, obstrucción, excusa o negativa a las actuaciones de control financiero.","La presentación de cuentas justificativas inexactas o incompletas.","La falta de justificación del empleo dado a los fondos recibidos una vez transcurrido el plazo establecido para su presentación.","El incumplimiento de la obligación de llevar o conservar la contabilidad, los registros legalmente establecidos, los programas y archivos informáticos que les sirvan de soporte y los sistemas de codificación utilizados."],"bloque":"subv-sanciones","precepto":"art. 57.c","correcta":2,"justificaciones":["No. La resistencia u obstrucción es, con carácter general, infracción leve (**art. 56.g**).","No. Las cuentas inexactas o incompletas son infracción leve (**art. 56.b**).","Es esta. La falta de justificación pasado el plazo es infracción grave (**art. 57.c**).","No. Incumplir la llevanza de la contabilidad es infracción leve (**art. 56.d**)."]},{"id":"of-11-014","origen":"oficiales","test":"Tema 5 (4) - LGS (arts 36 a Disposición adicional quinta)","n":14,"enunciado":"Según el artículo 54 de la Ley 38/2003, ¿en cuál de los siguientes supuestos se exime de responsabilidad por infracción administrativa en materia de subvenciones?","opciones":["Cuando la infracción derive de un error de derecho excusable apreciado por el órgano competente.","Cuando concurra fuerza mayor.","Cuando la infracción sea leve y se reintegre voluntariamente la subvención antes de la incoación del procedimiento.","Cuando la decisión sea colectiva, aunque el interesado hubiera votado a favor en la toma de decisiones."],"bloque":"subv-sanciones","precepto":"art. 54.b","correcta":1,"justificaciones":["No. El error de derecho excusable no figura en el art. 54.","Es esta. No hay responsabilidad cuando concurre fuerza mayor (**art. 54.b**).","No. El reintegro voluntario no exime en el art. 54 (salvo en los casos del art. 63.1).","No. En la decisión colectiva solo se exime a quien salvó su voto o no asistió (**art. 54.c**)."]},{"id":"vo-07-001","origen":"votaciones","test":"Clase 20 - Bloque III","n":1,"enunciado":"Desde la perspectiva administrativa, las subvenciones son una técnica de:","opciones":["Limitación.","Arbitral.","De servicio público.","Fomento."],"bloque":"subv-general","precepto":"concepto de subvención","correcta":3,"justificaciones":["No. La limitación restringe derechos, y la subvención los favorece.","No. La actividad arbitral es de resolución de conflictos.","No. El servicio público es la prestación directa de servicios, y la subvención no lo es.","Es esta. La subvención es una técnica de fomento: estimula actividades de interés general mediante una ayuda."],"revisar":"Pregunta de doctrina. No consta en la Ley 38/2003 con esas palabras. Razonada con doctrina general.","dup":"of-08-001"},{"id":"vo-07-002","origen":"votaciones","test":"Clase 20 - Bloque III","n":2,"enunciado":"Indique cuál de las siguientes respuestas se refiere a una actividad administrativa de fomento:","opciones":["La ejecución de las obras de construcción de una carretera nacional por parte del Ministerio de Fomento.","La concesión del Premio Nacional de Literatura por parte del Ministerio de Educación, Cultura y Deporte.","La vacunación a viajeros en un Centro de Vacunación Internacional de una Subdelegación del Gobierno.","La concesión de una licencia para la ocupación del dominio público por parte de un Ayuntamiento."],"bloque":"subv-general","precepto":"concepto de fomento","correcta":1,"justificaciones":["No. Construir una carretera es prestar un servicio público.","Es esta. Un premio es un incentivo honorífico, una modalidad de fomento.","No. Vacunar es prestación de un servicio público.","No. La licencia sobre el dominio público es una actividad de limitación o intervención."],"revisar":"Pregunta de doctrina. No consta en la Ley 38/2003 con esas palabras. Razonada con doctrina general.","dup":"of-08-002"},{"id":"vo-07-003","origen":"votaciones","test":"Clase 20 - Bloque III","n":3,"enunciado":"Según la Ley General de Subvenciones, una subvención que no van a ser financiada con cargo a fondos de la Unión Europea, ¿que régimen jurídico le será de aplicación?","opciones":["Las normas de derecho privado en todo caso.","El derecho comunitario, dado que las subvenciones van dirigidas a varias Comunidades Autónomas.","El derecho privado y las restantes normas de desarrollo y, en su defecto, el derecho administrativo.","La Ley General de Subvenciones y sus disposiciones de desarrollo, las restantes normas de derecho administrativo y, en su defecto, las normas de derecho privado."],"bloque":"subv-general","precepto":"art. 3","correcta":3,"justificaciones":["No. Se aplican la ley y su desarrollo primero, y el derecho privado solo en defecto (**art. 3**).","No. Si no hay fondos de la Unión Europea, no manda el derecho comunitario (**art. 3**).","No. El orden es otro: primero la ley, luego el derecho administrativo y por último el privado (**art. 3**).","Es esta. La LGS y sus normas de desarrollo, luego el derecho administrativo y por último el privado (**art. 3**)."]},{"id":"vo-07-004","origen":"votaciones","test":"Clase 20 - Bloque III","n":4,"enunciado":"Indique la afirmación correcta en relación con el concepto de subvención y el ámbito de aplicación de la LGS:","opciones":["La entrega ha de estar sujeta al cumplimiento de un determinado objetivo, siempre que estos hayan sido ya realizados.","Tienen carácter de subvención las prestaciones no contributivas del Sistema de la Seguridad Social.","Están excluidas del ámbito de aplicación de la Ley los premios que se otorguen a solicitud del beneficiario.","No tienen carácter de subvención las prestaciones reconocidas por el Fondo de Garantía Salarial."],"bloque":"subv-general","precepto":"art. 2","correcta":3,"justificaciones":["No. La entrega debe estar sujeta al cumplimiento de un objetivo, pero que se vaya a realizar, no que ya esté realizado (**art. 2.1.c**).","No. Las prestaciones de la Seguridad Social no son subvención (**art. 2.4**).","No. Se excluyen los premios sin solicitud previa. Los que se otorgan a solicitud sí entran (**art. 4.a**).","Es esta. Las prestaciones del Fondo de Garantía Salarial no son subvención (**art. 2.4**)."]},{"id":"vo-07-005","origen":"votaciones","test":"Clase 20 - Bloque III","n":5,"enunciado":"Según el artículo 2.4 de la Ley 38/2003, de 17 de noviembre, General de Subvenciones, no tienen carácter de subvenciones:","opciones":["Las otorgadas como consecuencia de la Política Agrícola Común.","Las que financien proyectos relacionados con la ciencia y la tecnología.","Los beneficios fiscales y beneficios en la cotización a la Seguridad Social.","Las destinadas a fomentar actividades de interés social."],"bloque":"subv-general","precepto":"art. 2.4.g","correcta":2,"justificaciones":["No. Las ayudas de la PAC se financian con fondos de la Unión y se rigen por su normativa (**art. 6**), pero siguen siendo subvenciones.","No. Financiar proyectos de ciencia es un fin que puede subvencionarse (**art. 2.1.c**).","Es esta. Los beneficios fiscales y los beneficios en la cotización a la Seguridad Social no son subvenciones (**art. 2.4.g**).","No. Fomentar actividades de interés social es el objeto típico de una subvención (**art. 2.1.c**)."],"dup":"of-08-010"},{"id":"vo-07-006","origen":"votaciones","test":"Clase 20 - Bloque III","n":6,"enunciado":"De acuerdo con el artículo 10 de la Ley 38/2003, ¿quién tiene la competencia para la concesión de una subvención de cuantía de 10 millones de euros en un Organismo Autónomo?","opciones":["El Presidente o Director del Organismo Autónomo, sin que esta competencia pueda ser objeto de desconcentración.","El Presidente o Director del Organismo Autónomo previa autorización del Consejo de Ministros, sin que esta competencia pueda ser objeto de desconcentración.","El Presidente o Director del Organismo Autónomo; esta competencia podrá ser objeto de desconcentración.","El Presidente o Director del Organismo Autónomo previa autorización del Consejo de Ministros; esta competencia podrá ser objeto de desconcentración."],"bloque":"subv-general","precepto":"art. 10","correcta":2,"justificaciones":["No. Sí puede desconcentrarse (**art. 10.3**).","No. Diez millones no supera el umbral de 12, así que no hace falta autorización, y además sí puede desconcentrarse (**art. 10.2 y 3**).","Es esta. Concede su presidente o director, sin autorización por no superar 12 millones, y la competencia puede desconcentrarse por real decreto (**art. 10.1, 2 y 3**).","No. No hace falta autorización con diez millones (**art. 10.2**)."],"dup":"of-09-021"},{"id":"vo-07-007","origen":"votaciones","test":"Clase 20 - Bloque III","n":7,"enunciado":"Según el artículo 10 de la LGS, en un organismo autónomo, ¿cuál es la autoridad competente para conceder una subvención de cuantía superior a 12 millones de euros?","opciones":["El Consejo de Ministros.","El Presidente o Director del organismo autónomo, con autorización del Consejo de Ministros.","El titular del Departamento ministerial, con autorización del Consejo de Ministros.","El Presidente o Director del organismo autónomo, con autorización del titular del Departamento ministerial."],"bloque":"subv-general","precepto":"art. 10","correcta":1,"justificaciones":["No. Concede el presidente o director del organismo, el Consejo de Ministros solo autoriza (**art. 10.2**).","Es esta. Concede el presidente o director del organismo, con autorización previa del Consejo de Ministros (**art. 10.1 y 2**).","No. El titular del Departamento no sustituye al presidente o director del organismo (**art. 10.1**).","No. La autorización la da el Consejo de Ministros, no el Departamento (**art. 10.2**)."]},{"id":"vo-07-008","origen":"votaciones","test":"Clase 20 - Bloque III","n":8,"enunciado":"Conforme a la LGS, ¿cuál de los siguientes NO es un requisito que debe cumplir el otorgamiento de una subvención?","opciones":["La competencia del órgano administrativo concedente.","La existencia de crédito adecuado y suficiente para atender las obligaciones económicas que se derivan de su concesión.","La tramitación del procedimiento de concesión de acuerdo con las normas que resulten de aplicación.","La audiencia pública."],"bloque":"subv-general","precepto":"art. 9.4","correcta":3,"justificaciones":["Sí es requisito. Competencia del órgano concedente (**art. 9.4.a**).","Sí es requisito. Crédito adecuado y suficiente (**art. 9.4.b**).","Sí es requisito. Tramitación del procedimiento conforme a las normas aplicables (**art. 9.4.c**).","Es la que NO. La audiencia pública no aparece entre los requisitos del art. 9.4."]},{"id":"vo-07-009","origen":"votaciones","test":"Clase 20 - Bloque III","n":9,"enunciado":"La aprobación de las bases reguladoras de las subvenciones, a nivel estatal, se lleva a cabo por:","opciones":["Real Decreto del Consejo de Ministros.","Por Orden ministerial.","Resolución, o en su caso, instrucción.","Ley Orgánica."],"bloque":"subv-general","precepto":"art. 17.1","correcta":1,"justificaciones":["No. No se aprueban por Real Decreto (**art. 17.1**).","Es esta. Las aprueba el ministro correspondiente por orden ministerial (**art. 17.1**).","No. Resolución o instrucción no es la vía en la AGE (**art. 17.1**).","No. No se aprueban por ley orgánica (**art. 17.1**)."]},{"id":"vo-07-010","origen":"votaciones","test":"Clase 20 - Bloque III","n":10,"enunciado":"Según establece el artículo 20 de la Ley 38/2003, ¿quién es el órgano responsable de la administración y custodia de la Base de Datos Nacional de Subvenciones (BDNS)?","opciones":["Intervención General de la Administración del Estado.","Secretaría de Estado de Hacienda.","Agencia Estatal de Administración Tributaria.","Ninguna de las respuestas anteriores es correcta."],"bloque":"subv-general","precepto":"art. 20.3","correcta":0,"justificaciones":["Es esta. La Intervención General de la Administración del Estado (**art. 20.3**).","No. La Secretaría de Estado de Hacienda no la administra (**art. 20.3**).","No. La Agencia Tributaria no la administra (**art. 20.3**).","No. Sí hay una respuesta correcta (**art. 20.3**)."],"dup":"of-09-019"},{"id":"vo-07-011","origen":"votaciones","test":"Clase 20 - Bloque III","n":11,"enunciado":"Según la LGS, la duración total, incluido prórrogas, de un convenio de colaboración entre un órgano administrativo concedente y una entidad colaboradora no podrá ser superior a:","opciones":["Cuatro años.","Cinco años.","Seis años.","Diez años."],"bloque":"subv-general","precepto":"art. 16.2","correcta":2,"justificaciones":["No. Cuatro años es la vigencia inicial, no el tope con prórrogas (**art. 16.2**).","No. Cinco años no es el tope (**art. 16.2**).","Es esta. Cuatro años de vigencia inicial y, con prórrogas, seis años en total (**art. 16.2**).","No. Seis años es el tope, no diez (**art. 16.2**)."]},{"id":"vo-07-012","origen":"votaciones","test":"Clase 20 - Bloque III","n":12,"enunciado":"El artículo 22.2 de la Ley 38/2003, habla de la concesión de las subvenciones nominativas previstas en los Presupuestos Generales del Estado, ¿cuál es el procedimiento para dicha concesión?","opciones":["La concurrencia competitiva.","La evaluación individualizada.","La subasta pública.","La concesión directa."],"bloque":"subv-concesion","precepto":"art. 22.2.a","correcta":3,"justificaciones":["No. La concurrencia competitiva es el procedimiento ordinario (**art. 22.1**).","No. La ley no habla de evaluación individualizada para las nominativas (**art. 22.2.a**).","No. La subasta pública no es un procedimiento de concesión de subvenciones (**art. 22**).","Es esta. Las nominativas se conceden de forma directa (**art. 22.2.a**)."],"dup":"of-10-032"},{"id":"vo-07-013","origen":"votaciones","test":"Clase 20 - Bloque III","n":13,"enunciado":"De acuerdo con la Ley General de Subvenciones, ¿cómo se tramitará el procedimiento ordinario de concesión de subvenciones?","opciones":["Mediante la concesión directa a través de Real Decreto.","Mediante la concesión nominativa a través de Real Decreto.","En régimen de concurrencia competitiva.","Mediante la concesión nominativa en los Presupuestos Generales del Estado."],"bloque":"subv-concesion","precepto":"art. 22.1","correcta":2,"justificaciones":["No. La concesión directa es excepcional (**art. 22.2**).","No. La concesión nominativa es una forma de concesión directa, excepcional (**art. 22.2.a**).","Es esta. El procedimiento ordinario es la concurrencia competitiva (**art. 22.1**).","No. La nominativa es una forma de concesión directa, no el procedimiento ordinario (**art. 22.2.a**)."]},{"id":"vo-07-014","origen":"votaciones","test":"Clase 20 - Bloque III","n":14,"enunciado":"Conforme a la LGS, ¿cuál es el instrumento habitual para canalizar las subvenciones previstas en los Presupuestos Generales del Estado?","opciones":["La encomienda de gestión.","El encargo a un medio propio.","El convenio.","El contrato."],"bloque":"subv-concesion","precepto":"art. 28.1","correcta":2,"justificaciones":["No. La encomienda de gestión no es el instrumento habitual de las subvenciones (**art. 28.1**).","No. El encargo a medio propio no es una subvención (**art. 32 LCSP**).","Es esta. Los convenios son el instrumento habitual para las subvenciones nominativas de los Presupuestos (**art. 28.1**).","No. Un contrato tiene prestación a cambio, la subvención no (**art. 2.1 LGS**)."]},{"id":"vo-07-015","origen":"votaciones","test":"Clase 20 - Bloque III","n":15,"enunciado":"Conforme al Reglamento de la Ley General de Subvenciones, si las bases reguladoras permitieran subcontratar las actividades subvencionadas sin establecer límites cuantitativos, las subcontrataciones realizadas no podrán superar:","opciones":["El 20 % del importe de la actividad subvencionada, sumando los precios de todos los subcontratos.","El 30 % del importe de la actividad subvencionada, sumando los precios de todos los subcontratos.","El 40 % del importe de la actividad subvencionada, sumando los precios de todos los subcontratos.","El 50 % del importe de la actividad subvencionada, sumando los precios de todos los subcontratos."],"bloque":"subv-concesion","precepto":"art. 29.2","correcta":3,"justificaciones":["No. El tope supletorio es del 50 por ciento (**art. 29.2**).","No. El tope supletorio es del 50 por ciento (**art. 29.2**).","No. El tope supletorio es del 50 por ciento (**art. 29.2**).","Es esta. Si las bases no fijan límite, hasta el 50 por ciento del importe de la actividad subvencionada (**art. 29.2**)."],"ojo":"El enunciado cita el Reglamento, pero ya lo dice la propia LGS (art. 29.2)."},{"id":"vo-07-016","origen":"votaciones","test":"Clase 20 - Bloque III","n":16,"enunciado":"De conformidad con el artículo 30.2 de la LGS, el plazo de rendición de la cuenta justificativa será el que determinen las bases reguladoras y en su defecto se realizará, como máximo, en el plazo de:","opciones":["Un mes desde la finalización del plazo para la realización de la actividad.","Dos meses desde la finalización del plazo para la realización de la actividad.","Tres meses desde la finalización del plazo para la realización de la actividad.","Seis meses desde la finalización del plazo para la realización de la actividad."],"bloque":"subv-concesion","precepto":"art. 30.2","correcta":2,"justificaciones":["No. Un mes no es el plazo supletorio (**art. 30.2**).","No. Dos meses no es el plazo supletorio (**art. 30.2**).","Es esta. Como máximo, tres meses desde que finaliza el plazo de realización de la actividad (**art. 30.2**).","No. Seis meses no es el plazo supletorio (**art. 30.2**)."],"dup":"of-10-007"},{"id":"vo-07-017","origen":"votaciones","test":"Clase 20 - Bloque III","n":17,"enunciado":"Conforme a la LGS, podrán ser subvencionados con carácter excepcional:","opciones":["Los intereses deudores de las cuentas bancarias, cuando así lo prevea la normativa reguladora de la subvención.","Los intereses, recargos y sanciones administrativas y penales, cuando así lo prevea la normativa reguladora de la subvención.","Los gastos de procedimientos judiciales, cuando así lo prevea la normativa reguladora de la subvención.","Los gastos de garantía bancaria, cuando así lo prevea la normativa reguladora de la subvención."],"bloque":"subv-concesion","precepto":"art. 31.7","correcta":3,"justificaciones":["No. Los intereses deudores de cuentas bancarias nunca son subvencionables (**art. 31.7.a**).","No. Los intereses, recargos y sanciones nunca son subvencionables (**art. 31.7.b**).","No. Los gastos de procedimientos judiciales nunca son subvencionables (**art. 31.7.c**).","Es esta. Con carácter excepcional, los gastos de garantía bancaria, si lo prevé la normativa reguladora (**art. 31.7**)."]},{"id":"vo-07-018","origen":"votaciones","test":"Clase 20 - Bloque III","n":18,"enunciado":"Según el artículo 34 de la Ley 38/2003, General de Subvenciones, la resolución de concesión de la subvención conllevara:","opciones":["El compromiso del gasto.","La aprobación del gasto.","El reconocimiento de la obligación.","La autorización del gasto."],"bloque":"subv-concesion","precepto":"art. 34.2","correcta":0,"justificaciones":["Es esta. La resolución de concesión conlleva el compromiso del gasto (**art. 34.2**).","No. La aprobación del gasto es previa a la convocatoria o concesión directa (**art. 34.1**).","No. El reconocimiento de la obligación llega con la justificación y el pago (**art. 34.3**).","No. La autorización del gasto se hace antes (**art. 34.1**)."]},{"id":"vo-07-019","origen":"votaciones","test":"Clase 20 - Bloque III","n":19,"enunciado":"Con carácter previo a la convocatoria de la subvención o a la concesión directa de la misma, deberá efectuarse:","opciones":["La aprobación del gasto.","El compromiso del gasto.","La aprobación y compromiso del gasto.","La autorización del gasto"],"bloque":"subv-concesion","precepto":"art. 34.1","correcta":0,"justificaciones":["Es esta. Antes de la convocatoria o de la concesión directa se aprueba el gasto (**art. 34.1**).","No. El compromiso lo conlleva la resolución de concesión (**art. 34.2**).","No. Solo la aprobación va antes. El compromiso viene con la concesión (**art. 34.1 y 2**).","No. La ley habla de aprobación del gasto (**art. 34.1**)."]},{"id":"vo-07-020","origen":"votaciones","test":"Clase 20 - Bloque III","n":20,"enunciado":"En un procedimiento de concesión de subvenciones en régimen de concurrencia competitiva, debe tramitarse el oportuno expediente de gasto:","opciones":["Única y excepcionalmente si se contempla una cuantía adicional a la cuantía total máxima establecida en la convocatoria.","Cuando se haya previsto expresamente en la normativa reguladora.","Con carácter previo a la convocatoria de las subvenciones.","Solo antes de la resolución de concesión de las subvenciones."],"bloque":"subv-concesion","precepto":"art. 34.1","correcta":2,"justificaciones":["No. El expediente de gasto es previo a la convocatoria en todo caso. La cuantía adicional solo afecta al crédito previsto (**art. 34.1**).","No. No depende de que lo diga la normativa reguladora, lo exige la ley (**art. 34.1**).","Es esta. Con carácter previo a la convocatoria (**art. 34.1**).","No. Es previo a la convocatoria, no solo antes de la resolución (**art. 34.1**)."]},{"id":"vo-07-021","origen":"votaciones","test":"Clase 20 - Bloque III","n":21,"enunciado":"De conformidad con la Ley 38/2003, el derecho de la Administración a reconocer o liquidar el reintegro de una subvención prescribirá a los:","opciones":["Dos años.","Tres años.","Cuatro años.","No prescribe."],"bloque":"subv-reintegro","precepto":"art. 39.1","correcta":2,"justificaciones":["No. Dos años no es el plazo (**art. 39.1**).","No. Tres años no es el plazo (**art. 39.1**).","Es esta. Cuatro años (**art. 39.1**).","No. Sí prescribe (**art. 39.1**)."],"dup":"of-11-004"},{"id":"vo-07-022","origen":"votaciones","test":"Clase 20 - Bloque III","n":22,"enunciado":"La Ley General de Subvenciones establece que el plazo máximo para resolver y notificar la resolución del procedimiento de reintegro de una subvención será, desde la fecha del acuerdo de iniciación, de:","opciones":["3 meses.","6 meses.","9 meses.","12 meses."],"bloque":"subv-reintegro","precepto":"art. 42.4","correcta":3,"justificaciones":["No. El plazo es de doce meses (**art. 42.4**).","No. El plazo es de doce meses (**art. 42.4**).","No. El plazo es de doce meses (**art. 42.4**).","Es esta. Doce meses desde el acuerdo de iniciación, con caducidad si vence (**art. 42.4**)."]},{"id":"vo-07-023","origen":"votaciones","test":"Clase 20 - Bloque III","n":23,"enunciado":"Según la LGS, cuando proceda el reintegro, se exigirá el interés de demora correspondiente, calculado:","opciones":["Desde el momento de concesión de la subvención hasta la fecha en que el interesado pague la obligación de reintegro.","Desde el momento de pago de la subvención hasta la fecha en que se acuerde el reintegro.","Desde el momento de concesión de la subvención hasta la fecha en que se inicie el procedimiento de reintegro.","Desde el momento de pago de la subvención hasta la fecha en que se inicie el procedimiento de reintegro."],"bloque":"subv-reintegro","precepto":"art. 37.1","correcta":1,"justificaciones":["No. El interés corre desde el pago, no desde la concesión, y hasta el acuerdo de reintegro o el ingreso (**art. 37.1**).","Es esta. Desde el pago de la subvención hasta la fecha en que se acuerde la procedencia del reintegro (**art. 37.1**).","No. Corre desde el pago, no desde la concesión (**art. 37.1**).","No. Termina cuando se acuerda el reintegro, no cuando se inicia el procedimiento (**art. 37.1**)."],"ojo":"El art. 37.1 añade que, si el deudor ingresa antes, el interés llega hasta esa fecha."},{"id":"vo-07-024","origen":"votaciones","test":"Clase 20 - Bloque III","n":24,"enunciado":"El plazo de prescripción de las infracciones y sanciones en el ámbito de la LGS es de:","opciones":["4 años tanto para las infracciones como para las sanciones.","3 años para las infracciones y 5 años para las sanciones.","5 años para las infracciones y 3 años para las sanciones.","3 años tanto para las infracciones como para las sanciones."],"bloque":"subv-sanciones","precepto":"art. 65","correcta":0,"justificaciones":["Es esta. Infracciones y sanciones prescriben a los cuatro años (**art. 65**).","No. Son cuatro años para ambas (**art. 65**).","No. Son cuatro años para ambas (**art. 65**).","No. Son cuatro años, no tres (**art. 65**)."]},{"id":"vo-07-025","origen":"votaciones","test":"Clase 20 - Bloque III","n":25,"enunciado":"En el ámbito estatal, la competencia para imponer sanciones pecuniarias en materia de subvenciones corresponde a:","opciones":["El Consejo de Ministros.","El ministro de Hacienda.","El órgano concedente, en todo caso.","Los Ministros y los Secretarios de Estado."],"bloque":"subv-sanciones","precepto":"art. 66.1","correcta":3,"justificaciones":["No. El Consejo de Ministros solo impone las sanciones más graves de pérdida de ayudas y prohibición de contratar (**art. 66.1**).","No. No es el Ministro de Hacienda sino los de los departamentos concedentes (**art. 66.1**).","No. El órgano concedente, sin más, no es la regla en la AGE (**art. 66.1**).","Es esta. Las acuerdan e imponen los Ministros o los Secretarios de Estado de los departamentos concedentes (**art. 66.1**)."]},{"id":"vo-07-026","origen":"votaciones","test":"Clase 20 - Bloque III","n":26,"enunciado":"Siguiendo lo dispuesto en la Ley 38/2003, ¿cuál de las siguientes infracciones se tipificaría como grave?","opciones":["La resistencia, obstrucción, excusa o negativa a las actuaciones de control financiero.","La presentación de cuentas justificativas inexactas o incompletas.","La falta de justificación del empleo dado a los fondos recibidos una vez transcurrido el plazo establecido para su presentación.","El incumplimiento de la obligación de llevar o conservar la contabilidad, los registros legalmente establecidos, los programas y archivos informáticos que les sirvan de soporte y los sistemas de codificación utilizados."],"bloque":"subv-sanciones","precepto":"art. 57.c","correcta":2,"justificaciones":["No. La resistencia u obstrucción al control financiero es muy grave (**art. 58.c**).","No. Las cuentas justificativas inexactas o incompletas son infracción leve (**art. 56.b**).","Es esta. La falta de justificación una vez pasado el plazo es grave (**art. 57.c**).","No. Incumplir la llevanza o conservación de contabilidad es leve (**art. 56.d**)."]},{"id":"vo-15-001","origen":"votaciones","test":"Clase repaso 20 - Bloque III","n":1,"enunciado":"Según la ley 38/2003, de 17 de noviembre, general de subvenciones, se entiende por subvención toda disposición dineraria realizada por cualquier administración pública, a favor de personas públicas o privadas, y que cumpla los siguientes requisitos:","opciones":["Que la entrega esté sujeta al cumplimiento de un indeterminado objetivo.","Que la entrega se realice con contraprestación directa de los beneficiarios.","Que el proyecto, la acción, conducta o situación financiada tenga por objeto el fomento de una actividad de utilidad pública o interés social o de promoción de una finalidad pública.","Todas son correctas."],"bloque":"subv-general","precepto":"art. 2.1","correcta":2,"justificaciones":["No. El objetivo es determinado, no indeterminado (**art. 2.1.b**).","No. Es sin contraprestación directa (**art. 2.1.a**).","Es esta. Fomento de una actividad de utilidad pública o interés social, o de una finalidad pública (**art. 2.1.c**).","No. Solo la tercera es correcta (**art. 2.1**)."]},{"id":"vo-15-002","origen":"votaciones","test":"Clase repaso 20 - Bloque III","n":2,"enunciado":"Según el artículo 2 LGS, no tienen carácter de subvenciones: (indique la incorrecta)","opciones":["Las prestaciones contributivas y no contributivas de la Seguridad Social.","Los beneficios fiscales y beneficios en la cotización a la Seguridad Social.","Las prestaciones reconocidas por el Fondo de Garantía Social.","Las ayudas económicas de emergencia o urgencia social gestionadas por las administraciones competentes a través de los servicios sociales, destinadas a cubrir necesidades básicas de la ciudadanía."],"bloque":"subv-general","precepto":"art. 2.4","correcta":2,"justificaciones":["Es cierto. Las prestaciones de la Seguridad Social no son subvención (**art. 2.4.a**).","Es cierto. Los beneficios fiscales y en la cotización no son subvención (**art. 2.4.g**).","Es la incorrecta. Es el Fondo de Garantía Salarial, no 'Social' (**art. 2.4.f**).","Es cierto. Las ayudas de emergencia social no son subvención (**art. 2.4.j**)."]},{"id":"vo-15-003","origen":"votaciones","test":"Clase repaso 20 - Bloque III","n":3,"enunciado":"No están excluidos del ámbito de aplicación de la Ley 38/2003: (Ayto Vall d´Uixó C1 – 2024)","opciones":["Los premios que se otorguen previa solicitud del beneficiario.","Las subvenciones previstas en la Ley Orgánica 5/1985, de 19 de junio, del Régimen Electoral General.","Las subvenciones reguladas en la Ley Orgánica 3/1987, de 2 de julio, de Financiación de los Partidos Políticos.","Todas las respuestas son correctas."],"bloque":"subv-general","precepto":"art. 4","correcta":0,"justificaciones":["Es esta. Los premios con solicitud previa no están excluidos. Los que se dan sin solicitud, sí (**art. 4.a**).","No. La ley electoral está excluida (**art. 4.b**).","No. La financiación de partidos está excluida (**art. 4.c**).","No. Solo la primera es correcta (**art. 4**)."]},{"id":"vo-15-004","origen":"votaciones","test":"Clase repaso 20 - Bloque III","n":4,"enunciado":"El otorgamiento de una subvención debe cumplir los siguientes requisitos (indique la incorrecta):","opciones":["La competencia del órgano administrativo concedente.","La existencia de crédito adecuado y suficiente.","La fiscalización previa respecto a las subvenciones con asignación nominativa.","La aprobación del gasto por el órgano competente para ello."],"bloque":"subv-general","precepto":"art. 9.4","correcta":2,"justificaciones":["Sí es requisito. Competencia del órgano concedente (**art. 9.4.a**).","Sí es requisito. Crédito adecuado y suficiente (**art. 9.4.b**).","Es la incorrecta. La fiscalización previa se exige respecto de los actos de contenido económico en general, no solo de las nominativas (**art. 9.4.d**).","Sí es requisito. Aprobación del gasto por el órgano competente (**art. 9.4.e**)."]},{"id":"vo-15-005","origen":"votaciones","test":"Clase repaso 20 - Bloque III","n":5,"enunciado":"¿Quién es la autoridad competente para conceder una subvención de cuantía superior a 12 millones de euros?:","opciones":["Los Directores Generales de las distintas Entidades Gestoras y Servicios Comunes de la Seguridad Social, previa autorización del Consejo de Estado.","El Presidente o Director del organismo autónomo, con autorización del Ministro correspondiente.","El Consejo de Ministros.","El Ministro en la Administración General del Estado, con autorización del Consejo de Ministros."],"bloque":"subv-general","precepto":"art. 10","correcta":3,"justificaciones":["No. La autorización no la da el Consejo de Estado (**art. 10.2**).","No. La autorización no la da el Ministro, sino el Consejo de Ministros (**art. 10.2**).","No. El Consejo de Ministros autoriza, no concede (**art. 10.2**).","Es esta. Concede el Ministro, con autorización previa del Consejo de Ministros (**art. 10.1 y 2**)."]},{"id":"vo-15-006","origen":"votaciones","test":"Clase repaso 20 - Bloque III","n":6,"enunciado":"En el ámbito de la Administración General del Estado, las bases reguladoras de la concesión del artículo 17 de la LGS:","opciones":["Serán objeto de publicación en la BDNS.","Se aprobarán por Real Decreto.","Su aprobación requerirá informe previo de los servicios jurídicos y de la Intervención Delegada correspondiente.","Requieren autorización previa del Ministro."],"bloque":"subv-general","precepto":"art. 17.1","correcta":2,"justificaciones":["No. La BDNS no publica las bases así (**art. 17**).","No. Se aprueban por orden ministerial (**art. 17.1**).","Es esta. Informe previo de los servicios jurídicos y de la Intervención Delegada (**art. 17.1**).","No. No requieren autorización del Ministro, las aprueba él (**art. 17.1**)."]},{"id":"vo-15-007","origen":"votaciones","test":"Clase repaso 20 - Bloque III","n":7,"enunciado":"La BDNS podrá suministrar información pública sobre las:","opciones":["Sanciones firmes impuestas por infracciones graves.","Infracciones firmes impuestas por sanciones graves.","Sanciones firmes impuestas por infracciones muy graves.","Infracciones firmes impuestas por sanciones muy graves."],"bloque":"subv-general","precepto":"art. 20.9","correcta":2,"justificaciones":["No. Se refiere a infracciones muy graves (**art. 20.9**).","No. Están al revés: las sanciones se imponen por infracciones (**art. 20.9**).","Es esta. Sanciones firmes impuestas por infracciones muy graves (**art. 20.9**).","No. Está al revés (**art. 20.9**)."]},{"id":"vo-15-008","origen":"votaciones","test":"Clase repaso 20 - Bloque III","n":8,"enunciado":"Según el artículo 22.2 de la Ley 38/2003, de 17 de noviembre, General de Subvenciones, podrán concederse de forma directa: (Diputación Badajoz A2 – 2025)","opciones":["Excepcionalmente, las subvenciones en que se acrediten razones de interés público, social, económico o humanitario u otras debidamente justificadas que dificulten su convocatoria pública.","Las subvenciones por cuantía superior a la que se determine en la convocatoria.","Las subvenciones que no estén previstas nominativamente en los Presupuestos de las Entidades Locales.","Aquellas cuyo otorgamiento o cuantía venga impuesto a la Administración por una norma de rango reglamentario."],"bloque":"subv-concesion","precepto":"art. 22.2.c","correcta":0,"justificaciones":["Es esta. Con carácter excepcional, razones de interés público, social, económico o humanitario que dificulten la convocatoria pública (**art. 22.2.c**).","No. La cuantía no es motivo de concesión directa (**art. 22.2**).","No. Las nominativas de los Presupuestos locales sí son directas (**art. 22.2.a**).","No. Las que impone la norma son de rango legal, no reglamentario (**art. 22.2.b**)."]},{"id":"vo-15-009","origen":"votaciones","test":"Clase repaso 20 - Bloque III","n":9,"enunciado":"El plazo máximo para resolver y notificar la resolución del procedimiento de concesión de régimen de concurrencia competitiva será, por regla general, de:","opciones":["6 meses, a partir de la publicación de las bases.","6 meses, a partir del final del plazo de presentación de solicitudes.","6 meses, a partir de la aprobación de la convocatoria.","6 meses, a partir de la publicación de la correspondiente convocatoria."],"bloque":"subv-concesion","precepto":"art. 25.4","correcta":3,"justificaciones":["No. Se computa desde la publicación de la convocatoria, no de las bases (**art. 25.4**).","No. No es desde el fin del plazo de solicitudes (**art. 25.4**).","No. No es desde la aprobación de la convocatoria (**art. 25.4**).","Es esta. Seis meses desde la publicación de la convocatoria (**art. 25.4**)."]},{"id":"vo-15-010","origen":"votaciones","test":"Clase repaso 20 - Bloque III","n":10,"enunciado":"De acuerdo con el artículo 29 de la ley 38/2003, ¿en cuál de los siguientes supuestos sería necesario que la subcontratación de la actividad se formalice en contrato por escrito previa autorización de la entidad concedente de la subvención? (Diputación A Coruña A2 - 2026)","opciones":["Cuando la actividad concertada con terceros sobrepase del 20 por ciento del importe de la subvención y dicho importe sea superior a 50.000 euros.","Cuando la actividad concertada con terceros sobrepase del 30 por ciento del importe de la subvención y dicho importe sea superior a 60.000 euros.","Cuando la actividad concertada con terceros sobrepase del 20 por ciento del importe de la subvención y dicho importe sea igual o superior a 60.000 euros.","Cuando la actividad concertada con terceros sobrepase del 20 por ciento del importe de la subvención y dicho importe sea superior a 60.000 euros."],"bloque":"subv-concesion","precepto":"art. 29.3","correcta":3,"justificaciones":["No. El umbral es 60.000 euros, no 50.000 (**art. 29.3**).","No. El porcentaje es del 20 por ciento, no del 30 (**art. 29.3**).","No. El importe debe ser superior a 60.000, no igual o superior (**art. 29.3**).","Es esta. Más del 20 por ciento del importe y más de 60.000 euros (**art. 29.3**)."]},{"id":"vo-15-011","origen":"votaciones","test":"Clase repaso 20 - Bloque III","n":11,"enunciado":"A falta de previsión en la norma reguladora de la subvención, la justificación se realizará, como máximo, en el plazo de:","opciones":["6 meses desde el otorgamiento de la subvención.","3 meses desde la realización del pago del último gasto vinculado a la actividad.","3 meses desde la finalización del plazo para la realización de la actividad.","Ninguna de las opciones es correcta."],"bloque":"subv-concesion","precepto":"art. 30.2","correcta":2,"justificaciones":["No. No hay plazo de seis meses desde el otorgamiento (**art. 30**).","No. No se cuenta desde el pago del último gasto (**art. 30**).","Es esta. Tres meses desde la finalización del plazo para realizar la actividad (**art. 30.2**).","No. Una es correcta (**art. 30.2**)."],"revisar":"El plazo supletorio de tres meses figura en el art. 30 y en el Reglamento (art. 70). Compruébalo contra el BOE."},{"id":"vo-15-012","origen":"votaciones","test":"Clase repaso 20 - Bloque III","n":12,"enunciado":"Indique la respuesta CORRECTA. De acuerdo con la Ley 38/2003, de 17 de noviembre, general de subvenciones, en ningún caso serán gastos subvencionables: (GVA A1 – 2025)","opciones":["Los tributos, cuando el beneficiario de la subvención los abona efectivamente.","Los gastos de asesoría jurídica.","Los impuestos indirectos susceptibles de recuperación.","Los gastos financieros."],"bloque":"subv-concesion","precepto":"art. 31.8","correcta":2,"justificaciones":["No. Los tributos efectivamente abonados sí son subvencionables (**art. 31.8**).","No. Los de asesoría jurídica son subvencionables si lo prevén las bases (**art. 31.7**).","Es esta. Los impuestos indirectos susceptibles de recuperación no son subvencionables (**art. 31.8**).","No. Los gastos financieros son subvencionables si lo prevén las bases (**art. 31.7**)."]},{"id":"vo-15-013","origen":"votaciones","test":"Clase repaso 20 - Bloque III","n":13,"enunciado":"En relación al procedimiento de aprobación del gasto y pago:","opciones":["El compromiso del gasto deberá efectuarse con carácter previo a la convocatoria de la subvención o a la concesión directa de la misma.","La convocatoria de la subvención conllevará el compromiso del gasto correspondiente.","La aprobación del gasto deberá efectuarse con carácter posterior a la convocatoria de la subvención o a la concesión directa de la misma.","La resolución de concesión de la subvención conllevará el compromiso del gasto correspondiente."],"bloque":"subv-concesion","precepto":"art. 34","correcta":3,"justificaciones":["No. Previa va la aprobación del gasto, no el compromiso (**art. 34.1**).","No. La convocatoria no conlleva el compromiso, lo hace la resolución de concesión (**art. 34.2**).","No. La aprobación va antes de la convocatoria, no después (**art. 34.1**).","Es esta. La resolución de concesión conlleva el compromiso del gasto (**art. 34.2**)."]},{"id":"vo-15-014","origen":"votaciones","test":"Clase repaso 20 - Bloque III","n":14,"enunciado":"Según el art. 37 de la Ley 38/2003, de 17 de noviembre, General de Subvenciones, NO es una causa de reintegro de las cantidades percibidas: (Salamanca A2 – 2023)","opciones":["La obtención de la subvención falseando las condiciones requeridas para ello.","El incumplimiento de la obligación de justificación o justificación insuficiente.","La carencia o insuficiencia de crédito.","La resistencia a las actuaciones de comprobación y control financiero."],"bloque":"subv-reintegro","precepto":"art. 37.1","correcta":2,"justificaciones":["Sí es causa. Obtener la subvención falseando las condiciones (**art. 37.1.a**).","Sí es causa. Incumplir la obligación de justificación o justificarla insuficientemente (**art. 37.1.c**).","Es la que NO. La carencia o insuficiencia de crédito no figura entre las causas de reintegro (**art. 37.1**).","Sí es causa. La resistencia a las actuaciones de comprobación y control (**art. 37.1.e**)."]},{"id":"vo-15-015","origen":"votaciones","test":"Clase repaso 20 - Bloque III","n":15,"enunciado":"El interés de demora se calculará:","opciones":["Desde el momento del gasto de la subvención hasta la fecha en que se acuerde la procedencia del reintegro.","Desde el momento del pago de la subvención hasta la fecha en que se notifique la procedencia del reintegro.","Desde el momento de la justificación de la subvención hasta la fecha en que se valore la procedencia del reintegro.","Desde el momento del pago de la subvención hasta la fecha en que se acuerde la procedencia del reintegro."],"bloque":"subv-reintegro","precepto":"art. 37.1","correcta":3,"justificaciones":["No. Corre desde el pago, no desde el gasto (**art. 37.1**).","No. Termina cuando se acuerda, no cuando se notifica (**art. 37.1**).","No. Corre desde el pago, no desde la justificación (**art. 37.1**).","Es esta. Desde el pago hasta la fecha en que se acuerde la procedencia del reintegro (**art. 37.1**)."]},{"id":"vo-15-016","origen":"votaciones","test":"Clase repaso 20 - Bloque III","n":16,"enunciado":"Según el artículo 39 de la Ley 38/2003, de 17 de noviembre, General de Subvenciones, el derecho de la Administración a liquidar el reintegro de la subvención prescribirá a los: (Diputación Palencia A2 – 2025)","opciones":["Tres años.","Cuatro años.","Cinco años.","Seis años."],"bloque":"subv-reintegro","precepto":"art. 39.1","correcta":1,"justificaciones":["No. Son cuatro años (**art. 39.1**).","Es esta. Cuatro años (**art. 39.1**).","No. Son cuatro años (**art. 39.1**).","No. Son cuatro años (**art. 39.1**)."]},{"id":"vo-15-017","origen":"votaciones","test":"Clase repaso 20 - Bloque III","n":17,"enunciado":"En el marco de un procedimiento de concesión de subvenciones, el plazo máximo para resolver y notificar un procedimiento de reintegro será de:","opciones":["12 meses desde la notificación del acuerdo de iniciación.","6 meses desde la notificación del acuerdo de iniciación.","3 meses desde la fecha del acuerdo de iniciación.","12 meses desde la fecha del acuerdo de iniciación."],"bloque":"subv-reintegro","precepto":"art. 42.4","correcta":3,"justificaciones":["No. Se cuenta desde la fecha del acuerdo, no desde su notificación (**art. 42.4**).","No. Son doce meses (**art. 42.4**).","No. Son doce meses (**art. 42.4**).","Es esta. Doce meses desde la fecha del acuerdo de iniciación (**art. 42.4**)."]},{"id":"vo-15-018","origen":"votaciones","test":"Clase repaso 20 - Bloque III","n":18,"enunciado":"De acuerdo con el artículo 56 de la Ley 38/2003, NO es una infracción leve: (Junta Andalucía A1 - 2016)","opciones":["La falta de justificación del empleo dado a los fondos recibidos una vez transcurrido el plazo establecido para su presentación.","La presentación de cuentas justificativas inexactas o incompletas.","La resistencia, obstrucción, excusa o negativa a las actuaciones del control financiero.","El incumplimiento de la obligación de llevar o conservar la contabilidad."],"bloque":"subv-sanciones","precepto":"arts. 56 a 58","correcta":0,"justificaciones":["No es leve. La falta de justificación pasado el plazo es infracción grave (**art. 57.c**).","Sí es leve. Cuentas justificativas inexactas o incompletas (**art. 56.b**).","Tampoco es leve. La resistencia al control financiero es muy grave (**art. 58.c**).","Sí es leve. No llevar o conservar la contabilidad (**art. 56.d.2.º**)."],"ojo":"Pregunta defectuosa: la 0 (grave) y la 2 (muy grave) no son leves. Se marca la 0."},{"id":"vo-15-019","origen":"votaciones","test":"Clase repaso 20 - Bloque III","n":19,"enunciado":"Respecto a las sanciones pecuniarias, podrán consistir en:","opciones":["Una multa fija comprendida entre 65 y 6.000 €.","Una multa proporcional que puede ir del tanto al doble de la cantidad indebidamente obtenida, aplicada o no justificada.","Una multa fija comprendida entre 75 y 6.000 €.","Una multa fija que puede ir del tanto al triple de la cantidad indebidamente obtenida, aplicada o no justificada."],"bloque":"subv-sanciones","precepto":"art. 59.2","correcta":2,"justificaciones":["No. La multa fija es de 75 a 6.000 euros (**art. 59.2**).","No. La multa proporcional llega al triple, no al doble (**art. 59.2**).","Es esta. Multa fija de 75 a 6.000 euros (**art. 59.2**).","No. La multa fija no se mide en proporción, y el triple corresponde a la multa proporcional (**art. 59.2**)."]},{"id":"vo-15-020","origen":"votaciones","test":"Clase repaso 20 - Bloque III","n":20,"enunciado":"Según el artículo 65 de la Ley 38/2003, de 17 de noviembre, General de Subvenciones, las infracciones en materia de subvenciones prescriben: (Diputación Palencia A2 – 2025)","opciones":["En el plazo de cuatro años a contar desde el día en que la infracción se hubiera cometido.","En el plazo de cuatro años a contar desde el día en que la subvención se hubiera concedido.","En el plazo de cuatro años a contar desde el día siguiente a aquel en que hubiera adquirido firmeza la resolución por la que se impuso la sanción.","Ninguna respuesta es correcta."],"bloque":"subv-sanciones","precepto":"art. 65.1","correcta":0,"justificaciones":["Es esta. Cuatro años desde el día en que se cometió la infracción (**art. 65.1**).","No. Se cuenta desde la comisión de la infracción, no desde la concesión (**art. 65.1**).","No. Eso es la prescripción de las sanciones, que corre desde la firmeza (**art. 65.2**).","No. La primera es correcta (**art. 65.1**)."]},{"id":"pr-54-001","origen":"practicas","test":"Ejercicio 22.- Tipos de Actividad","n":1,"enunciado":"Beneficio en las cotizaciones a la Seguridad Social otorgado por el Ministerio de Trabajo.","opciones":["Actividad de Fomento.","Actividad de Servicio Público.","Actividad de Policía."],"bloque":"subv-general","precepto":"Tipos de actividad administrativa (fomento)","correcta":0,"justificaciones":["Correcta: una bonificación en las cotizaciones es un incentivo para estimular una conducta, es decir, fomento.","No: no se presta un servicio a la ciudadanía.","No: no limita derechos ni impone una conducta."]},{"id":"pr-54-002","origen":"practicas","test":"Ejercicio 22.- Tipos de Actividad","n":2,"enunciado":"Nueva línea de tren realizada por el Ministerio de Fomento.","opciones":["Actividad de Fomento.","Actividad de Servicio Público.","Actividad de Policía."],"bloque":"subv-general","precepto":"Tipos de actividad administrativa (fomento)","correcta":1,"justificaciones":["No: no se incentiva a nadie a actuar, se construye una infraestructura.","Correcta: construir y explotar una línea de tren es prestar un servicio público, aunque el ministerio se llame de Fomento.","No: no se limita ninguna actividad privada."],"ojo":"El nombre del ministerio engaña: la actividad es de servicio público, no de fomento."},{"id":"pr-54-003","origen":"practicas","test":"Ejercicio 22.- Tipos de Actividad","n":3,"enunciado":"El Estado concede incentivos fiscales para impulsar la rehabilitación energética de edificios.","opciones":["Actividad de Fomento.","Actividad de Servicio Público.","Actividad de Policía."],"bloque":"subv-general","precepto":"Tipos de actividad administrativa (fomento)","correcta":0,"justificaciones":["Correcta: los incentivos fiscales para rehabilitar edificios estimulan una conducta privada, es decir, fomento.","No: no se presta ningún servicio.","No: no limita derechos ni sanciona."]},{"id":"pr-54-004","origen":"practicas","test":"Ejercicio 22.- Tipos de Actividad","n":4,"enunciado":"La Inspección de Trabajo requiere a una empresa que subsane incumplimientos de la normativa de prevención de riesgos laborales.","opciones":["Actividad de Fomento.","Actividad de Servicio Público.","Actividad de Policía."],"bloque":"subv-general","precepto":"Tipos de actividad administrativa (fomento)","correcta":2,"justificaciones":["No: no se concede ninguna ventaja para incentivar nada.","No: no se presta un servicio a los ciudadanos.","Correcta: requerir la subsanación de incumplimientos normativos es policía administrativa, una actividad de limitación."]},{"id":"pr-54-005","origen":"practicas","test":"Ejercicio 22.- Tipos de Actividad","n":5,"enunciado":"Un ayuntamiento mantiene un servicio municipal de recogida de residuos urbanos.","opciones":["Actividad de Fomento.","Actividad de Servicio Público.","Actividad de Policía."],"bloque":"subv-general","precepto":"Tipos de actividad administrativa (fomento)","correcta":1,"justificaciones":["No: no se incentiva a nadie.","Correcta: la recogida de residuos urbanos es un servicio que presta el ayuntamiento, un servicio público.","No: el ayuntamiento no restringe ninguna actividad ni derecho de los particulares."]},{"id":"pr-54-006","origen":"practicas","test":"Ejercicio 22.- Tipos de Actividad","n":6,"enunciado":"El Ministerio de Educación concede becas a estudiantes para financiar sus estudios universitarios.","opciones":["Actividad de Fomento.","Actividad de Servicio Público.","Actividad de Policía."],"bloque":"subv-general","precepto":"Tipos de actividad administrativa (fomento)","correcta":0,"justificaciones":["Correcta: las becas son ayudas económicas que fomentan una actividad de interés, es decir, fomento.","No: no hay un servicio prestado directamente.","No: no se limita ningún derecho."]},{"id":"pr-54-007","origen":"practicas","test":"Ejercicio 22.- Tipos de Actividad","n":7,"enunciado":"La autoridad sanitaria ordena el cierre temporal de un restaurante por graves deficiencias higiénicas.","opciones":["Actividad de Fomento.","Actividad de Servicio Público.","Actividad de Policía."],"bloque":"subv-general","precepto":"Tipos de actividad administrativa (fomento)","correcta":2,"justificaciones":["No: no se otorga ningún beneficio.","No: no se presta un servicio público.","Correcta: ordenar el cierre de un local por incumplir normas sanitarias es policía, actividad de limitación."]},{"id":"pr-54-008","origen":"practicas","test":"Ejercicio 22.- Tipos de Actividad","n":8,"enunciado":"La Administración concede una ayuda a una entidad sin ánimo de lucro para desarrollar un proyecto de inclusión social.","opciones":["Actividad de Fomento.","Actividad de Servicio Público.","Actividad de Policía."],"bloque":"subv-general","precepto":"Tipos de actividad administrativa (fomento)","correcta":0,"justificaciones":["Correcta: la ayuda a una entidad sin ánimo de lucro para un proyecto social es fomento, y suele canalizarse como subvención.","No: no se presta el servicio directamente, se financia a un tercero.","No: la Administración no restringe ninguna actividad de la entidad, la financia."]},{"id":"pr-55-001","origen":"practicas","test":"Ejercicio 23.- Ámbito de aplicación.","n":1,"enunciado":"El Ministerio de Educación concede una ayuda de 1.000 euros a un estudiante para financiar sus estudios, previa solicitud y cumplimiento de los requisitos establecidos.","opciones":["Sí, se le aplicará la 38/2003.","No están comprendidas en el ámbito de aplicación de esta ley.","No tienen carácter de subvenciones.","Quedan excluidos del ámbito de aplicación de esta ley."],"bloque":"subv-general","precepto":"art. 2.1","correcta":0,"justificaciones":["Correcta: la ayuda a un estudiante, sin contraprestación y condicionada a requisitos, es una subvención de la Ley 38/2003 (art. 2.1).","No: aquí sí reúne los tres requisitos del art. 2.1.","No: sí tiene carácter de subvención.","No: no está entre las exclusiones del art. 4."]},{"id":"pr-55-002","origen":"practicas","test":"Ejercicio 23.- Ámbito de aplicación.","n":2,"enunciado":"El SEPE reconoce a una persona la prestación contributiva por desempleo tras perder su trabajo.","opciones":["Sí, se le aplicará la 38/2003.","No están comprendidas en el ámbito de aplicación de esta ley.","No tienen carácter de subvenciones.","Quedan excluidos del ámbito de aplicación de esta ley."],"bloque":"subv-general","precepto":"art. 2.4.a","correcta":2,"justificaciones":["No: las prestaciones de la Seguridad Social no son subvenciones.","No: la fórmula del art. 2.4 es “no tienen carácter de subvenciones”, no “no están comprendidas”.","Correcta: las prestaciones contributivas de la Seguridad Social no tienen carácter de subvención (art. 2.4.a).","No: las exclusiones del art. 4 son otras (premios sin solicitud, leyes electorales, partidos)."]},{"id":"pr-55-003","origen":"practicas","test":"Ejercicio 23.- Ámbito de aplicación.","n":3,"enunciado":"El Estado transfiere fondos a una comunidad autónoma para financiar globalmente su actividad, sin que la aportación proceda de una convocatoria pública.","opciones":["Sí, se le aplicará la 38/2003.","No están comprendidas en el ámbito de aplicación de esta ley.","No tienen carácter de subvenciones.","Quedan excluidos del ámbito de aplicación de esta ley."],"bloque":"subv-general","precepto":"art. 2.2","correcta":1,"justificaciones":["No: las aportaciones para financiar globalmente la actividad de otra Administración quedan fuera de la ley.","Correcta: no están comprendidas en el ámbito de aplicación las aportaciones entre Administraciones para financiar globalmente su actividad (art. 2.2).","No: la fórmula del art. 2.2 es “no están comprendidas”, no “no tienen carácter de subvención”.","No: las exclusiones del art. 4 son otras."]},{"id":"pr-55-004","origen":"practicas","test":"Ejercicio 23.- Ámbito de aplicación.","n":4,"enunciado":"Un ministerio concede de oficio un premio económico a una persona por una actuación meritoria, sin que esta lo haya solicitado ni participado en convocatoria alguna.","opciones":["Sí, se le aplicará la 38/2003.","No están comprendidas en el ámbito de aplicación de esta ley.","No tienen carácter de subvenciones.","Quedan excluidos del ámbito de aplicación de esta ley."],"bloque":"subv-general","precepto":"art. 4.a","correcta":3,"justificaciones":["No: un premio concedido sin solicitud previa está excluido.","No: la fórmula adecuada es la de exclusión del art. 4.","No: la ley no lo califica como “no subvención”, sino como excluido.","Correcta: quedan excluidos los premios que se otorguen sin la previa solicitud del beneficiario (art. 4.a)."]},{"id":"pr-55-005","origen":"practicas","test":"Ejercicio 23.- Ámbito de aplicación.","n":5,"enunciado":"La Administración bonifica fiscalmente a una empresa por invertir en investigación y desarrollo.","opciones":["Sí, se le aplicará la 38/2003.","No están comprendidas en el ámbito de aplicación de esta ley.","No tienen carácter de subvenciones.","Quedan excluidos del ámbito de aplicación de esta ley."],"bloque":"subv-general","precepto":"art. 2.4.g","correcta":2,"justificaciones":["No: un beneficio fiscal no es una subvención.","No: la fórmula del art. 2.4 es “no tienen carácter de subvenciones”.","Correcta: los beneficios fiscales no tienen carácter de subvención (art. 2.4.g).","No: no figura en las exclusiones del art. 4."]},{"id":"pr-55-006","origen":"practicas","test":"Ejercicio 23.- Ámbito de aplicación.","n":6,"enunciado":"Una comunidad autónoma concede una ayuda a una empresa para contratar a personas desempleadas, condicionada al mantenimiento del empleo durante un periodo determinado.","opciones":["Sí, se le aplicará la 38/2003.","No están comprendidas en el ámbito de aplicación de esta ley.","No tienen carácter de subvenciones.","Quedan excluidos del ámbito de aplicación de esta ley."],"bloque":"subv-general","precepto":"art. 2.1 y 3.3","correcta":0,"justificaciones":["Correcta: la ayuda condicionada al mantenimiento del empleo es una subvención, y la ley se aplica a la actividad subvencional de las comunidades (art. 3.3).","No: no hay ninguna exclusión aplicable.","No: sí tiene carácter de subvención.","No: no figura en el art. 4."]},{"id":"pr-55-007","origen":"practicas","test":"Ejercicio 23.- Ámbito de aplicación.","n":7,"enunciado":"El estado da una subvención de las reguladas en la Ley Orgánica de Financiación de los Partidos Políticos.","opciones":["Sí, se le aplicará la 38/2003.","No están comprendidas en el ámbito de aplicación de esta ley.","No tienen carácter de subvenciones.","Quedan excluidos del ámbito de aplicación de esta ley."],"bloque":"subv-general","precepto":"art. 4.c","correcta":3,"justificaciones":["No: las subvenciones de la ley de financiación de partidos están excluidas.","No: la fórmula adecuada es la de exclusión.","No: no se califican como “no subvenciones” sino como excluidas.","Correcta: quedan excluidas las subvenciones de la LO 3/1987 de financiación de partidos políticos (art. 4.c)."]},{"id":"pr-55-008","origen":"practicas","test":"Ejercicio 23.- Ámbito de aplicación.","n":8,"enunciado":"El estado da una ayuda económica de emergencia o urgencia social a través de los servicios sociales, destinada a cubrir necesidades básicas de la ciudadanía.","opciones":["Sí, se le aplicará la 38/2003.","No están comprendidas en el ámbito de aplicación de esta ley.","No tienen carácter de subvenciones.","Quedan excluidos del ámbito de aplicación de esta ley."],"bloque":"subv-general","precepto":"art. 2.4.j","correcta":2,"justificaciones":["No: las ayudas de emergencia social no son subvenciones.","No: la fórmula del art. 2.4 es “no tienen carácter de subvenciones”.","Correcta: las ayudas de emergencia o urgencia social gestionadas por servicios sociales no tienen carácter de subvención (art. 2.4.j).","No: no figura en las exclusiones del art. 4."],"ojo":"La letra j) se añadió al art. 2.4 por la Ley 4/2026, de 1 de octubre, en vigor desde el 23 de octubre de 2026."},{"id":"pr-55-009","origen":"practicas","test":"Ejercicio 23.- Ámbito de aplicación.","n":9,"enunciado":"La Administración concede un premio económico en un concurso de fotografía al que los participantes se han presentado voluntariamente.","opciones":["Sí, se le aplicará la 38/2003.","No están comprendidas en el ámbito de aplicación de esta ley.","No tienen carácter de subvenciones.","Quedan excluidos del ámbito de aplicación de esta ley."],"bloque":"subv-general","precepto":"art. 2.1 y 4.a","correcta":0,"justificaciones":["Correcta: el premio se otorga a quien se presenta voluntariamente, es decir, con solicitud previa, así que no está excluido y se rige por la ley.","No: el único premio excluido es el otorgado sin solicitud previa.","No: sí tiene carácter de subvención.","No: no encaja en el art. 4.a, porque hay solicitud."]},{"id":"pr-55-010","origen":"practicas","test":"Ejercicio 23.- Ámbito de aplicación.","n":10,"enunciado":"La AGE hace una aportación dineraria a la Junta de Castilla y León para financiar globalmente una actividad.","opciones":["Sí, se le aplicará la 38/2003.","No están comprendidas en el ámbito de aplicación de esta ley.","No tienen carácter de subvenciones.","Quedan excluidos del ámbito de aplicación de esta ley."],"bloque":"subv-general","precepto":"art. 2.2","correcta":1,"justificaciones":["No: es la aportación global entre Administraciones, que la ley deja fuera.","Correcta: aportaciones entre Administraciones para financiar globalmente una actividad no están comprendidas (art. 2.2).","No: la fórmula del art. 2.2 es “no están comprendidas”.","No: el art. 4 no recoge este supuesto."]},{"id":"pr-56-001","origen":"practicas","test":"Ejercicio 24.- Titulo Preliminar","n":1,"enunciado":"Señale la respuesta incorrecta:","opciones":["Las subvenciones que se otorguen por consorcios, mancomunidades u otras personificaciones públicas creadas por varias Administraciones públicas se regularán de acuerdo con lo establecido en el instrumento jurídico de creación.","Las subvenciones se regirán por la Ley de Subvenciones 38/2003, por derecho privado y supletoriamente por derecho administrativo."],"bloque":"subv-general","precepto":"art. 5","correcta":1,"justificaciones":["Es correcta: las subvenciones de consorcios y mancomunidades se rigen por su instrumento de creación (art. 5.2).","Es la incorrecta: el régimen es esta ley y su desarrollo, las demás normas de derecho administrativo y, en su defecto, el derecho privado (art. 5.1)."],"ojo":"La opción incorrecta invierte el orden de normas aplicables."},{"id":"pr-56-002","origen":"practicas","test":"Ejercicio 24.- Titulo Preliminar","n":2,"enunciado":"Señale la respuesta incorrecta:","opciones":["Las subvenciones financiadas con cargo a fondos de la Unión Europea se regirán exclusivamente por la normativa Española.","Las subvenciones financiadas con cargo a fondos de la Unión Europea se regirán por las normas comunitarias aplicables en cada caso y por las normas nacionales de desarrollo o transposición de aquéllas"],"bloque":"subv-general","precepto":"art. 6","correcta":0,"justificaciones":["Es la incorrecta: las subvenciones con fondos de la UE se rigen por las normas comunitarias y las nacionales de desarrollo, no exclusivamente por la normativa española (art. 6.1).","Es correcta: se rigen por las normas comunitarias aplicables y las nacionales de desarrollo o transposición (art. 6.1)."]},{"id":"pr-56-003","origen":"practicas","test":"Ejercicio 24.- Titulo Preliminar","n":3,"enunciado":"Señale la respuesta correcta:","opciones":["La gestión de las subvenciones se realizará de acuerdo con los siguientes principios: Publicidad, transparencia, concurrencia, objetividad, igualdad y no discriminación, eficacia y eficiencia.","La gestión de las subvenciones se realizará de acuerdo con los siguientes principios: Participación ciudadana, transparencia, solidaridad, objetividad, coordinación, solvencia y eficiencia."],"bloque":"subv-general","precepto":"art. 8.3","correcta":0,"justificaciones":["Correcta: son los principios del art. 8.3: publicidad, transparencia, concurrencia, objetividad, igualdad y no discriminación, eficacia y eficiencia.","Falsa: participación ciudadana, solidaridad, coordinación o solvencia no figuran entre los principios del art. 8.3."]},{"id":"pr-56-004","origen":"practicas","test":"Ejercicio 24.- Titulo Preliminar","n":4,"enunciado":"Señale la respuesta incorrecta:","opciones":["Se aprobará un plan estratégico para cada Administración, que abarcará las subvenciones de sus organismos y demás entes públicos a él vinculados.","Los planes estratégicos contendrán previsiones para un periodo de vigencia de tres años, salvo que por la especial naturaleza del sector afectado, sea conveniente establecer un plan estratégico de duración diferente."],"bloque":"subv-general","precepto":"art. 8.1 LGS y arts. 10 y 11 del Reglamento","correcta":0,"justificaciones":["Es la incorrecta: el plan estratégico lo aprueba cada departamento ministerial para sus subvenciones y las de sus organismos vinculados, no uno por cada Administración.","Es correcta: los planes prevén un período de tres años, salvo que la naturaleza del sector aconseje otro (art. 11.4 del Reglamento)."],"revisar":"El detalle del plan por departamento viene del Reglamento (RD 887/2006), que he comprobado por web y no en el texto de la LGS."},{"id":"pr-56-005","origen":"practicas","test":"Ejercicio 24.- Titulo Preliminar","n":5,"enunciado":"Señale la respuesta correcta:","opciones":["Se realiza un seguimiento anual del plan estratégico de subvenciones correspondiente y para ello cada Departamento ministerial emitirá antes del 31 de octubre de cada año un informe sobre el grado de avance de la aplicación del plan, sus efectos y las repercusiones.","Los planes estratégicos de subvenciones se aprueban por el Ministro responsable de su ejecución y se remitirán a la Secretaría de Estado de Hacienda y Presupuestos y a las Cortes Generales para su conocimiento."],"bloque":"subv-general","precepto":"arts. 13 y 14 del Reglamento","correcta":1,"justificaciones":["Falsa: el informe de seguimiento se emite antes del 30 de abril de cada año, no del 31 de octubre (art. 14.2 del Reglamento).","Correcta: los planes los aprueban los Ministros responsables y se remiten a la Secretaría de Estado de Hacienda y Presupuestos y a las Cortes Generales (art. 13 del Reglamento)."],"revisar":"Datos del Reglamento (RD 887/2006), comprobados por web; conviene confirmarlos en el BOE."},{"id":"pr-56-006","origen":"practicas","test":"Ejercicio 24.- Titulo Preliminar","n":6,"enunciado":"Señale la respuesta correcta:","opciones":["Con carácter previo al otorgamiento de las subvenciones, deberán aprobarse las normas que establezcan las bases reguladoras de concesión, un extracto de la misma se publicará en el Boletín Oficial del Estado.","Un requisito previo al otorgamiento de una subvención será la aprobación del gasto por el órgano competente para ello."],"bloque":"subv-general","precepto":"art. 9.2, 9.3 y 9.4.e","correcta":1,"justificaciones":["Falsa: lo que se publica en el BOE son las propias bases reguladoras (art. 9.3), y el extracto lo es de la convocatoria (art. 23.2).","Correcta: la aprobación del gasto por el órgano competente es uno de los requisitos para otorgar la subvención (art. 9.4.e)."]},{"id":"pr-56-007","origen":"practicas","test":"Ejercicio 24.- Titulo Preliminar","n":7,"enunciado":"Señale la respuesta incorrecta:","opciones":["En los organismos y entidades de derecho público vinculadas o dependientes de la Administración General del Estado serán competentes para otorgar subvenciones los Presidentes o directores.","La concesión de subvenciones de cuantía superior a 12 millones de euros será competencia del Consejo de Ministros."],"bloque":"subv-general","precepto":"art. 10.1 y 10.2","correcta":1,"justificaciones":["Es correcta: los presidentes o directores de organismos y entidades públicas dependientes de la AGE son competentes para conceder (art. 10.1).","Es la incorrecta: la concesión de más de 12 millones requiere la previa autorización del Consejo de Ministros, pero no es competencia suya (art. 10.2)."]},{"id":"pr-56-008","origen":"practicas","test":"Ejercicio 24.- Titulo Preliminar","n":8,"enunciado":"Señale la respuesta correcta:","opciones":["Las competencia para conceder subvenciones, llevará aparejada la de aprobar el gasto correspondiente.","Las facultades para conceder subvenciones, podrán ser objeto de desconcentración mediante real decreto acordado en Consejo de Ministros."],"bloque":"subv-general","precepto":"art. 10.3","correcta":1,"justificaciones":["Falsa: la competencia para conceder no lleva aparejada la de aprobar el gasto; la aprobación del gasto es un requisito distinto (arts. 9.4.e y 10.2).","Correcta: las facultades de conceder pueden desconcentrarse por real decreto acordado en Consejo de Ministros (art. 10.3)."]},{"id":"pr-56-009","origen":"practicas","test":"Ejercicio 24.- Titulo Preliminar","n":9,"enunciado":"Señale la respuesta incorrecta:","opciones":["Las agrupaciones de personas físicas o jurídicas, públicas o privadas siempre pueden ser beneficiarios de una subvención.","Cuando el beneficiario sea una agrupación de personas físicas o jurídicas, públicas o privadas sin personalidad jurídica deberá nombrarse un representante."],"bloque":"subv-general","precepto":"art. 11.3","correcta":0,"justificaciones":["Es la incorrecta: las agrupaciones solo pueden ser beneficiarias cuando lo prevean expresamente las bases reguladoras.","Es correcta: una agrupación sin personalidad jurídica debe nombrar un representante o apoderado único (art. 11.3)."]},{"id":"pr-56-010","origen":"practicas","test":"Ejercicio 24.- Titulo Preliminar","n":10,"enunciado":"Señale la respuesta incorrecta:","opciones":["Podrán actuar como entidades colaboradoras las comunidades autónomas y las corporaciones locales respecto de las subvenciones concedidas por la Administración General del Estado.","Para ser entidad colaboradora de una subvención deberá estar inscrita como tal en la Base de Datos nacional de Subvenciones."],"bloque":"subv-general","precepto":"arts. 12.3 y 20","correcta":1,"justificaciones":["Es correcta: comunidades autónomas y corporaciones locales pueden ser entidades colaboradoras de las subvenciones de la AGE (art. 12.3).","Es la incorrecta: la ley no exige estar inscrita en la BDNS para ser entidad colaboradora."]},{"id":"pr-56-011","origen":"practicas","test":"Ejercicio 24.- Titulo Preliminar","n":11,"enunciado":"Señale la respuesta correcta:","opciones":["No podrán obtener la condición de beneficiario o entidad colaboradora los que tengan la residencia fiscal en un país o territorio calificado como extranjero.","No hallarse al corriente en el cumplimiento de las obligaciones tributarias o frente a la Seguridad Social es motivo de prohibición para obtener la condición de beneficiario en materia de subvenciones."],"bloque":"subv-general","precepto":"art. 13.2","correcta":1,"justificaciones":["Falsa: la prohibición es por residencia fiscal en un paraíso fiscal, no en cualquier país extranjero (art. 13.2.f).","Correcta: no estar al corriente de obligaciones tributarias o con la Seguridad Social impide ser beneficiario (art. 13.2.e)."]},{"id":"pr-56-012","origen":"practicas","test":"Ejercicio 24.- Titulo Preliminar","n":12,"enunciado":"Señale la respuesta correcta:","opciones":["Podrá justificarse mediante testimonio judicial el no estar incursos en las prohibiciones para obtener la condición de beneficiario.","No podrá ser entidad colaboradora de una subvención quien haya sido sancionado mediante resolución con la pérdida de la posibilidad de obtener subvenciones."],"bloque":"subv-general","precepto":"art. 13.7 y 13.2.h","correcta":0,"justificaciones":["Correcta: la ausencia de prohibiciones puede justificarse mediante testimonio judicial, certificados telemáticos o certificación administrativa (art. 13.7).","Falsa tal como está: la prohibición del art. 13.2.h exige resolución firme, y el enunciado omite ese requisito."],"ojo":"La segunda opción parece cierta, pero le falta “firme”. La primera es literal del art. 13.7.","revisar":"Respuesta elegida por ser literal; la segunda opción es casi idéntica al art. 13.2.h."},{"id":"pr-56-013","origen":"practicas","test":"Ejercicio 24.- Titulo Preliminar","n":13,"enunciado":"Señale la respuesta incorrecta:","opciones":["Una de las obligaciones de los beneficiarios será comunicar al órgano concedente la obtención de otras subvenciones con distinta finalidad.","Será obligación del beneficiario acreditar con anterioridad a dictarse la propuesta de resolución de concesión que se halla al corriente en el cumplimiento de sus obligaciones tributarias y frente a la Seguridad Social."],"bloque":"subv-general","precepto":"art. 14.1.d y 14.1.e","correcta":0,"justificaciones":["Es la incorrecta: la comunicación obligatoria se refiere a otras ayudas que financien las mismas actividades subvencionadas, no a las de distinta finalidad (art. 14.1.d).","Es correcta: hay que acreditar, antes de la propuesta de resolución de concesión, estar al corriente con Hacienda y Seguridad Social (art. 14.1.e)."]},{"id":"pr-56-014","origen":"practicas","test":"Ejercicio 24.- Titulo Preliminar","n":14,"enunciado":"Señale la respuesta correcta:","opciones":["Justificar la entrega de los fondos percibidos ante el órgano concedente de la subvención será una de las obligaciones que se le exige a las entidades colaboradoras.","Las entidades colaboradoras tendrán como obligación establecida en la ley de subvenciones el cumplimiento del objetivo que fundamenta la concesión de dicha subvención."],"bloque":"subv-general","precepto":"art. 15.1","correcta":0,"justificaciones":["Correcta: justificar la entrega de los fondos ante el órgano concedente es obligación de la entidad colaboradora (art. 15.1.c).","Falsa: cumplir el objetivo que fundamenta la concesión es obligación del beneficiario (art. 14.1.a)."]},{"id":"pr-56-015","origen":"practicas","test":"Ejercicio 24.- Titulo Preliminar","n":15,"enunciado":"Señale la respuesta correcta:","opciones":["Los convenios de colaboración con las entidades colaboradoras incluidas las prórrogas no podrán exceder de seis años.","Para poder prorrogar un convenio de colaboración será necesaria la autorización por escrito del órgano concedente."],"bloque":"subv-general","precepto":"art. 16.2","correcta":0,"justificaciones":["Correcta: el convenio dura como máximo cuatro años y, con prórrogas, no puede pasar de seis (art. 16.2).","Falsa: la prórroga se acuerda por mutuo acuerdo de las partes antes de que acabe el convenio, no por una autorización escrita del órgano (art. 16.2)."]},{"id":"pr-56-016","origen":"practicas","test":"Ejercicio 24.- Titulo Preliminar","n":16,"enunciado":"Señale la respuesta incorrecta:","opciones":["Las bases reguladoras deberán ser aprobadas por Acuerdo de Consejo de Ministros.","En las bases reguladoras de una subvención figurara los criterios objetivos de otorgamiento de la subvención y ponderación de los mismos."],"bloque":"subv-general","precepto":"art. 17.1","correcta":0,"justificaciones":["Es la incorrecta: en la AGE las bases se aprueban por orden ministerial, no por acuerdo del Consejo de Ministros.","Es correcta: las bases fijan los criterios objetivos de otorgamiento y su ponderación (art. 17.3.e)."]},{"id":"pr-56-017","origen":"practicas","test":"Ejercicio 24.- Titulo Preliminar","n":17,"enunciado":"Señale la respuesta correcta:","opciones":["La Base de Datos Nacional de Subvenciones suministrará información pública sobre las sanciones firmes impuestas por infracciones graves y muy graves.","La BDNS operará como sistema nacional de publicidad de las subvenciones."],"bloque":"subv-general","precepto":"arts. 18.1, 20.8 y 20.9","correcta":1,"justificaciones":["Falsa: la BDNS puede dar información pública sobre sanciones firmes por infracciones muy graves, no por graves y muy graves (art. 20.9).","Correcta: la BDNS opera como sistema nacional de publicidad de subvenciones (art. 18.1)."]},{"id":"pr-56-018","origen":"practicas","test":"Ejercicio 24.- Titulo Preliminar","n":18,"enunciado":"Señale la respuesta incorrecta:","opciones":["El importe de las subvenciones en ningún caso podrá superar el coste de la actividad subvencionada.","En ningún caso podrá percibirse otra subvenciones para la misma finalidad."],"bloque":"subv-general","precepto":"art. 19.2 y 19.3","correcta":1,"justificaciones":["Es correcta: el importe no puede superar el coste de la actividad subvencionada (art. 19.3).","Es la incorrecta: la compatibilidad con otras subvenciones para la misma finalidad la regula la normativa reguladora, y no está prohibida en todo caso (art. 19.2)."]},{"id":"pr-56-019","origen":"practicas","test":"Ejercicio 24.- Titulo Preliminar","n":19,"enunciado":"Señale la respuesta incorrecta:","opciones":["El tribunal de cuentas es el órgano responsable de la administración y custodia de la Base de Datos Nacional de Subvenciones.","Las administraciones concedentes deberán remitir a la BDNS información sobre las convocatorias de subvenciones y las resoluciones de concesión recaídas."],"bloque":"subv-general","precepto":"art. 20.3","correcta":0,"justificaciones":["Es la incorrecta: la responsable de administrar y custodiar la BDNS es la Intervención General de la Administración del Estado, no el Tribunal de Cuentas.","Es correcta: las administraciones concedentes remiten a la BDNS las convocatorias y las resoluciones de concesión (art. 18.2)."]},{"id":"pr-56-020","origen":"practicas","test":"Ejercicio 24.- Titulo Preliminar","n":20,"enunciado":"Señale la respuesta incorrecta:","opciones":["Las entidades colaboradoras deberán dar publicidad de las subvenciones y ayudas percibidas.","No serán publicadas las subvenciones concedidas cuando la publicación de los datos del beneficiario pueda ser contrario al respeto y salvaguarda del honor, a la intimidad personal o familiar de las personas físicas y así haya sido previsto en su normativa reguladora."],"bloque":"subv-general","precepto":"art. 18.3","correcta":0,"justificaciones":["Es la incorrecta: quien debe dar publicidad de las subvenciones percibidas son los beneficiarios, no las entidades colaboradoras (art. 18.3).","Es correcta: la publicidad se limita cuando afecta al honor o la intimidad de personas físicas y así lo prevé su normativa reguladora."],"revisar":"La segunda opción reproduce una regla de publicidad que no he podido localizar literal en la LGS; se elige la primera por ser claramente falsa."},{"id":"pr-57-001","origen":"practicas","test":"Ejercicio 25.- Titulo I. Verdadero o Falso","n":1,"enunciado":"El procedimiento ordinario de concesión de subvenciones se tramitará en régimen de concurrencia competitiva.","opciones":["VERDADERO.","FALSO."],"bloque":"subv-concesion","precepto":"art. 22.1","correcta":0,"justificaciones":["Correcta: el procedimiento ordinario de concesión es la concurrencia competitiva, que compara las solicitudes y las ordena por los criterios de las bases.","Incorrecta: lo contrario es lo que dice el art. 22.1."]},{"id":"pr-57-002","origen":"practicas","test":"Ejercicio 25.- Titulo I. Verdadero o Falso","n":2,"enunciado":"Excepcionalmente, cuando así lo prevean las bases reguladoras, el órgano competente procederá al prorrateo entre los beneficiarios del importe global máximo destinado a las subvenciones.","opciones":["VERDADERO.","FALSO."],"bloque":"subv-concesion","precepto":"art. 22.1","correcta":0,"justificaciones":["Correcta: excepcionalmente, si lo prevén las bases, se prorratea el importe global máximo entre los beneficiarios.","Incorrecta: lo contrario es lo que dice el art. 22.1."]},{"id":"pr-57-003","origen":"practicas","test":"Ejercicio 25.- Titulo I. Verdadero o Falso","n":3,"enunciado":"Podrá concederse de forma directa subvenciones cuyo otorgamiento o cuantía venga reglamentariamente impuesto a la Administración.","opciones":["VERDADERO.","FALSO."],"bloque":"subv-concesion","precepto":"art. 22.2.b","correcta":1,"justificaciones":["Incorrecta: lo contrario es lo que dice el art. 22.2.b.","Correcta: la concesión directa por otorgamiento o cuantía impuestos exige una norma de rango legal, no basta una reglamentaria."]},{"id":"pr-57-004","origen":"practicas","test":"Ejercicio 25.- Titulo I. Verdadero o Falso","n":4,"enunciado":"Las convocatorias de las subvenciones deberán indicar necesariamente si la resolución pone fin a la vía administrativa y, en caso contrario, órgano ante el que ha de interponerse recurso de alzada.","opciones":["VERDADERO.","FALSO."],"bloque":"subv-concesion","precepto":"art. 23.2.k","correcta":0,"justificaciones":["Correcta: la convocatoria indica si la resolución agota la vía administrativa y, si no, ante qué órgano se interpone el recurso de alzada.","Incorrecta: lo contrario es lo que dice el art. 23.2.k."]},{"id":"pr-57-005","origen":"practicas","test":"Ejercicio 25.- Titulo I. Verdadero o Falso","n":5,"enunciado":"La presentación de la solicitud por parte del beneficiario conllevará la autorización al órgano gestor para recabar los certificados a emitir por la Agencia Estatal de Administración Tributaria (AEAT) y por la Tesorería General de la Seguridad Social (TGSS).","opciones":["VERDADERO.","FALSO."],"bloque":"subv-concesion","precepto":"art. 23.3","correcta":0,"justificaciones":["Correcta: presentar la solicitud implica autorizar al órgano gestor a recabar los certificados de la AEAT y de la Tesorería General de la Seguridad Social.","Incorrecta: lo contrario es lo que dice el art. 23.3."]},{"id":"pr-57-006","origen":"practicas","test":"Ejercicio 25.- Titulo I. Verdadero o Falso","n":6,"enunciado":"Si en un procedimiento de concurrencia competitiva la solicitud no reúne los requisitos establecidos en la norma de convocatoria, el órgano competente requerirá al interesado para que la subsane en el plazo máximo e improrrogable de 15 días.","opciones":["VERDADERO.","FALSO."],"bloque":"subv-concesion","precepto":"art. 23.5","correcta":1,"justificaciones":["Incorrecta: lo contrario es lo que dice el art. 23.5.","Correcta: el plazo de subsanación es de 10 días improrrogables, no de 15."]},{"id":"pr-57-007","origen":"practicas","test":"Ejercicio 25.- Titulo I. Verdadero o Falso","n":7,"enunciado":"La convocatoria de una subvención deberá publicarse en el BOE y un extracto de la misma en la BDNS.","opciones":["VERDADERO.","FALSO."],"bloque":"subv-concesion","precepto":"art. 23.2","correcta":1,"justificaciones":["Incorrecta: lo contrario es lo que dice el art. 23.2.","Correcta: la convocatoria se publica en la BDNS y su extracto en el BOE, al revés de lo que dice el enunciado."]},{"id":"pr-57-008","origen":"practicas","test":"Ejercicio 25.- Titulo I. Verdadero o Falso","n":8,"enunciado":"La instrucción del procedimiento de concesión de subvenciones en régimen de concurrencia competitiva corresponde al órgano concedente.","opciones":["VERDADERO.","FALSO."],"bloque":"subv-concesion","precepto":"art. 24.1","correcta":1,"justificaciones":["Incorrecta: lo contrario es lo que dice el art. 24.1.","Correcta: la instrucción corresponde al órgano que designe la convocatoria, no necesariamente al concedente."]},{"id":"pr-57-009","origen":"practicas","test":"Ejercicio 25.- Titulo I. Verdadero o Falso","n":9,"enunciado":"La propuesta de resolución definitiva en un procedimiento de concurrencia competitiva se notificará a los interesados que hayan sido propuestos como beneficiarios, para que en el plazo previsto en dicha normativa comuniquen su aceptación.","opciones":["VERDADERO.","FALSO."],"bloque":"subv-concesion","precepto":"art. 24.5","correcta":0,"justificaciones":["Correcta: la propuesta de resolución definitiva se notifica a los propuestos como beneficiarios para que comuniquen su aceptación, cuando proceda según las bases.","Incorrecta: lo contrario es lo que dice el art. 24.5."]},{"id":"pr-57-010","origen":"practicas","test":"Ejercicio 25.- Titulo I. Verdadero o Falso","n":10,"enunciado":"Las propuestas de resolución provisional y definitiva no crean derecho alguno a favor del beneficiario propuesto, frente a la Administración, mientras no se le haya notificado la resolución de concesión.","opciones":["VERDADERO.","FALSO."],"bloque":"subv-concesion","precepto":"art. 24.6","correcta":0,"justificaciones":["Correcta: las propuestas provisional y definitiva no crean derecho alguno hasta la notificación de la resolución de concesión.","Incorrecta: lo contrario es lo que dice el art. 24.6."]},{"id":"pr-57-011","origen":"practicas","test":"Ejercicio 25.- Titulo I. Verdadero o Falso","n":11,"enunciado":"La resolución de un procedimiento de concurrencia competitiva, además de contener la relación de solicitantes a los que se concede la subvención, hará constar, en su caso, de manera expresa, la desestimación del resto de las solicitudes.","opciones":["VERDADERO.","FALSO."],"bloque":"subv-concesion","precepto":"art. 25.3","correcta":0,"justificaciones":["Correcta: la resolución incluye a los solicitantes a los que se concede y hace constar de forma expresa la desestimación del resto.","Incorrecta: lo contrario es lo que dice el art. 25.3."]},{"id":"pr-57-012","origen":"practicas","test":"Ejercicio 25.- Titulo I. Verdadero o Falso","n":12,"enunciado":"El plazo para resolver un procedimiento en régimen de concurrencia competitiva será un máximo de 6 meses a contar desde el día siguiente en que el interesado presenta su solicitud.","opciones":["VERDADERO.","FALSO."],"bloque":"subv-concesion","precepto":"art. 25.4","correcta":1,"justificaciones":["Incorrecta: lo contrario es lo que dice el art. 25.4.","Correcta: el plazo máximo de seis meses se cuenta desde la publicación de la convocatoria, no desde que el interesado presenta su solicitud."]},{"id":"pr-57-013","origen":"practicas","test":"Ejercicio 25.- Titulo I. Verdadero o Falso","n":13,"enunciado":"Cuando el importe de la propuesta de resolución provisional sea inferior al solicitado, si así se ha previsto en las bases reguladoras se podrá instar del beneficiario la reformulación de su solicitud.","opciones":["VERDADERO.","FALSO."],"bloque":"subv-concesion","precepto":"art. 27.1","correcta":0,"justificaciones":["Correcta: si la propuesta provisional es inferior a lo solicitado y las bases lo prevén, se puede pedir la reformulación de la solicitud.","Incorrecta: lo contrario es lo que dice el art. 27.1."]},{"id":"pr-57-014","origen":"practicas","test":"Ejercicio 25.- Titulo I. Verdadero o Falso","n":14,"enunciado":"Los contratos serán el instrumento habitual para canalizar las subvenciones previstas nominativamente en los Presupuestos Generales del Estado.","opciones":["VERDADERO.","FALSO."],"bloque":"subv-concesion","precepto":"art. 28.1","correcta":1,"justificaciones":["Incorrecta: lo contrario es lo que dice el art. 28.1.","Correcta: el instrumento habitual para las subvenciones nominativas son los convenios, no los contratos."]},{"id":"pr-57-015","origen":"practicas","test":"Ejercicio 25.- Titulo I. Verdadero o Falso","n":15,"enunciado":"El beneficiario únicamente podrá subcontratar la actividad subvencionada parcialmente y solo cuando la normativa reguladora de la subvención así lo prevea.","opciones":["VERDADERO.","FALSO."],"bloque":"subv-concesion","precepto":"art. 29.2","correcta":1,"justificaciones":["Incorrecta: lo contrario es lo que dice el art. 29.2.","Correcta: el beneficiario puede subcontratar total o parcialmente cuando la normativa reguladora lo prevea; el enunciado limita a lo parcial."]},{"id":"pr-57-016","origen":"practicas","test":"Ejercicio 25.- Titulo I. Verdadero o Falso","n":16,"enunciado":"Los contratistas quedarán obligados sólo ante el beneficiario, que asumirá la total responsabilidad de la ejecución de la actividad subvencionada frente a la Administración.","opciones":["VERDADERO.","FALSO."],"bloque":"subv-concesion","precepto":"art. 29.5","correcta":0,"justificaciones":["Correcta: los contratistas quedan obligados solo ante el beneficiario, que asume la total responsabilidad frente a la Administración.","Incorrecta: lo contrario es lo que dice el art. 29.5."]},{"id":"pr-57-017","origen":"practicas","test":"Ejercicio 25.- Titulo I. Verdadero o Falso","n":17,"enunciado":"Si viene establecido en las bases reguladoras podrá concertarse por el beneficiario la ejecución total o parcial de las actividades subvencionadas con personas o entidades, aunque estén incursas en alguna de las prohibiciones del artículo 13 de esta ley.","opciones":["VERDADERO.","FALSO."],"bloque":"subv-concesion","precepto":"art. 29.7.a","correcta":1,"justificaciones":["Incorrecta: lo contrario es lo que dice el art. 29.7.a.","Correcta: en ningún caso se puede subcontratar con personas incursas en las prohibiciones del art. 13, aunque lo prevean las bases."]},{"id":"pr-57-018","origen":"practicas","test":"Ejercicio 25.- Titulo I. Verdadero o Falso","n":18,"enunciado":"Cuando las actividades hayan sido financiadas, además de con la subvención, con fondos propios u otras subvenciones o recursos, deberá acreditarse en la justificación el importe, procedencia y aplicación de tales fondos a las actividades subvencionadas.","opciones":["VERDADERO.","FALSO."],"bloque":"subv-concesion","precepto":"art. 30.4","correcta":0,"justificaciones":["Correcta: si hubo fondos propios u otras ayudas, hay que acreditar en la justificación su importe, procedencia y aplicación.","Incorrecta: lo contrario es lo que dice el art. 30.4."]},{"id":"pr-57-019","origen":"practicas","test":"Ejercicio 25.- Titulo I. Verdadero o Falso","n":19,"enunciado":"En ningún caso serán gastos subvencionables los tributos abonados efectivamente por el beneficiario.","opciones":["VERDADERO.","FALSO."],"bloque":"subv-concesion","precepto":"art. 31.8","correcta":1,"justificaciones":["Incorrecta: lo contrario es lo que dice el art. 31.8.","Correcta: los tributos sí son gasto subvencionable cuando el beneficiario los abona efectivamente; no lo son los impuestos recuperables ni los personales sobre la renta."]},{"id":"pr-57-020","origen":"practicas","test":"Ejercicio 25.- Titulo I. Verdadero o Falso","n":20,"enunciado":"Cuando el importe del gasto subvencionable supere las cuantías establecidas para el contrato menor el beneficiario deberá solicitar como mínimo tres ofertas de diferentes proveedores, con carácter previo a la contracción del compromiso.","opciones":["VERDADERO.","FALSO."],"bloque":"subv-concesion","precepto":"art. 31.3","correcta":0,"justificaciones":["Correcta: si el gasto supera la cuantía del contrato menor, el beneficiario pide como mínimo tres ofertas antes de comprometer el gasto.","Incorrecta: lo contrario es lo que dice el art. 31.3."]},{"id":"pr-58-001","origen":"practicas","test":"Ejercicio 26.- Infracciones","n":1,"enunciado":"El incumplimiento de las condiciones establecidas alterando sustancialmente los fines para los que la subvención fue concedida.","opciones":["Leve.","Grave.","Muy Grave."],"bloque":"subv-sanciones","precepto":"art. 57.b","correcta":1,"justificaciones":["No: esta conducta es una infracción grave según el art. 57.b.","Correcta: alterar sustancialmente los fines de la subvención incumpliendo sus condiciones es infracción grave.","No: esta conducta es una infracción grave según el art. 57.b."]},{"id":"pr-58-002","origen":"practicas","test":"Ejercicio 26.- Infracciones","n":2,"enunciado":"El incumplimiento de obligaciones de índole contable o registral.","opciones":["Leve.","Grave.","Muy Grave."],"bloque":"subv-sanciones","precepto":"art. 56.d","correcta":0,"justificaciones":["Correcta: los incumplimientos de índole contable o registral son infracciones leves.","No: esta conducta es una infracción leve según el art. 56.d.","No: esta conducta es una infracción leve según el art. 56.d."]},{"id":"pr-58-003","origen":"practicas","test":"Ejercicio 26.- Infracciones","n":3,"enunciado":"La presentación fuera de plazo de las cuentas justificativas de la aplicación dada a los fondos percibidos, así como su presentación inexacta o incompleta.","opciones":["Leve.","Grave.","Muy Grave."],"bloque":"subv-sanciones","precepto":"art. 56.a y 56.b","correcta":0,"justificaciones":["Correcta: presentar fuera de plazo o de forma inexacta o incompleta las cuentas justificativas es infracción leve.","No: esta conducta es una infracción leve según el art. 56.a y 56.b.","No: esta conducta es una infracción leve según el art. 56.a y 56.b."]},{"id":"pr-58-004","origen":"practicas","test":"Ejercicio 26.- Infracciones","n":4,"enunciado":"La no aplicación, en todo o en parte, de las cantidades recibidas a los fines para los que la subvención fue concedida.","opciones":["Leve.","Grave.","Muy Grave."],"bloque":"subv-sanciones","precepto":"art. 58.b","correcta":2,"justificaciones":["No: esta conducta es una infracción muy grave según el art. 58.b.","No: esta conducta es una infracción muy grave según el art. 58.b.","Correcta: no aplicar, total o parcialmente, las cantidades recibidas a los fines de la subvención es infracción muy grave."]},{"id":"pr-58-005","origen":"practicas","test":"Ejercicio 26.- Infracciones","n":5,"enunciado":"El incumplimiento por parte de la entidad colaboradora de la obligación de verificar, en su caso, el cumplimiento y efectividad de las condiciones o requisitos determinantes para el otorgamiento de las subvenciones, cuando de ello se derive la obligación de reintegro","opciones":["Leve.","Grave.","Muy Grave."],"bloque":"subv-sanciones","precepto":"art. 57.e","correcta":1,"justificaciones":["No: esta conducta es una infracción grave según el art. 57.e.","Correcta: que la entidad colaboradora no verifique las condiciones, cuando de ello se derive reintegro, es infracción grave.","No: esta conducta es una infracción grave según el art. 57.e."]},{"id":"pr-58-006","origen":"practicas","test":"Ejercicio 26.- Infracciones","n":6,"enunciado":"La resistencia, excusa, obstrucción o negativa a las actuaciones de control, cuando de ello se derive la imposibilidad de verificar el empleo dado a los fondos percibidos.","opciones":["Leve.","Grave.","Muy Grave."],"bloque":"subv-sanciones","precepto":"art. 58.c","correcta":2,"justificaciones":["No: esta conducta es una infracción muy grave según el art. 58.c.","No: esta conducta es una infracción muy grave según el art. 58.c.","Correcta: la resistencia al control que impide verificar el empleo de los fondos es infracción muy grave."]},{"id":"pr-58-007","origen":"practicas","test":"Ejercicio 26.- Infracciones","n":7,"enunciado":"La obtención de la condición de entidad colaboradora falseando los requisitos requeridos en las bases reguladoras de la subvención u ocultando los que la hubiesen impedido.","opciones":["Leve.","Grave.","Muy Grave."],"bloque":"subv-sanciones","precepto":"art. 57.d","correcta":1,"justificaciones":["No: esta conducta es una infracción grave según el art. 57.d.","Correcta: obtener la condición de entidad colaboradora falseando los requisitos es infracción grave.","No: esta conducta es una infracción grave según el art. 57.d."]},{"id":"pr-58-008","origen":"practicas","test":"Ejercicio 26.- Infracciones","n":8,"enunciado":"La falta de suministro de información por parte de las administraciones, organismos y demás entidades obligadas a suministrar información a la Base de Datos Nacional de Subvenciones (BDNS).","opciones":["Leve.","Grave.","Muy Grave."],"bloque":"subv-sanciones","precepto":"art. 57.f","correcta":1,"justificaciones":["No: esta conducta es una infracción grave según el art. 57.f.","Correcta: no suministrar información a la BDNS es infracción grave.","No: esta conducta es una infracción grave según el art. 57.f."]},{"id":"pr-58-009","origen":"practicas","test":"Ejercicio 26.- Infracciones","n":9,"enunciado":"La obtención de una subvención falseando las condiciones requeridas para su concesión u ocultando las que la hubiesen impedido o limitado.","opciones":["Leve.","Grave.","Muy Grave."],"bloque":"subv-sanciones","precepto":"art. 58.a","correcta":2,"justificaciones":["No: esta conducta es una infracción muy grave según el art. 58.a.","No: esta conducta es una infracción muy grave según el art. 58.a.","Correcta: obtener una subvención falseando las condiciones o ocultando las que lo impedían es infracción muy grave."]},{"id":"pr-58-010","origen":"practicas","test":"Ejercicio 26.- Infracciones","n":10,"enunciado":"La falta de justificación del empleo dado a los fondos recibidos una vez transcurrido el plazo establecido para su presentación.","opciones":["Leve.","Grave.","Muy Grave."],"bloque":"subv-sanciones","precepto":"art. 57.c","correcta":1,"justificaciones":["No: esta conducta es una infracción grave según el art. 57.c.","Correcta: no justificar el empleo de los fondos una vez vencido el plazo es infracción grave.","No: esta conducta es una infracción grave según el art. 57.c."]},{"id":"pr-59-001","origen":"practicas","test":"Ejercicio 27.- Subvenciones en números","n":1,"enunciado":"Los planes estratégicos contendrán previsiones para un periodo de vigencia de:","opciones":["1 año.","6 meses.","4 años.","3 años."],"bloque":"subv-general","precepto":"art. 11.4 del Reglamento","correcta":3,"justificaciones":["No: un año no es el período de vigencia de los planes estratégicos.","No: seis meses tampoco es el período de vigencia de los planes.","No: cuatro años no es el período, que son tres.","Correcta: los planes estratégicos prevén un período de vigencia de tres años, salvo que el sector aconseje otro (art. 11.4 del Reglamento)."],"revisar":"Dato del Reglamento (RD 887/2006), comprobado por web."},{"id":"pr-59-002","origen":"practicas","test":"Ejercicio 27.- Subvenciones en números","n":2,"enunciado":"El informe sobre el grado de avance de la aplicación del plan estratégico de subvenciones correspondiente, así como sus efectos y las repercusiones presupuestarias y financieras se emitirá antes del:","opciones":["31 de octubre de cada año.","30 de abril de cada año.","31 de diciembre de cada año.","30 de septiembre de cada año."],"bloque":"subv-general","precepto":"art. 14.2 del Reglamento","correcta":1,"justificaciones":["No: el 31 de octubre no es la fecha del informe de seguimiento.","Correcta: el informe sobre el grado de avance del plan se emite antes del 30 de abril de cada año (art. 14.2 del Reglamento).","No: el 31 de diciembre no es la fecha del informe de seguimiento.","No: el 30 de septiembre no es la fecha del informe de seguimiento."],"revisar":"Dato del Reglamento (RD 887/2006), comprobado por web."},{"id":"pr-59-003","origen":"practicas","test":"Ejercicio 27.- Subvenciones en números","n":3,"enunciado":"Requerirá autorización por acuerdo de El Consejo de Ministros la concesión de subvenciones de cuantía:","opciones":["Igual o superior a 12 millones de euros.","Superior a 10 millones de euros.","Igual o superior a 10 millones de euros.","Superior a 12 millones de euros."],"bloque":"subv-general","precepto":"art. 10.2","correcta":3,"justificaciones":["No: Igual o superior a 12 millones no es lo que establece art. 10.2.","No: Superior a 10 millones no es lo que establece art. 10.2.","No: Igual o superior a 10 millones no es lo que establece art. 10.2.","Correcta: la concesión de subvenciones de cuantía superior a 12 millones requiere autorización del Consejo de Ministros (art. 10.2)."],"ojo":"Con exactamente 12.000.000 no hace falta autorización: la ley dice “superior”."},{"id":"pr-59-004","origen":"practicas","test":"Ejercicio 27.- Subvenciones en números","n":4,"enunciado":"Los convenios de colaboración no podrán tener un plazo de vigencia superior a:","opciones":["1 año.","3 años.","4 años.","No viene determinado."],"bloque":"subv-general","precepto":"art. 16.2","correcta":2,"justificaciones":["No: 1 año no es lo que establece art. 16.2.","No: 3 años no es lo que establece art. 16.2.","Correcta: el convenio de colaboración no puede durar más de cuatro años, con prórrogas hasta un total de seis (art. 16.2).","No: Que no venga determinado no es lo que establece art. 16.2."]},{"id":"pr-59-005","origen":"practicas","test":"Ejercicio 27.- Subvenciones en números","n":5,"enunciado":"Plazo para presentar una solicitud de participación en una subvención en régimen de concurrencia competitiva:","opciones":["10 días hábiles.","15 días hábiles.","15 días naturales.","El que venga establecido en la convocatoria."],"bloque":"subv-concesion","precepto":"art. 23.2.g","correcta":3,"justificaciones":["No: 10 días hábiles no es lo que establece art. 23.2.g.","No: 15 días hábiles no es lo que establece art. 23.2.g.","No: 15 días naturales no es lo que establece art. 23.2.g.","Correcta: el plazo de presentación de solicitudes es el que fije la convocatoria (art. 23.2.g)."]},{"id":"pr-59-006","origen":"practicas","test":"Ejercicio 27.- Subvenciones en números","n":6,"enunciado":"Plazo para subsanaciones de la solicitud en una subvención en régimen de concurrencia competitiva:","opciones":["10 días prorrogables por 5 días más en determinados casos.","15 días.","10 días improrrogables.","5 días prorrogables por 5 días más en determinados casos."],"bloque":"subv-concesion","precepto":"art. 23.5","correcta":2,"justificaciones":["No: 10 días prorrogables por 5 días más no es lo que establece art. 23.5.","No: 15 días no es lo que establece art. 23.5.","Correcta: la subsanación se hace en el plazo máximo e improrrogable de 10 días (art. 23.5).","No: 5 días prorrogables por 5 días más no es lo que establece art. 23.5."]},{"id":"pr-59-007","origen":"practicas","test":"Ejercicio 27.- Subvenciones en números","n":7,"enunciado":"La propuesta de resolución provisional de los procedimientos de concurrencia competitiva deberá notificarse a los interesados, y se les concederá un plazo para presentar alegaciones de:","opciones":["15 días.","10 días.","1 mes.","20 días."],"bloque":"subv-concesion","precepto":"art. 24.4","correcta":1,"justificaciones":["No: 15 días no es lo que establece art. 24.4.","Correcta: se concede un plazo de 10 días para presentar alegaciones a la propuesta provisional (art. 24.4).","No: 1 mes no es lo que establece art. 24.4.","No: 20 días no es lo que establece art. 24.4."]},{"id":"pr-59-008","origen":"practicas","test":"Ejercicio 27.- Subvenciones en números","n":8,"enunciado":"El plazo máximo para resolver y notificar la resolución del procedimiento de concurrencia competitiva no podrá exceder de:","opciones":["12 meses.","3 meses.","6 meses.","9 meses."],"bloque":"subv-concesion","precepto":"art. 25.4","correcta":2,"justificaciones":["No: 12 meses no es lo que establece art. 25.4.","No: 3 meses no es lo que establece art. 25.4.","Correcta: el plazo máximo para resolver y notificar no puede exceder de seis meses, salvo ley o norma de la Unión Europea que fije otro (art. 25.4).","No: 9 meses no es lo que establece art. 25.4."]},{"id":"pr-59-009","origen":"practicas","test":"Ejercicio 27.- Subvenciones en números","n":9,"enunciado":"Cuando la normativa reguladora de una subvención permita la subcontratación sin indicar el porcentaje este no excederá de:","opciones":["El 20% del importe de la actividad subvencionada.","El 50% del importe de la actividad subvencionada.","Tiene que indicarlo la normativa reguladora.","El 70% del importe de la actividad subvencionada."],"bloque":"subv-concesion","precepto":"art. 29.2","correcta":1,"justificaciones":["No: El 20 % del importe de la actividad subvencionada no es lo que establece art. 29.2.","Correcta: si la normativa permite subcontratar sin indicar porcentaje, no se puede pasar del 50 % del importe de la actividad (art. 29.2).","No: Tiene que indicarlo la normativa reguladora no es lo que establece art. 29.2.","No: El 70 % del importe de la actividad subvencionada no es lo que establece art. 29.2."]},{"id":"pr-59-010","origen":"practicas","test":"Ejercicio 27.- Subvenciones en números","n":10,"enunciado":"La subcontratación se tendrá que celebrar por escrito y ser autorizada previamente por la entidad concedente de la subvención cuando:","opciones":["Exceda del 20% del importe de la subvención y dicho importe sea superior a 40.000 euros.","Exceda del 20% del importe de la subvención y dicho importe sea superior a 60.000 euros.","Exceda del 50% del importe de la subvención y dicho importe sea superior a 20.000 euros.","Exceda del 50% del importe de la subvención y dicho importe sea superior a 60.000 euros."],"bloque":"subv-concesion","precepto":"art. 29.3","correcta":1,"justificaciones":["No: Exceda del 20 % y supere 40.000 euros no es lo que establece art. 29.3.","Correcta: hace falta contrato por escrito y autorización previa del concedente cuando lo subcontratado excede del 20 % de la subvención y de 60.000 euros (art. 29.3).","No: Exceda del 50 % y supere 20.000 euros no es lo que establece art. 29.3.","No: Exceda del 50 % y supere 60.000 euros no es lo que establece art. 29.3."]},{"id":"pr-59-011","origen":"practicas","test":"Ejercicio 27.- Subvenciones en números","n":11,"enunciado":"A falta de previsión de las bases reguladoras del plazo de justificación este se realizará, como máximo en el plazo de:","opciones":["6 meses.","1 mes.","3 meses.","20 días."],"bloque":"subv-concesion","precepto":"art. 30.2","correcta":2,"justificaciones":["No: 6 meses no es lo que establece art. 30.2.","No: 1 mes no es lo que establece art. 30.2.","Correcta: sin previsión en las bases, la cuenta justificativa se presenta como máximo en tres meses desde que acaba el plazo de la actividad (art. 30.2).","No: 20 días no es lo que establece art. 30.2."]},{"id":"pr-59-012","origen":"practicas","test":"Ejercicio 27.- Subvenciones en números","n":12,"enunciado":"Quedan exonerados de la constitución de garantía, salvo previsión expresa en contrario en las bases reguladoras los beneficiarios de subvenciones concedidas por importe inferior a:","opciones":["3.000 euros.","6.000 euros.","1.000 euros.","10.000 euros."],"bloque":"subv-concesion","precepto":"art. 42.2.b del Reglamento","correcta":0,"justificaciones":["Correcta: quedan exonerados de garantía los beneficiarios de subvenciones por importe inferior a 3.000 euros (art. 42.2.b del Reglamento).","No: 6.000 euros no es lo que establece art. 42.2.b del Reglamento.","No: 1.000 euros no es lo que establece art. 42.2.b del Reglamento.","No: 10.000 euros no es lo que establece art. 42.2.b del Reglamento."],"revisar":"Dato del Reglamento (RD 887/2006, art. 42.2.b), comprobado por web."},{"id":"pr-59-013","origen":"practicas","test":"Ejercicio 27.- Subvenciones en números","n":13,"enunciado":"El interés de demora aplicable en materia de subvenciones será el interés legal del dinero:","opciones":["Incrementado un 20%.","Incrementado un 30%.","Incrementado un 25%.","Incrementado un 40%."],"bloque":"subv-reintegro","precepto":"art. 38.2","correcta":2,"justificaciones":["No: Incrementado un 20 % no es lo que establece art. 38.2.","No: Incrementado un 30 % no es lo que establece art. 38.2.","Correcta: el interés de demora es el interés legal del dinero incrementado en un 25 %, salvo que la Ley de Presupuestos fije otro (art. 38.2).","No: Incrementado un 40 % no es lo que establece art. 38.2."]},{"id":"pr-59-014","origen":"practicas","test":"Ejercicio 27.- Subvenciones en números","n":14,"enunciado":"El plazo máximo para resolver y notificar la resolución del procedimiento de reintegro no podrá exceder de:","opciones":["12 meses.","3 meses.","6 meses.","9 meses."],"bloque":"subv-reintegro","precepto":"art. 42.4","correcta":0,"justificaciones":["Correcta: el procedimiento de reintegro se resuelve y notifica en 12 meses desde el acuerdo de iniciación (art. 42.4).","No: 3 meses no es lo que establece art. 42.4.","No: 6 meses no es lo que establece art. 42.4.","No: 9 meses no es lo que establece art. 42.4."]},{"id":"pr-59-015","origen":"practicas","test":"Ejercicio 27.- Subvenciones en números","n":15,"enunciado":"El derecho de la Administración a reconocer o liquidar el reintegro prescribe en:","opciones":["1 año.","3 años.","5 años.","4 años."],"bloque":"subv-reintegro","precepto":"art. 39.1","correcta":3,"justificaciones":["No: 1 año no es lo que establece art. 39.1.","No: 3 años no es lo que establece art. 39.1.","No: 5 años no es lo que establece art. 39.1.","Correcta: el derecho a reconocer o liquidar el reintegro prescribe a los cuatro años (art. 39.1)."]},{"id":"pr-59-016","origen":"practicas","test":"Ejercicio 27.- Subvenciones en números","n":16,"enunciado":"Las actuaciones de control financiero sobre beneficiarios y, en su caso, entidades colaboradoras, deberán concluir en el plazo máximo de:","opciones":["18 meses.","3 meses.","6 meses.","12 meses."],"bloque":"subv-reintegro","precepto":"art. 49.7","correcta":3,"justificaciones":["No: 18 meses no es lo que establece art. 49.7.","No: 3 meses no es lo que establece art. 49.7.","No: 6 meses no es lo que establece art. 49.7.","Correcta: las actuaciones de control financiero concluyen en 12 meses desde la notificación de su inicio, ampliables hasta 12 más (art. 49.7)."]},{"id":"pr-59-017","origen":"practicas","test":"Ejercicio 27.- Subvenciones en números","n":17,"enunciado":"La sanción no pecuniaria de prohibición de actuar como entidad colaboradora podrá ser de máximo:","opciones":["1 año.","3 años.","5 años.","6 años."],"bloque":"subv-sanciones","precepto":"art. 59.3","correcta":2,"justificaciones":["No: 1 año no es lo que establece art. 59.3.","No: 3 años no es lo que establece art. 59.3.","Correcta: la sanción no pecuniaria puede durar hasta cinco años (art. 59.3).","No: 6 años no es lo que establece art. 59.3."]},{"id":"pr-59-018","origen":"practicas","test":"Ejercicio 27.- Subvenciones en números","n":18,"enunciado":"Las infracciones graves en materia de subvenciones prescribirán en el plazo de:","opciones":["4 años.","2 años.","3 años.","1 año."],"bloque":"subv-sanciones","precepto":"art. 65.1","correcta":0,"justificaciones":["Correcta: las infracciones prescriben a los cuatro años desde que se cometieron (art. 65.1).","No: 2 años no es lo que establece art. 65.1.","No: 3 años no es lo que establece art. 65.1.","No: 1 año no es lo que establece art. 65.1."]},{"id":"pr-59-019","origen":"practicas","test":"Ejercicio 27.- Subvenciones en números","n":19,"enunciado":"Las sanciones por infracción leve en materia de subvenciones prescribirán en el plazo de:","opciones":["1 años.","6 meses.","3 años.","4 años."],"bloque":"subv-sanciones","precepto":"art. 65.2","correcta":3,"justificaciones":["No: 1 año no es lo que establece art. 65.2.","No: 6 meses no es lo que establece art. 65.2.","No: 3 años no es lo que establece art. 65.2.","Correcta: las sanciones prescriben a los cuatro años desde el día siguiente a la firmeza, sea cual sea la gravedad (art. 65.2)."]},{"id":"pr-59-020","origen":"practicas","test":"Ejercicio 27.- Subvenciones en números","n":20,"enunciado":"El plazo máximo para resolver y notificar la resolución de un procedimiento sancionador en materia de subvenciones no podrá exceder de:","opciones":["12 meses.","6 meses.","3 meses.","9 meses."],"bloque":"subv-sanciones","precepto":"art. 102.1 del Reglamento","correcta":1,"justificaciones":["No: 12 meses no es lo que establece art. 102.1 del Reglamento.","Correcta: el plazo máximo para notificar la resolución del procedimiento sancionador es de seis meses (art. 102.1 del Reglamento).","No: 3 meses no es lo que establece art. 102.1 del Reglamento.","No: 9 meses no es lo que establece art. 102.1 del Reglamento."],"revisar":"Dato del Reglamento (RD 887/2006, art. 102.1), comprobado por web; la LGS no lo fija."},{"id":"pr-60-001","origen":"practicas","test":"Bloque III.- Supuesto 24","n":1,"enunciado":"De conformidad con la ley 39/2015, de 1 de octubre, ¿en qué fecha debe considerarse presentada la solicitud para la concesión de la subvención por la mercantil Siglo XXI S.L.?","opciones":["El 20 de diciembre de 2025, dentro del plazo concedido en la convocatoria.","El 20 de diciembre de 2025, por lo que debió inadmitirse por extemporánea.","El 1 de diciembre de 2025, dado que no existía obligación de relacionarse a través de medios electrónicos.","El 1 de diciembre de 2025, dado que se subsanó el defecto advertido dentro del plazo concedido."],"caso":"caso-60","bloque":"subv-concesion","precepto":"art. 68.4 Ley 39/2015","correcta":0,"justificaciones":["Correcta: una persona jurídica está obligada a relacionarse por medios electrónicos, y al requerirle la subsanación se considera presentada la solicitud el día en que se subsana, el 20 de diciembre, dentro del plazo (art. 68.4 de la Ley 39/2015).","No: el 20 de diciembre está dentro del plazo de un mes desde el 21 de noviembre, así que no hay extemporaneidad.","No: una sociedad mercantil sí está obligada a relacionarse electrónicamente con la Administración (art. 14.2.a).","No: la fecha no se retrotrae al 1 de diciembre; cuenta la de la subsanación."],"ojo":"El plazo de un mes desde el 21 de noviembre vence el 21 de diciembre, domingo, y pasa al lunes 22. El 20 de diciembre llega en plazo de todos modos."},{"id":"pr-60-002","origen":"practicas","test":"Bloque III.- Supuesto 24","n":2,"enunciado":"En el caso de que la solicitud presentada por Siglo XXI S.L. no reúna los requisitos establecidos en la convocatoria, el órgano competente requerirá al interesado para que la subsane según la Ley 38/2003 en el plazo de:","opciones":["Diez días improrrogables.","Diez días, ampliables hasta cinco días más, a petición del interesado.","Diez días, ampliables hasta cinco días más, a iniciativa del órgano.","Diez días, ampliables hasta cinco días más, a petición del interesado o a iniciativa del órgano."],"caso":"caso-60","bloque":"subv-concesion","precepto":"art. 23.5","correcta":0,"justificaciones":["Correcta: el plazo es de diez días, máximo e improrrogable (art. 23.5).","No: la ley no permite ampliar a petición del interesado.","No: tampoco permite ampliar por iniciativa del órgano.","No: no hay ampliación posible, ni a petición ni de oficio."],"ojo":"El requerimiento del enunciado daba cinco días, menos de los diez que fija la ley."},{"id":"pr-60-003","origen":"practicas","test":"Bloque III.- Supuesto 24","n":3,"enunciado":"De conformidad con lo dispuesto en la Ley 38/2003, de 17 de noviembre, General de Subvenciones (en adelante LGS), ¿es competente el Ministro de Cultura y Deporte para establecer las bases reguladoras de las subvenciones para la modernización de las industrias culturales y creativas?","opciones":["No, la aprobación de las bases reguladoras corresponde al Consejo de Ministros, mediante Real Decreto.","Sí, mediante orden ministerial.","No, su aprobación corresponde en todo caso al órgano concedente de la subvención.","Sí, aunque también pudieron ser aprobadas por resolución del Secretario de Estado de Cultura."],"caso":"caso-60","bloque":"subv-concesion","precepto":"art. 17.1","correcta":1,"justificaciones":["No: en la AGE las bases las aprueba el Ministro, no el Consejo de Ministros por real decreto.","Correcta: el Ministro establece las bases reguladoras mediante orden ministerial (art. 17.1).","No: la aprobación de las bases no corresponde al órgano concedente, sino al Ministro.","No: las bases no se aprueban por resolución de un Secretario de Estado."]},{"id":"pr-60-004","origen":"practicas","test":"Bloque III.- Supuesto 24","n":4,"enunciado":"De acuerdo con la LGS, en relación con la convocatoria y con las bases reguladores de la subvención, ¿son correctas las publicaciones realizadas en el BOE?","opciones":["No, solo deben publicarse en el BOE las bases reguladoras de la subvención.","No, solo debe publicarse en el BOE la convocatoria de la subvención.","No, dado que en el BOE se debió publicar la convocatoria de la subvención y no un mero extracto de la misma.","Sí, ambas publicaciones se han realizado de conformidad con lo dispuesto en la LGS."],"caso":"caso-60","bloque":"subv-concesion","precepto":"arts. 9.3 y 23.2","correcta":3,"justificaciones":["No: también se publica en el BOE el extracto de la convocatoria.","No: las bases reguladoras también se publican en el BOE.","No: lo que se publica en el BOE es un extracto de la convocatoria; el texto completo va a la BDNS (art. 23.2).","Correcta: las bases se publican en el BOE (art. 9.3) y de la convocatoria, el extracto (art. 23.2)."]},{"id":"pr-60-005","origen":"practicas","test":"Bloque III.- Supuesto 24","n":5,"enunciado":"Las bases reguladoras determinan que el órgano concedente es el Secretario de Estado de Cultura. Según la LGS, en el ámbito de la AGE, ¿qué órganos son competentes para conceder subvenciones?","opciones":["El Consejo de Ministros.","Los Ministros y los Secretarios de Estado.","El Consejo de Ministros, los Ministros y los Secretarios de Estado.","Los Ministros, exclusivamente."],"caso":"caso-60","bloque":"subv-concesion","precepto":"art. 10.1","correcta":1,"justificaciones":["No: el Consejo de Ministros no concede, solo autoriza las de más de 12 millones.","Correcta: son órganos concedentes los Ministros y los Secretarios de Estado (art. 10.1).","No: el Consejo de Ministros no figura como órgano concedente.","No: no son solo los Ministros, también los Secretarios de Estado."]},{"id":"pr-60-006","origen":"practicas","test":"Bloque III.- Supuesto 24","n":6,"enunciado":"De acuerdo con la LGS, ¿requiere la concesión de estas subvenciones la previa autorización del Consejo de Ministros?","opciones":["No, porque su cuantía no es superior a 12.000.000 euros.","Sí, resulta necesaria e implicará la aprobación del gasto.","Sí, resulta necesaria pero la referida autorización no implicará la aprobación del gasto.","Sí, aunque la normativa reguladora de la subvención podría establecer que dicha la autorización fuera otorgada por la Comisión Delegada del Gobierno para Asuntos Económicos."],"caso":"caso-60","bloque":"subv-concesion","precepto":"art. 10.2","correcta":0,"justificaciones":["Correcta: la autorización se exige para subvenciones de cuantía superior a 12 millones, y la convocatoria es de 12.000.000, que no la supera (art. 10.2).","No: no es necesaria, y aunque lo fuera, la autorización no implicaría la aprobación del gasto.","No: no es necesaria porque la cuantía no supera 12 millones.","No: no es necesaria; la Comisión Delegada solo sustituye al Consejo de Ministros cuando sí hace falta."]},{"id":"pr-60-007","origen":"practicas","test":"Bloque III.- Supuesto 24","n":7,"enunciado":"Según la LGS, ¿en qué momento debe efectuarse la aprobación del gasto?","opciones":["Con anterioridad a la publicación de las bases reguladoras.","Con carácter previo a la convocatoria de la subvención.","Conjuntamente con la convocatoria de la subvención.","En cualquier momento anterior a la concesión de la subvención."],"caso":"caso-60","bloque":"subv-concesion","precepto":"art. 34.1","correcta":1,"justificaciones":["No: la aprobación del gasto no precede a las bases.","Correcta: con carácter previo a la convocatoria o a la concesión directa (art. 34.1).","No: no puede ir al mismo tiempo, tiene que ser previa.","No: no basta con cualquier momento anterior a la concesión, tiene que ser previa a la convocatoria."]},{"id":"pr-60-008","origen":"practicas","test":"Bloque III.- Supuesto 24","n":8,"enunciado":"Indique cuál de las siguientes circunstancias inhabilita para obtener la condición de beneficiario, de acuerdo con lo previsto en el artículo 13 de la LGS:","opciones":["Haber obtenido cualquier otra subvención o ayuda pública para la misma finalidad.","Tener la residencia fiscal en un país o territorio extranjero.","Haber solicitado la declaración de concurso voluntario.","Haber sido parte en un contrato del sector público extinguido por cualquier causa de resolución."],"caso":"caso-60","bloque":"subv-general","precepto":"art. 13.2.b","correcta":2,"justificaciones":["No: haber obtenido otras ayudas no inhabilita, solo hay que comunicarlo.","No: la prohibición es por residencia fiscal en un paraíso fiscal, no en cualquier país extranjero (art. 13.2.f).","Correcta: haber solicitado la declaración de concurso voluntario inhabilita (art. 13.2.b).","No: la prohibición es haber dado lugar, por causa de la que fueron declarados culpables, a la resolución firme de un contrato, y el enunciado dice “por cualquier causa” (art. 13.2.c)."]},{"id":"pr-60-009","origen":"practicas","test":"Bloque III.- Supuesto 24","n":9,"enunciado":"De acuerdo con la LGS, el procedimiento para la concesión de esta subvención se inicia:","opciones":["De oficio, mediante convocatoria aprobada por el órgano competente.","De oficio, mediante la publicación de las bases reguladoras.","De oficio, una vez publicado el extracto de la convocatoria en la BDNS.","A petición de los interesados, mediante solicitud dirigida al órgano concedente."],"caso":"caso-60","bloque":"subv-concesion","precepto":"art. 23.1 y 23.2","correcta":0,"justificaciones":["Correcta: el procedimiento se inicia siempre de oficio, mediante convocatoria aprobada por el órgano competente (art. 23).","No: no se inicia con la publicación de las bases.","No: no se inicia con el extracto en la BDNS, sino con la convocatoria.","No: no se inicia a petición de los interesados."]},{"id":"pr-60-010","origen":"practicas","test":"Bloque III.- Supuesto 24","n":10,"enunciado":"De conformidad con la LGS, ¿en cuál de los siguientes supuestos podría el Ministerio de Cultura conceder una subvención de forma directa?","opciones":["Únicamente, cuando estuviera prevista nominativamente en los Presupuestos Generales del Estado.","Con carácter excepcional, cuando se acrediten razones debidamente justificadas que dificulten su convocatoria pública.","Únicamente cuando se trate de ayudas otorgadas en ejecución de acciones de discriminación positiva.","Cuando su otorgamiento o cuantía venga impuesto por una norma de rango legal o reglamentario."],"caso":"caso-60","bloque":"subv-concesion","precepto":"art. 22.2","correcta":1,"justificaciones":["No: la concesión directa no se limita a las nominativas (art. 22.2).","Correcta: excepcionalmente, si se acreditan razones de interés público, social, económico o humanitario que dificulten la convocatoria (art. 22.2.c).","No: las acciones de discriminación positiva no son un supuesto legal de concesión directa.","No: la ley exige una norma de rango legal, no reglamentario (art. 22.2.b)."]},{"id":"pr-60-011","origen":"practicas","test":"Bloque III.- Supuesto 24","n":11,"enunciado":"Teniendo en cuenta que la convocatoria no pospone el inicio del cómputo de plazos, indiqué cuál será la fecha máxima para resolver y notificar la resolución de concesión de la subvención que tramita el Ministerio de Cultura y Deporte:","opciones":["1 de junio de 2026.","13 de abril de 2026.","21 de mayo de 2026.","20 de junio de 2026."],"caso":"caso-60","bloque":"subv-concesion","precepto":"art. 25.4","correcta":2,"justificaciones":["No: el 1 de junio de 2026 no sale de contar seis meses desde la publicación.","No: el 13 de abril de 2026 se sale contando desde la orden de bases (13 de octubre), que no es la convocatoria.","Correcta: seis meses desde la publicación de la convocatoria el 21 de noviembre de 2025 vencen el 21 de mayo de 2026 (art. 25.4).","No: el 20 de junio de 2026 se saldría contando desde la resolución de convocatoria, no desde su publicación."],"ojo":"El plazo se cuenta desde la publicación de la convocatoria, no desde la fecha de la orden de bases ni de la resolución de convocatoria."},{"id":"pr-60-012","origen":"practicas","test":"Bloque III.- Supuesto 24","n":12,"enunciado":"De acuerdo con la LGS, en este procedimiento, el vencimiento del plazo máximo sin haberse notificado la resolución:","opciones":["Produce la caducidad del procedimiento.","Determina la prescripción del procedimiento.","Legitima a los interesados para entender estimada su solicitud por silencio administrativo.","Legitima a los interesados para entender desestimada su solicitud por silencio administrativo."],"caso":"caso-60","bloque":"subv-concesion","precepto":"art. 25.5","correcta":3,"justificaciones":["No: no se produce caducidad en el procedimiento de concesión.","No: la prescripción no es la consecuencia del silencio.","No: el silencio es negativo, no estimatorio.","Correcta: el vencimiento del plazo sin notificar legitima para entender desestimada la solicitud (art. 25.5)."]},{"id":"pr-60-013","origen":"practicas","test":"Bloque III.- Supuesto 24","n":13,"enunciado":"Frente a la resolución definitiva de concesión de la subvención, ¿qué recurso podría interponer Siglo XXI S.L. en vía administrativa?","opciones":["Recurso de alzada, en el plazo de un mes.","Recurso potestativo de reposición, en el plazo de un mes.","Recurso de alzada, en el plazo de tres meses.","No cabría recurso en vía administrativa."],"caso":"caso-60","bloque":"subv-concesion","precepto":"art. 23.2.k y arts. 121 y 122 Ley 39/2015","correcta":0,"justificaciones":["Correcta: la resolución la dicta un Secretario de Estado, que tiene superior jerárquico, así que cabe recurso de alzada en el plazo de un mes (arts. 121 y 122 de la Ley 39/2015).","No: el recurso de reposición solo cabe contra actos que agoten la vía administrativa.","No: el plazo de la alzada es de un mes, no de tres.","No: sí cabe recurso en vía administrativa."],"revisar":"La convocatoria debe indicar si la resolución pone fin a la vía administrativa (art. 23.2.k); sin esa información, se responde alzada porque el Secretario de Estado tiene al Ministro como superior."},{"id":"pr-60-014","origen":"practicas","test":"Bloque III.- Supuesto 24","n":14,"enunciado":"¿Podría la Mercantil Siglo XXI S.L. subcontratar la actividad subvencionada?","opciones":["Sí, en cualquier caso.","No, en ningún caso.","Únicamente cuando la normativa reguladora de la subvención así lo prevea.","No, salvo autorización expresa del órgano concedente."],"caso":"caso-60","bloque":"subv-concesion","precepto":"art. 29.2","correcta":2,"justificaciones":["No: no siempre se puede subcontratar.","No: sí se puede, si la normativa lo prevé.","Correcta: solo cuando la normativa reguladora de la subvención lo prevea (art. 29.2).","No: no basta la autorización expresa del órgano concedente si la normativa no lo prevé."]},{"id":"pr-60-015","origen":"practicas","test":"Bloque III.- Supuesto 24","n":15,"enunciado":"En la ejecución de la actividad subvencionada la Mercantil Siglo XXI S.L. ha incurrido en distintos gastos. De los siguientes, ¿cuál podría considerarse subvencionable por la normativa reguladora de la subvención?","opciones":["Excepcionalmente, los intereses deudores de las cuentas bancarias.","Los impuestos personales sobre la renta.","Excepcionalmente, los gastos de procedimientos judiciales.","Excepcionalmente, los gastos de garantía bancaria."],"caso":"caso-60","bloque":"subv-concesion","precepto":"art. 31.7","correcta":3,"justificaciones":["No: los intereses deudores de las cuentas bancarias nunca son subvencionables (art. 31.7.a).","No: los impuestos personales sobre la renta nunca son subvencionables (art. 31.8).","No: los gastos de procedimientos judiciales nunca son subvencionables (art. 31.7.c).","Correcta: los gastos de garantía bancaria pueden subvencionarse con carácter excepcional si lo prevé la normativa reguladora (art. 31.7)."]},{"id":"pr-60-016","origen":"practicas","test":"Bloque III.- Supuesto 24","n":16,"enunciado":"De acuerdo con la LGS, a falta de previsión expresa en las bases reguladoras, la presentación de la cuenta justificativa se realizará, como máximo, en el plazo de:","opciones":["Tres meses desde la finalización del plazo para la realización de la actividad.","Seis meses desde la finalización del plazo para la realización de la actividad.","Tres meses desde la notificación de la resolución de concesión.","Seis meses desde la notificación de la resolución de concesión."],"caso":"caso-60","bloque":"subv-concesion","precepto":"art. 30.2","correcta":0,"justificaciones":["Correcta: tres meses desde que acaba el plazo para realizar la actividad (art. 30.2).","No: el plazo no es de seis meses, sino de tres desde el fin de la actividad.","No: se cuenta desde el fin del plazo de la actividad, no desde la notificación de la resolución.","No: ni seis meses ni desde la notificación."]},{"id":"pr-60-017","origen":"practicas","test":"Bloque III.- Supuesto 24","n":17,"enunciado":"¿Con qué fase de ejecución del gasto se corresponde la resolución de la concesión de la subvención?","opciones":["La retención del crédito.","El reconocimiento de la obligación.","El compromiso del gasto.","La aprobación del gasto."],"caso":"caso-60","bloque":"subv-concesion","precepto":"art. 34.2","correcta":2,"justificaciones":["No: la retención de crédito es anterior.","No: el reconocimiento de la obligación viene después, con el pago.","Correcta: la resolución de concesión conlleva el compromiso del gasto (art. 34.2).","No: la aprobación del gasto va antes de la convocatoria (art. 34.1)."]},{"id":"pr-60-018","origen":"practicas","test":"Bloque III.- Supuesto 24","n":18,"enunciado":"¿Cuál de las siguientes constituiría, en su caso, causa de nulidad de la resolución de concesión?","opciones":["El incumplimiento por la beneficiaria de la obligación de justificación.","La carencia o insuficiencia de crédito.","El incumplimiento por la beneficiaria de la actividad subvencional.","El incumplimiento de la obligación de adoptar las medidas de difusión del carácter público de la financiación."],"caso":"caso-60","bloque":"subv-concesion","precepto":"art. 36.1.b","correcta":1,"justificaciones":["No: incumplir la justificación es causa de reintegro, no de nulidad (art. 37.1.c).","Correcta: la carencia o insuficiencia de crédito es causa de nulidad de la resolución (art. 36.1.b).","No: incumplir la actividad es causa de reintegro (art. 37.1.b).","No: no adoptar medidas de difusión es causa de reintegro (art. 37.1.d)."]},{"id":"pr-60-019","origen":"practicas","test":"Bloque III.- Supuesto 24","n":19,"enunciado":"En caso de que la resolución de concesión se viera afectada por una causa de nulidad, ¿cómo debería proceder la Administración?","opciones":["Revocando la resolución de concesión, sin necesidad de recabar dictamen previo del Consejo de Estado.","Declararando la nulidad de la resolución de concesión, previo dictamen favorable del Consejo de Estado.","Impugnando la resolución ante el orden jurisdiccional contencioso-administrativo, previa su declaración de lesividad para el interés público.","Rectificando o convalidando la resolución de concesión."],"caso":"caso-60","bloque":"subv-concesion","precepto":"art. 36.3","correcta":1,"justificaciones":["No: la nulidad no se corrige revocando, sino mediante revisión de oficio.","Correcta: debe declarar la nulidad por revisión de oficio, con dictamen favorable del Consejo de Estado (art. 36.3 de la LGS y art. 106 de la Ley 39/2015).","No: la declaración de lesividad es para actos anulables, no para los nulos.","No: rectificar o convalidar no vale para un acto nulo."],"ojo":"Las referencias a los arts. 102 y 103 de la Ley 30/1992 del texto de la LGS equivalen hoy a los arts. 106 y 107 de la Ley 39/2015."},{"id":"pr-60-020","origen":"practicas","test":"Bloque III.- Supuesto 24","n":20,"enunciado":"Si la administración incurre en causa de nulidad, pero se da cuenta que el interesado había obtenido la subvención falseando las condiciones requeridas para ello, como deberá proceder:","opciones":["Realizara una anulación de oficio, pero iniciara a la vez un expediente sancionador.","Impugnará el acto, pero le exigirá al interesado el interés de demora incrementando un 25%.","Iniciará un procedimiento de reintegro, sin perjuicio de poder iniciar además un expediente sancionador.","Iniciará expediente sancionador por falta grave."],"caso":"caso-60","bloque":"subv-reintegro","precepto":"art. 36.5 y 37.1.a","correcta":2,"justificaciones":["No: no procede la revisión de oficio cuando hay causa de reintegro (art. 36.5).","No: no se impugna el acto ni se exige un interés incrementado así.","Correcta: obtener la subvención falseando las condiciones es causa de reintegro, y puede además haber expediente sancionador (arts. 36.5 y 37.1.a).","No: el falseamiento para obtenerla es infracción muy grave, no grave (art. 58.a), y además hay reintegro."]},{"id":"pr-60-021","origen":"practicas","test":"Bloque III.- Supuesto 24","n":21,"enunciado":"En caso de que la Mercantil Siglo XXI S.L. incumpliera la obligación de justificar el cumplimiento de las condiciones impuestas, ¿en qué plazo prescribiría el derecho de la Administración para reconocer el reintegro?","opciones":["A los cinco años, desde el momento en que venció el plazo para presentar la justificación.","A los cuatro años, desde la publicación de la convocatoria de concesión de la subvención.","A los cinco años, desde la publicación de la convocatoria de concesión de la subvención.","A los cuatro años, desde el momento en que venció el plazo para presentar la justificación."],"caso":"caso-60","bloque":"subv-reintegro","precepto":"art. 39","correcta":3,"justificaciones":["No: el plazo es de cuatro años, no cinco.","No: no se cuenta desde la publicación de la convocatoria.","No: ni cinco años ni desde la convocatoria.","Correcta: prescribe a los cuatro años desde que venció el plazo para presentar la justificación (art. 39.1 y 39.2.a)."]},{"id":"pr-60-022","origen":"practicas","test":"Bloque III.- Supuesto 24","n":22,"enunciado":"¿Qué órgano sería competente, en su caso, para exigir el reintegro de la subvención otorgada a Siglo XXI S.L.?","opciones":["El Ministro de Cultura y Deporte.","El Secretario de Estado de Cultura.","El Titular del Ministerio de Hacienda.","El Subdirector General de Promoción de Industrias Culturales."],"caso":"caso-60","bloque":"subv-reintegro","precepto":"art. 41.1","correcta":1,"justificaciones":["No: el Ministro no es el concedente.","Correcta: exige el reintegro el órgano concedente, que es el Secretario de Estado de Cultura (art. 41.1).","No: el Ministerio de Hacienda no resuelve reintegros de estas subvenciones.","No: el subdirector general solo tramita."]},{"id":"pr-60-023","origen":"practicas","test":"Bloque III.- Supuesto 24","n":23,"enunciado":"De acuerdo con el artículo 42 de la LGS, el plazo máximo para resolver y notificar la resolución del procedimiento de reintegro será, desde la fecha del acuerdo de iniciación, de:","opciones":["6 meses, transcurridos los cuales se producirá la caducidad del procedimiento.","12 meses, transcurridos los cuales se producirá la caducidad del procedimiento.","6 meses, transcurridos los cuales prescribirá el derecho de la Administración a exigir el reintegro.","12 meses, transcurridos los cuales prescribirá el derecho de la Administración a exigir el reintegro."],"caso":"caso-60","bloque":"subv-reintegro","precepto":"art. 42.4","correcta":1,"justificaciones":["No: el plazo es de doce meses, no de seis.","Correcta: doce meses desde el acuerdo de iniciación, con caducidad si se supera (art. 42.4).","No: ni seis meses ni prescripción.","No: el efecto de pasarse del plazo es la caducidad, no la prescripción."]},{"id":"pr-60-024","origen":"practicas","test":"Bloque III.- Supuesto 24","n":24,"enunciado":"Tras el otorgamiento de la subvención y durante la ejecución de la actividad subvencionada, la mercantil Siglo XXI S.L. obtuvo otra subvención, procedente de la Administración local, para financiar la misma actividad. Sin embargo, como la suma de ambas subvenciones (la estatal y la local) no superaba el coste de la actividad subvencionada decidió no comunicarlo al Ministerio de Cultura. Según la LGS, ¿podría haberse incurrido en la comisión de alguna infracción en materia de subvenciones?","opciones":["Sí, de carácter muy grave.","Sí, de carácter grave.","Sí, de carácter leve.","No, dado que la suma de ambas subvenciones no superan el coste de la actividad subvencionada."],"caso":"caso-60","bloque":"subv-sanciones","precepto":"art. 57.a","correcta":1,"justificaciones":["No: no llega a muy grave, que exige conductas como falsear condiciones o no aplicar los fondos.","Correcta: no comunicar la obtención de otras ayudas para la misma finalidad es infracción grave (art. 57.a).","No: no es leve, está tipificada como grave.","No: aunque la suma no supere el coste, la omisión de comunicarlo ya es infracción."]},{"id":"pr-60-025","origen":"practicas","test":"Bloque III.- Supuesto 24","n":25,"enunciado":"De acuerdo con la LGS, ¿en qué plazo prescribiría la infracción a que se refiere la pregunta anterior?","opciones":["Un año, a contar desde el día en que la infracción se hubiera cometido.","Tres años, a contar desde el día en que la infracción se hubiera cometido.","Cuatro años, a contar desde el día en que la infracción se hubiera cometido.","Al no existir comisión de infracción, no resultaría aplicable ningún plazo de prescripción."],"caso":"caso-60","sigueA":"pr-60-024","bloque":"subv-sanciones","precepto":"art. 65.1","correcta":2,"justificaciones":["No: la prescripción no es de un año.","No: el plazo de prescripción no es de tres años, sino de cuatro.","Correcta: las infracciones prescriben a los cuatro años desde que se cometieron (art. 65.1).","No: sí hay infracción, así que se aplica el plazo de prescripción."]},{"id":"pr-66-020","origen":"practicas","test":"Ley 39 + Contratos - Examen teórico (70 preguntas)","n":20,"enunciado":"Conforme a lo dispuesto en el artículo 42 de la Ley 38/2003, de 17 de noviembre, General de Subvenciones (en adelante LGS), el plazo máximo para resolver y notificar la resolución del procedimiento de reintegro es de:","opciones":["4 años desde la fecha del acuerdo de iniciación.","6 meses desde la fecha del acuerdo de iniciación.","3 meses desde la fecha del acuerdo de iniciación.","12 meses desde la fecha del acuerdo de iniciación."],"bloque":"subv-reintegro","precepto":"art. 42.4 LGS","correcta":3,"justificaciones":["No: cuatro años es el plazo de prescripción del derecho a reconocer o liquidar el reintegro, no el de resolución.","No: seis meses es el plazo para resolver el procedimiento de concesión (art. 25.4), no el de reintegro.","No: tres meses no es el plazo de reintegro.","Correcta: el plazo máximo para resolver y notificar el reintegro es de 12 meses desde el acuerdo de iniciación (art. 42.4)."]},{"id":"pr-66-021","origen":"practicas","test":"Ley 39 + Contratos - Examen teórico (70 preguntas)","n":21,"enunciado":"Conforme a las previsiones de la LGS, señale la respuesta incorrecta:","opciones":["El otorgamiento de una subvención requiere la aprobación del gasto por el órgano competente para ello.","Las bases reguladoras de cada tipo de subvención se publicarán en el diario oficial correspondiente.","Con carácter previo al otorgamiento de las subvenciones, deberán aprobarse las normas que establezcan las bases reguladoras.","La autorización previa del Consejo de Ministros, en los casos en que resulte necesaria, implicará la aprobación del gasto."],"bloque":"subv-concesion","precepto":"arts. 10.2, 17 y 34 LGS","correcta":3,"justificaciones":["No es la incorrecta: el gasto se aprueba con carácter previo a la convocatoria o a la concesión directa (art. 34.1).","No es la incorrecta: las bases se publican en el diario oficial (art. 17.1).","No es la incorrecta: las bases reguladoras deben aprobarse antes de otorgar las subvenciones (art. 17).","Correcta (es la incorrecta): la autorización del Consejo de Ministros no implica la aprobación del gasto, que corresponde en todo caso al órgano competente (art. 10.2)."]},{"id":"pr-66-022","origen":"practicas","test":"Ley 39 + Contratos - Examen teórico (70 preguntas)","n":22,"enunciado":"En los procedimientos de concesión de subvenciones, ¿puede el órgano competente proceder al prorrateo, entre los beneficiarios de la subvención, del importe global máximo destinado a las subvenciones?","opciones":["Excepcionalmente, siempre que así se prevea en las bases reguladoras.","Excepcionalmente, cuando lo considere adecuado para una mejor distribución de las subvenciones.","Sí, con carácter general. salvo que las bases reguladoras lo prohíban expresamente.","El prorrateo solo será posible en subvenciones de carácter nominativo."],"bloque":"subv-concesion","precepto":"art. 22.1 LGS","correcta":0,"justificaciones":["Correcta: el prorrateo es excepcional y solo si lo prevén las bases reguladoras (art. 22.1).","No: no basta que el órgano lo considere adecuado, hace falta que lo prevean las bases.","No: no es la regla general, es excepcional.","No: el prorrateo es una técnica de la concurrencia competitiva, no de las subvenciones nominativas."]},{"id":"pr-66-023","origen":"practicas","test":"Ley 39 + Contratos - Examen teórico (70 preguntas)","n":23,"enunciado":"De acuerdo con el artículo 42 de la LGS, señale la respuesta correcta respecto al procedimiento de reintegro:","opciones":["Podrá iniciarse de oficio o por solicitud de persona interesada.","El plazo máximo para resolver y notificar la resolución será de 6 meses desde la fecha del acuerdo de iniciación.","La resolución del procedimiento pondrá fin a la vía administrativa.","Contra la resolución que se dicte no cabrá recurso en vía administrativa."],"bloque":"subv-reintegro","precepto":"art. 42 LGS","correcta":2,"justificaciones":["No: el reintegro se inicia siempre de oficio (art. 42.2), no a solicitud de persona interesada.","No: el plazo es de 12 meses, no de 6 (art. 42.4).","Correcta: la resolución del procedimiento de reintegro pone fin a la vía administrativa (art. 42.5).","No: al poner fin a la vía administrativa cabe recurso potestativo de reposición o contencioso-administrativo."]},{"id":"pr-66-024","origen":"practicas","test":"Ley 39 + Contratos - Examen teórico (70 preguntas)","n":24,"enunciado":"Según el artículo 2 de la LGS, se entiende por subvención toda disposición dineraria realizada por una Administración Pública, a favor de personas públicas o privadas, que cumpla, entre otros, el siguiente requisito:","opciones":["Que la entrega se realice con contraprestación directa de los beneficiarios.","Que no se exija al beneficiario el cumplimiento de obligaciones materiales o formales.","Que la entrega se realice sin contraprestación directa de los beneficiarios.","Que el proyecto, la acción, conducta o situación financiada tenga por objeto el fomento de una actividad de utilidad privada."],"bloque":"subv-general","precepto":"art. 2.1.a LGS","correcta":2,"justificaciones":["No: la entrega se realiza sin contraprestación directa, no con ella.","No: al beneficiario se le exige cumplir obligaciones materiales y formales (art. 2.1.b).","Correcta: la entrega se realiza sin contraprestación directa de los beneficiarios (art. 2.1.a).","No: el fin es una actividad de utilidad pública o interés social, no de utilidad privada (art. 2.1.c)."]},{"id":"pr-66-025","origen":"practicas","test":"Ley 39 + Contratos - Examen teórico (70 preguntas)","n":25,"enunciado":"Según el artículo 34 de la LGS, la resolución de concesión de la subvención conllevará:","opciones":["La aprobación del gasto","El compromiso del gasto.","El reconocimiento de la obligación.","La propuesta de pago."],"bloque":"subv-concesion","precepto":"art. 34.2 LGS","correcta":1,"justificaciones":["No: la aprobación del gasto es previa a la convocatoria o a la concesión directa.","Correcta: la resolución de concesión conlleva el compromiso del gasto correspondiente (art. 34.2).","No: el reconocimiento de la obligación llega después, con la justificación.","No: la propuesta de pago llega después, con la justificación."]},{"id":"pr-66-026","origen":"practicas","test":"Ley 39 + Contratos - Examen teórico (70 preguntas)","n":26,"enunciado":"De acuerdo con el artículo 25.5 de la LGS, el vencimiento del plazo máximo sin haberse notificado la resolución de concesión de la subvención legitima a los interesados para:","opciones":["Entender estimada su pretensión por silencio administrativo.","Entender desestimada su pretensión por silencio administrativo.","Considerar caducado el procedimiento.","Considerar prescrito su derecho."],"bloque":"subv-concesion","precepto":"art. 25.5 LGS","correcta":1,"justificaciones":["No: en subvenciones el silencio es desestimatorio, no estimatorio.","Correcta: el vencimiento del plazo sin notificar legitima para entender desestimada la solicitud por silencio administrativo (art. 25.5).","No: en un procedimiento iniciado a solicitud la consecuencia es el silencio, no la caducidad.","No: no se trata de prescripción de ningún derecho."]},{"id":"pr-66-027","origen":"practicas","test":"Ley 39 + Contratos - Examen teórico (70 preguntas)","n":27,"enunciado":"Según la LGS, cuando proceda el reintegro de una subvención, se exigirá el interés de demora correspondiente, calculado:","opciones":["Desde el momento de la concesión de la subvención hasta la fecha en que se acuerde el reintegro.","Desde el momento de la concesión de la subvención hasta la fecha en que en que el deudor ingrese el reintegro.","Desde el momento del pago de la subvención hasta la fecha en que se acuerde el reintegro.","Desde el momento del pago de la subvención hasta la fecha en que se inicie el procedimiento de reintegro."],"bloque":"subv-reintegro","precepto":"art. 37.1 LGS","correcta":2,"justificaciones":["No: el interés se cuenta desde el pago, no desde la concesión.","No: se cuenta desde el pago y no desde la concesión.","Correcta: desde el momento del pago hasta la fecha en que se acuerde la procedencia del reintegro (art. 37.1).","No: el interés no se corta al iniciarse el procedimiento, sino al acordarse el reintegro."],"ojo":"La ley añade: o hasta la fecha en que el deudor ingrese el reintegro, si es anterior."},{"id":"pr-66-028","origen":"practicas","test":"Ley 39 + Contratos - Examen teórico (70 preguntas)","n":28,"enunciado":"Según la LGS, quedan incluidas dentro de su ámbito de aplicación, teniendo carácter de subvención:","opciones":["Los premios que se otorguen sin la previa solicitud del beneficiario.","Las prestaciones contributivas y no contributivas del Sistema de la Seguridad Social.","Una ayuda social concedida por un Ayuntamiento para la atención especializada a personas con diversidad funcional.","Los beneficios fiscales y beneficios en la cotización a la Seguridad Social."],"bloque":"subv-general","precepto":"arts. 2.4 y 4 LGS","correcta":2,"justificaciones":["No: los premios sin solicitud previa quedan excluidos del ámbito de la Ley (art. 4).","No: las prestaciones de la Seguridad Social no tienen carácter de subvención (art. 2.4.a).","Correcta: una ayuda social municipal para atención especializada cumple el concepto del art. 2.1 y no está en las exclusiones del art. 2.4.","No: los beneficios fiscales y en la cotización no tienen carácter de subvención (art. 2.4.g)."]},{"id":"pr-68-010","origen":"practicas","test":"Ley 39 + Contratos - Examen teórico (30 preguntas)","n":10,"enunciado":"Según el artículo 2.4 de la Ley 38/2003, General de Subvenciones, no tienen carácter de subvenciones: (ADM-LI 2026)","opciones":["Las otorgadas como consecuencia de la Política Agrícola Común.","Las que financien proyectos relacionados con la ciencia y la tecnología.","Los beneficios fiscales y beneficios en la cotización a la Seguridad Social.","Las destinadas a fomentar actividades de interés social."],"bloque":"subv-general","precepto":"art. 2.4.g LGS","correcta":2,"justificaciones":["No: la Ley no excluye las ayudas de la PAC de ese artículo.","No: financiar ciencia y tecnología puede ser subvención.","Correcta: los beneficios fiscales y en la cotización a la Seguridad Social no tienen carácter de subvención (art. 2.4.g).","No: fomentar actividades de interés social es el fin típico de una subvención (art. 2.1.c)."]}]});
